/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150120-6","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"区民委員会","time":"午後 １時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「第４０回消費生活展・第７回社会貢献活動しながわ」の開催","agenda":"はじめに、(1)「第４０回消費生活展・第７回社会貢献活動しながわ」の開催","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"実行委員会の発意で一緒にやったらどうかというようなことなのか、そこら辺は参加をしている人たちにもいろいろあるのかなと思うのですが、ちょっと教えていただきたい。","respondent":"米田商業・観光課長","answer":"どちらかというと会場の狭さということがあったのが１点と、消費生活展に比べて来場者数も少なかったりというようなことがありました。現状として見えない部分もあるのですけれど、そういうものを少しでも解消しながらということで、今まで組み立ててきているものです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺は当事者の方たちがどう思うかというのは、分散させられてしまう、ぜひ当事者の方たちのご意見の把握をきちっとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"それと、今回同じ日に同じ場所でやるということで、来場者数は増えると見込んでいるのかどうか。そこら辺をちょっと、もくろみというのでしょうか、教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"日曜日については例年どおり入ったということですが、去年の数字は２,０００人を割り込みました。それから、あるいは社会貢献活動であったりのイベントものも少し増やしたりしていますので、そういった意味では来場者数は増えるものと考えています。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひともそういう意味では来場者も増えて、大成功の開催にしていってほしいと求めました。実際にこれまでにそういう団体同士がコラボというのでしょうか、特徴的なものがもし過去にあったならば教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"中に出られている企業と地域活動をしている団体が連携して、またその両方で一緒になって新たな、過去において聞いてあります。ここに出ている観光協会と清泉女子大学の連携による観光事業の取り組みとか、そちらがやっている活動を自分もやってみようとかいうようなことで。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"区のここへ出てくるところというのは、どういうふうなスタンスで出ましょうというふうに、何かあるのかなというのをちょっと参考までにということと。なかなか人材的に難しいので１日でいいですというような、中はどういうふうに、実行委員会の中の議論というのをちょっと紹介ほしいと求めました。","respondent":"米田商業・観光課長","answer":"今まで１日だったので、どちらかというととりあえず１日発表できればいいというようなご意向が強いということで聞いています。そういった意味では、出展のご意向調整というのは実行委員会でやっておりますけれども、十分念入りな団体間の調整は図れているものと考えています。","id":"exchange-005"}]},{"id":"topic-02","title":"第１１回品川区新製品・新技術クラスターフェアの開催","agenda":"第１１回品川区新製品・新技術クラスターフェアの開催","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"クラスターフェアというのはもう１１回ということですけれど、毎回どれぐらいの参加者なのかということと、どういう方を対象にこれがされるのか、またこのリーフレットもありますけれど、これはどういうところに、どういう形でＰＲをするのかというところを説明するよう求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"４５０名の方々が一般企業の方の来場者、残りの８０名が２３区の産業関連の方々あるいは東京都、国というような行政の関連ということです。付随して行う講演会などは、ビジネス創造コンテストもあわせてやろうというようなことで、さまざま工夫して現在の形になってきたです。","id":"exchange-006"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"本多委員","kind":"意見","question":"１枚でレストランとかショップとか、いろいろな情報が１枚で見られるのは、１枚で集約したほうがいいのか。１年に１回というわけだと情報が遅れてしまいそうですし、その辺のところは重要なのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"何度も私も質問させていただいたりしているのですけれども、外国人が、１,３４０万人とかって言っていませんでしたっけ。おととしが１,０００万人だったと思うのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"無料の無線ＬＡＮですか、そういうものにも対応していくというのは、品川区としてもやっていかなくてはならないかなと思います。そういう意味では、ＩＴ関係は世界共通でありますので、ぜひとも進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"木村委員","kind":"意見","question":"そういう計画はないでしょうけれど、そういうことも考えられるのかどうか。ちょっとお聞かせ願いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"木村委員","kind":"意見","question":"それは行政が主導していくということはなかなか難しいことだと思いますけれども、そういうことが可能であるのかどうかという部分、何らかの模索をして、そういうことが主導していけるのかどうか、という可能性があるかどうかということだけでも聞かせてくださいとの意見を述べました。","respondent":"米田商業・観光課長","answer":"そういった中では地域の方々のご協力というものは欠かせないとは思います。発案があって、それに対して行政がどこまで支援できるかということは、可能な限りの連携を進めていければというふうに考えているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"どういう形で具体的に考えていらっしゃるのか、大きい意味において伺っておきたいと思いますが、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"検討を進めているところですけれども、特に観光の部分については、観光を活性化させていきたいという思いはとても大きく持ってあります。今後もそういったことに向けては、所管と連携しながらきちんと対処してまいりたいと考えているところです。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2716#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":16097,"voices":50}},{"id":"h27-20150120-7","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"の（仮称）品川区立障害児者総合支援施設整備運営事業者の公募","agenda":"の（仮称）品川区立障害児者総合支援施設整備運営事業者の公募","exchanges":[{"speaker":"石田（ち）副委員長","kind":"提案","question":"提案されたりすると、事業所がどうなるかと、うわさで広がったりすることもあるのです。少し心配する部分もあるのですけれども、その辺はどのように考えているのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"ぜひ手を挙げていただきたいと考えていますし、広くお声をかけて、できるだけ多くの事業者にいい提案をしていただければと思っているところです。","id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それがほかの福祉法人にも影響をしていくということで、やはり責任を持って進めてほしいという声もどんどん寄せられている状況になっているのです。その辺、改めて区のほうとしてはどのように聞いているのか、どう考えているのかを改めて伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ただやはり、障害者の支援というところで、専門性も要求されますし、これだけの大きな施設を直営で運営するのは難しいと考えております。安心して品川区立の施設に通える、そうしたような施設の運営を目指していきたいと、事業者と一緒に協働して行っていきたいと考えております。","id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"区直営であれば、そういったところがさらに進んでいくのではないかと思うので、改めて直営でということを要望させてほしいと求めました。拠点になっていくわけですから、どういったことを働きかけているのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"自立支援協議会というのを設けまして、区が中心となって支援者であるさまざまな施設の方たちと一緒に、行っているところです。障害者団体の方たちとも話を進めてまいりまして、どういう機能が必要になるか、そういったやりとりをしたうえでの施設の構成になっております。","id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"現場感覚というよりも、もう現場に入ってもらう職員、専門家を、区の職員として増やしていくことが必要になってくるのではないかと思います。今どういったことが必要なのか、改めて、やはり拠点とする施設ができるというところで展開していく考えはないか尋ねました。","respondent":"中山障害者福祉課長","answer":"基本的な施設の構成は、今回、公募の要領に載せさせていただいたこの内容になっているところです。その点につきましては引き続き、どういった支援をする必要があるのか、現場感覚も養いながら職員のスキルを磨いていきたいと考えています。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"次の質問にいきたいのですけれども、３ページの短期入所のところで、体験型居室を準備し、とありますけれども、これはグループホームの体験型としてとらえていいのかどうか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"今回、この施設に設けます短期入所は、６人くらいを１ブロックとした単位で考えております。短期入所して生活のリズムをつかみながら、今後も、既存のグループホームともお話をしながら進めていきたいと考えております。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"泊まりと地域生活というのは全く別物なので、やはりグループホームとしての体験型をもっと増やしてほしいという声などもあるのです。１５ページの法人を選定しない場合、その旨を公表しますとなっていった場合は、その後はどうなっていくのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"１５ページの法人を選定しない場合ですけれども、そこを無理して選定するわけにもいかないので、この項目を一応用意しています。万が一、水準を満たさないで法人を選定しない場合につきましては、改めて仕切り直しということになろうかと考えています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"全国公募による選定のところで確認したいのですけれども、たまたまそれが結果として、品川区内の医療系の法人に選定されたということがありました。確認したいのが、いかがでしょうか、改めて、答えるよう求めました。","respondent":"中山障害者福祉課長","answer":"これだけの大きな施設にもなりますので、実際に運営面のところや具体的な提案、そういったところをしっかりと審査していきたいと考えています。そういったところもしっかりチェックしながら、よりよい、安定して良いケアができる法人の選定を目指していきたいと考えております。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"ずっとお伺いしながら、厚生委員会の行政視察のことを思い出して、千歳市のワンストップサービスがありましたよね。せっかくですから療育ノートを検討していただいて、ずっと大人になる過程の中で活用していけばいいと思うのですが、いかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"ここの中で、障害のある子どもを支援していくためのサポートブックをどういうふうにつくっていくかというのは、今まさに検討中です。それを使っていくことで、継続的な支援が続けられるように、そういった視点で頑張っていきたいと考えています。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それを結んでいく中にあって、ここに社会支援と書いてあったけれども、そういうところまで含めた計画を前に進めていただきたいと思うのです。展開するサービスをどういうふうに具体化していくか、そのことはぜひ検討してくださいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"提案","question":"１４ページの(3)審査基準のところで、いろいろ提案等が非常にすばらしかったとします、そういうところの兼ね合いというのですか。建築費用等の提案が少し高いのではないかとなった場合には、どこまで福祉部門の考え方が要望できるのかというところを説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"運営面のほうに重点を置いて、設計面も加重はあるのですけれども、運営面のほうに比重を高くすると考えているところです。通常で考えれば、運営のいい事業者をできるだけ選定していく、その中で設計について若干の手直しをお願いするといったことはあろうかと思います。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました、少し安心しました。これは税金ですから、要望です、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"山元委員","kind":"提案","question":"５ページの３．施設内任意事業ということで、これは提案事業のようなのですけれども、その中に販売や飲食店云々ということが書いてあります。ちょっと公募とは関係があるかどうかわからないのですけれども、その辺がわからなかったので、そこら辺を１点教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"こちらにつきましては、この建設にあたって、いっとき別の場所に出ていただく予定です。移ったときの適地がないか、現在、それを探しています。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"お茶をして気分転換しているという方がいらっしゃったものですから、これを見ると、少し端のほうにでも考えを入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の生活困窮者自立支援制度","agenda":"の生活困窮者自立支援制度","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"費用負担のところですけれども、いわゆる都の補助はないのでしょうか。つまり、例えば自立支援相談事業等を行う場合、４分の３は国庫負担だけれども、４分の１は品川区負担になるのか、まず確認をお願いします。","respondent":"伊東生活福祉課長","answer":"この制度の、今お話しした費用負担につきましては、都の補助はなくて、国のほうから、先ほど申した４分の３ですとか、３分の２ですとか、２分の１と、そういうようなことになってあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、この１,１００名の方々に対して、それを具体的にどういうふうに展開していく予定があるのか。対処が必要となってくるわけであるから、現行の人数でこの責任を果たすことができるのかという確認を、まずお願いします。","respondent":"伊東生活福祉課長","answer":"あわせまして、その７名の中で住居確保給付金の事業も実施していく予定です。住宅支援給付ということで、法外ではありましたけれども、その人員を新しい法律のほうに振り向けるということで予定しています。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのは、この１,１００名の対象ですけれども、この中でも、多分いろいろな方がいらっしゃると思うのです。これは必須事業ですから、それらの実績が出にくいのではないかと思うのですが、いかがか尋ねました。","respondent":"伊東生活福祉課長","answer":"モデル実施ということで、ある程度の方々が落ち着いていくということで、こちらのほうの継続支援は不要になるというような事例も多々聞いてあります。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あえて言っておきますけれども、１,１００人の方々は全員が対象者ですので、それはご理解していただきたいのです。約１００億円前後投入されている生活福祉に対して、その税金でこれだけの制度をやっていただいて、改めて担当課長のお考えを確認したいと求めました。","respondent":"伊東生活福祉課長","answer":"確かに人員的には厳しいものがありますので、その辺は、こちらのほうでしっかりと対応していくということを、まず申し上げておきたいと思います。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最初に確認ですけれども、品川区としても今年の４月からやるということなのか、これから検討段階なのかということを教えていただきたい。(4)の費用負担で、財調とかの関係はどうなっているか、そこを教えていただきたいのが２点目です。","respondent":"伊東生活福祉課長","answer":"そして家計相談支援事業につきましては、やはりメニューがあったほうが支援につながるであろうということで、実施していこうと。一つ一つ問題をクリアにしていただいて、最終的には就労して生活を安定していただくという方向で支援をしていければと思っているところです。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"確認","question":"３点目は、２年以内ということなので、まだこれも細かいところはこれからということですかね、わかりました。いろいろ出てくると思いますけれども、その辺をまとめて、最後に確認で説明を求めました。","respondent":"伊東生活福祉課長","answer":"１,１００名というところは、それを品川区の数字に掛けたものですので、それがそのままイコールになるかというのは見えないところはあります。ただ、生活困窮者は結構潜在的にいるのかと考えていますので、その辺、しっかりとしていかなければいけないと思っているところです。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"ここから、この以下の事業につなげていくと出ていたのですけれども、この(1)がそれに当たってくるのかどうか。それからこの(1)を実施するとき、委託などはされるのか、それとも区が独自に進めていくのかを聞かせてくださいとの意見を述べました。","respondent":"伊東生活福祉課長","answer":"生活福祉課の中に新しい制度を担当する相談窓口を置く予定でございまして、ワンストップでいろいろとできるようにしていきたいと思っています。3)、4)というお話がありましたけれども、プランをつくって支援をしていくというようなことを考えているところです。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"(2)の2)は今後実施していく予定なのか、それともこれをすぐに1)、3)、4)と一緒に実施しない理由は何なのかを伺いたいと思います。それから、4)の学習支援事業というのは子どもたちをどんな形で支援されるのか、もしあれば説明を求めました。","respondent":"伊東生活福祉課長","answer":"一時生活支援事業ですけれども、これは今まで東京都と特別区で共同でやってあります自立支援センター、今。学習支援事業ですけれども、子どもと共に親のほうの支援もしていきつつ、そういう形で支援をしていこうという考えです。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど１,１００名という数字が出されていて、１,１００名以上かもしれないし、品川区としてこういうことは把握できないのでしょうか。そこを伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"前段の学習支援事業ですけれども、その対象者を生活困窮者というところに少し拡大しまして実施していこうと、現状で考えているところです。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"本当にいいことにつながっていく、品川区としてもプラスになっていくと思うので、こここそ充実させていくべきではないかと思います。先ほど、モデル実施している区があるとおっしゃっていたと思いますけれども、そのモデル実施している自治体はどこかわかるか尋ねました。","respondent":"伊東生活福祉課長","answer":"とりあえずは７名の態勢でスタートをしてみて、それから必要に応じてしっかり対応していければいいかと考えておるところです。モデルの実施自治体ですけれども、あとは岩手県や滋賀県、そういう形での事例は公表されているところです。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"モデル実施は、２３区ではないということですね。都内であれば、もう少し具体的にわかるかと思ったのですけれども、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問・要望","question":"まさに今もうそういうところに住んでいないと、簡単に言うとホームレスだという方だけが対象なのかを教えていただきたい。それから、住居確保給付金に有期とありますけれども、これが何ヶ月くらいなのか、わかれば説明を求めました。","respondent":"伊東生活福祉課長","answer":"生活ができないということであれば、どちらかというと、一時生活支援事業のほうに該当してくるかと考えておるところです。就職活動をしっかりやっている場合につきましてはさらに延長をするということで、現状では基本は３ヶ月ということで言われてあります。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"意見","question":"では、離職により住宅を失ったという表現になっているけれども、今おっしゃったように、こういう例はあまりないということで、その場合には下の事業になるというお話であれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"民間企業と連携した見守りネットワークのほうからまずお伺いしたいのですけれども、要は、その情報を受ける側の体制。これは２４時間と書いてあるから、とにかく品川区の体制がどうなっているのかという確認を、まずお願いします。","respondent":"大串福祉計画課長","answer":"一義的には、私ども福祉計画課のほうで、ご連絡は受けします。その先、在宅介護支援センターといったところにも記録等々が残っておりますので、ご連絡いただいたケースについては対応していくといった形で。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"ではそういうときに、この担当のそれぞれの事業者の方々がどこに連絡をしたらいいのか確実にわかっているのでしょうかということが１点。次の体制をしっかり組んでいかないと、これをつくった目的がなかなか達成されないと思うのですが、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"日中に関して言えば、我々職員がおりますので、その辺は十分に対応可能と考えております。先ほど申し上げました近隣の在宅介護支援センターとの協力体制も構築をしておりますので、また適切な対応ができるようにということで、今現在。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"せっかく得た情報を、品川区がきちんと捉えていかないといけないので、その確認をさせていただきました。当然いろいろな企業と連携を取っていくべきだと思うのですけれども、そのことについてのお考えをもう一度説明を求めました。","respondent":"大串福祉計画課長","answer":"その中でいろいろ対応させていただいているのですが、正直申し上げまして、それが一番重要なポイントになってまいります。資するのか、こういったところを十分にお話ししながら見極めて、協定を結んでいきたいと考えているところです。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"この事業をこれから継続的にやっていきたいと、品川区が思っていらっしゃると思うのです。５万円、２万円ということではなくて、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"今、委員からご指摘があったような形での助成金のあり方等々については、今現在、検討しています。近々また予算の審議の場でご提案をさせていただければと考えていますので、その際はよろしくお願いいたします。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"意見","question":"２．支え愛・ほっとステーションも高齢者になっていますけれども、同じ地域福祉の中でどういう形で、何か見守りとか支援ができるのか。高齢部門としてどのように考えていらっしゃるのか、聞き方が悪いですけれども、わかる範囲でどうなのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。やはり地域福祉ですから、それがどう輪になっていくかというのは、しっかりと推進していただきたいという要望だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"向委員","kind":"質問・要望","question":"確認だけさせていただきたいのが、基本的にはボランティアで支援をしてくださっているのかどうか、一つ確認させていただきたい。別の業種は、バランスの観点から一緒に締結してしまおうとか、そういう議論に至ったりはしないのか尋ねました。","respondent":"大串福祉計画課長","answer":"２点、ご質問いただきました。その辺を見極めつつ、こういった形の見守りネットワークが形成できるのかどうかについても、引き続き検討はしていきたいと考えています。","id":"exchange-033"},{"speaker":"向委員","kind":"質問","question":"最後にお伺いしたいのが、企業がこうやって手を挙げたいと思われる理由は何なのでしょうか。今、区として受けられている、企業が手を挙げたがる主な理由にどういう傾向があるのか、それだけ簡単に最後にお聞きできればと思います。","respondent":"大串福祉計画課長","answer":"事業者としても非常にありがたいところだとは、正直なところ、いろいろなお話をしていく中ではおっしゃっていただいたところです。これを結ぶことよってのさまざまな企業側にとってのメリット、そういったものもあるのかというのは担当としてお話をしていく中で感じたところです。","id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"お答えづらい内容だったかなと思いながらも、ありがとうあります、よくわかりました。気軽に１１０番する方も、さらなる将来的な発展も期待しつつ、以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問","question":"私からは１点だけ、支え愛・ほっとステーション事業の中で、今は品川第二地区と荏原第二地区ですけれども、今後増やす計画はあるのか尋ねました。","respondent":"大串福祉計画課長","answer":"こちらの事業につきましては、順次拡大していくということで考えているところです。今現在のところ、これについては拡大していくということで、基本方針としては持っているところです。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"それから、ずいぶんと平成２５年度だけが特化して多いのは、何か事情があったのか、教えていただきたい。それから、緊急通報というのは、どういうことで通報があったのか、その辺も少し教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"平成２５年度に増えたですが、やはりこの活動がかなり周知され、皆さんに浸透してきた結果なのかと考えているところです。ステーションということで設置させていただきましたけれども、皆さんの認識も深まった中で、これが現状かと思っているところです。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"少しお聞きしたいのですけれども、どういうメンバーというか、どういうことなのでしょうか。活動団体意見交換会と書いてあって、町会単位ではなくて、何かそういう組織的なものがあるのかどうか、それも教えていただきたい。","respondent":"大串福祉計画課長","answer":"2)が普及啓発事業の実施、普及啓発事業の実施というのが、我々はこういう取組みをやっていると。ご自分たちの取り組む活動のより一層の充実が図られるのではないかということで、発表会の場を設けさせていただいているといったところです。","id":"exchange-038"},{"speaker":"山元委員","kind":"質問","question":"そういう実施例を教えていただくと、何かそういうものがあるともっと身近に、これならできるなということがあるのではないかと思います。初年度は１０万円助成するとか、理想というか、将来的には全町会でというふうにお思いなのか尋ねました。","respondent":"大串福祉計画課長","answer":"そうした中では、全町会・自治会にご協力いただけることを目指して、この事業を展開してまいりたいと考えています。引き続き、そういった形での周知、啓発に努めていきたいと考えております。","id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、少しずつ設置が増えてきているのですけれども、こういったもののさらなる普及の周知をしていくという考えは、どういうふうに進んでいるのか。昨年、それの進捗状況はどのようになっているのか、お聞かせほしいと求めました。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"こちらの緊急通報の設置の件数ですけれども、これはあくまでもステーションが設置されている２カ所での件数となっています。こういった設置の勧奨も盛り込ませていただいておりますので… 在宅介護支援センターは、必要な方については個々にきちんと説明をして、お勧めしているという状況です。そちらにつきましては、今、ご説明申し上げております支え愛・ほっとステーション事業のほうでも受けておりますので。","id":"exchange-040"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"緊急通報システムの利用料の検討は、今どうなっているのか。変わっていなければ、変わっていないでいいのですけれども、お願いしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"利用料につきましては、現在、検討中でございまして、その負担の金額等につきましては、予算にも関係してきているところですので、今現在ですと、検討中ということでご説明させていただきたいと思います。","id":"exchange-041"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"町会等の皆さん、民生委員の皆さんのお話なども聞いていると、人もお金もないというような声も寄せられるのです。当初１０万円、どう考えているのか、説明を求めました。","respondent":"大串福祉計画課長","answer":"逆にむしろ、申請に際しての手間が煩雑だといったお声をいただくケースもあります。そうしたところを総合的に判断させていただいて、この助成金のありようについては、また改めてご提案をさせていただければと思っているところです。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういったときに、どう対処していくのか。こういうことがあったときには、こういうふうに対処すると望ましいというような、そういった啓発などはどのようになっていますか尋ねました。","respondent":"大串福祉計画課長","answer":"そちらにつきましては、逆に４番目でお示しした民間事業者との連携、これが一つ大きなポイントになってくるのかと思っているところです。こちらの活動を幅広く支援して、見守りの体制をより一層充実していきたいと考えているところです。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、この企業が契約している利用者等に広めてくれているということなのでしょうか。何がどうで何なのかというのがわかりづらいので、その辺を地域住民の皆さんにお知らせしていく、その辺はどうお考えか尋ねました。","respondent":"大串福祉計画課長","answer":"それから、この事業者のほうでの周知というご質問かと思うのですけれども、こちらの事業者が何か周知ということを行うわけではありません。こういった町会・自治会、それから民間事業者、いろいろな網の目を編み上げていければと考えているところです。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3406#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40569,"voices":109}},{"id":"h27-20150120-8","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"建設委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、東急線ホームドアの設置","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、東急線ホームドアの設置","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ホームドア設置済みの目黒線は、列車との接触事故が２０１３年度でゼロということですが、その前は大体どのぐらい事故があったということなのか尋ねました。","respondent":"中村都市計画課長","answer":"過去の事故件数については、目黒線についてはちょっと今、情報を把握しておりません。ただ、ここ５年以内で事故ということは聞いておりません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"これに対する費用負担はどうなっているのでしょうか。今後大井町線は、品川区内にほかの駅もありますけれども、これについて品川区は幾らか予算を払うということになっているのか尋ねました。","respondent":"中村都市計画課長","answer":"状況によって違ってきますので、金額については今つかんでおりませんけれども、大体一般的には１億から５億円ぐらいかかると言われております。これも、補助率としては同じ率で想定をしています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの質問にも関連するのですけれども、事業者、地元自治体ということで３分の１ずつになると。地元自治体のほうはそのうちの２分の１ということですけれども、そういったものについても同じスキームということなのか尋ねました。","respondent":"中村都市計画課長","answer":"補助費としては同じ金額ということになります。ただ、上限額も決まっておりまして、今、助成では、品川区としては６,０００万円を上限と定めてあります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろ要望を出していくとき、たしか何回か前にも伺ったことがあるのですが、ちょっと確認のために説明を求めました。","respondent":"中村都市計画課長","answer":"このホームドアの設置につきましても、日ごろから品川区も鉄道事業者に働きかけをしていますけれども、今回はその働きかけが実ったという形になっているかと思います。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"これに関してだけではなくて、定期的な協議会というのは何か持っているのでしょうか。もしあるのであれば、説明を求めました。","respondent":"中村都市計画課長","answer":"定期的な協議会というのは特に持っておりません。","id":"exchange-005"}]},{"id":"topic-02","title":"中延二丁目旧同潤会地区にかかる「都市計画原案」","agenda":"中延二丁目旧同潤会地区にかかる「都市計画原案」","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"数字の見方を伺いたいのですけれど、４のその他の近隣住民の関係ですが、２日間で９００軒で、大体こんなものなのか、少ないのか、多いのか、この数字に対する評価というか考えを教えていただきたい。","respondent":"寺嶋木密整備担当課長","answer":"この９００軒ですけれども、こういった説明会を開催するときには、半径としたエリアを対象とするということが決められております。今回はなるべく参加していただけるように、なるべく多くの方に参加していただきたいという趣旨であるというふうに理解しております。","id":"exchange-006"}]},{"id":"topic-03","title":"「木密地域不燃化１０年プロジェクト」不燃化特区の新規地区申請","agenda":"「木密地域不燃化１０年プロジェクト」不燃化特区の新規地区申請","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"資料２のところで、事業計画図のところで赤とピンクで囲ってある、一部欠落というか、切れているところ、ここは入らないということでいいのですか。お願いします。","respondent":"寺嶋木密整備担当課長","answer":"このエリアで都市防災不燃化促進事業という事業を導入することも合わせて予定しておりまして、あえて指定から外すということで、東京都との協議でそのような形になりました。","id":"exchange-007"}]},{"id":"topic-04","title":"東品川四丁目地区地区計画","agenda":"東品川四丁目地区地区計画","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今回はＣ街区というところで居住機能を導入するということで、近くにイオンとか、楽天タワーとか企業がたくさんあって、住宅もＵＲの賃貸とかあるのですけれど、ここはどういうものが入ってくる予定なのか、また計画なのか、具体的なところがわかれば説明を求めました。","respondent":"溝口都市開発課長","answer":"Ｃ街区の今、開発事業者のほうで計画されている計画でいきますと、約８００戸程度の住宅と下層に店舗等を予定されています。Ｃ街区としては以上のものを計画されていると聞いております。","id":"exchange-008"}]},{"id":"topic-05","title":"しながわ環境大賞・みどりの顕彰および環境講演会","agenda":"しながわ環境大賞・みどりの顕彰および環境講演会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"しながわ環境大賞は３団体ということで、どのような取り組みをされているのか、具体的に説明を求めました。","respondent":"三ツ橋環境課長","answer":"昭和６４年からずっと長い間継続されてあります。こちらは学校、すまいるスクール、ＰＴＡが連携した環境教育をされているところで、月１回親子で楽しく自然と楽しむイベントを開催しています。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"１６団体が応募されて、少ないという感覚でいいのかどうかもわからないのですけれど、これは毎年これぐらいの応募なのかということが一つと。ちょっと行財政改革特別委員会でも、基金が議論されているものですから、その辺ちょっと説明を求めました。","respondent":"三ツ橋環境課長","answer":"受賞された３団体と６団体以外にも応募されたということで、環境課からありがとうございましたの気持ちを込めて、参加賞も考えております。基金につきましては、こちらは基金は活用しておりません。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"区の状態、これらの団体というか区民の皆さん、どのような意識でおられるのか説明を求めました。","respondent":"三ツ橋環境課長","answer":"特にこちらの沖ウィンテックという会社につきましては、電力および温度の見える化を行うなど、地球温暖化防止に向けて取り組んでいる団体です。","id":"exchange-011"}]},{"id":"topic-06","title":"事業者向け防災ハンドブックの配布","agenda":"事業者向け防災ハンドブックの配布","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほど事業者向けということで企業の情報、そのほかの部分というのは、区民向けのハンドブックとほぼ変わらないのでしょうか。水害のところで、崖の対策等については何か入っているのか尋ねました。","respondent":"鈴木防災課長","answer":"１点目の、区民の方向けの防災ハンドブックと共通のもの以外の情報ですが、恐れ入りますがハンドブックの１２ページをあけていただけますでしょうか。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"どういったことを想定されているのか、配りっ放しという言い方はあれですけれども、そこのところを教えてください。どういうふうにお話をされるのか。","respondent":"鈴木防災課長","answer":"組織全体で取り組んでいただけるようにというところが主眼ですので、さまざまな場面でぜひ活用いただきたいということで、お声かけをする予定でおります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":16371,"voices":70}},{"id":"h27-20150120-9","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"文教委員会","time":"午後 １時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"の平成２７年度新入学の学校選択希望理由調査結果","agenda":"の平成２７年度新入学の学校選択希望理由調査結果","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２７年度、何年度からアンケートをやっていらっしゃるのかをお聞きしたいのですけれども、お願いします。","respondent":"野呂瀬学務課長","answer":"入学説明会でやったりとか、一緒にどういう理由で選んだのかと、より実態に合った調査をするためにしています。いつからというのは、学校選択を始めたその年からやっているものです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"「学校の教育活動に魅力がある」という項目に関して、ほかの項目を見ますと、結構具体的なお尋ねをしていらっしゃると思うのです。今１位になっているところを、もう少し具体的にどう思われているのかをお聞きできたらいいのかなと思いますが、その辺はどのようにお考えか尋ねました。","respondent":"野呂瀬学務課長","answer":"数字は、アンケートというのはこのアンケートだけでなくて、いろいろなところでアンケートをしております。そこまで細かくは、その中でまたいろいろな教育活動が親御さんによって違うのでしょうけれども、一つにまとめてしまったです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。もうちょっと具体的なこともわかっていらっしゃるのかと思いますが、最後に、今後同じように続けていくのかをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"このアンケートにつきましては、やはり毎年希望選択のときに続けていきたいと考えていますし、また、その結果を校長会等を通じて学校のほうにも周知して、今後の学校運営の一助にさせていただきたい、このように考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"項目もほとんど同じのようですから、教育委員会としてどういうふうに評価というのかしら、考察されているのか。どういうふうに現場のところの具体的な教育活動にフィードバックしていこうとするのか、そのあたりを伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"回答数ですけれども、３割程度というのはご指摘のとおりですけれども、大体３割の方が学校選択は希望していると。これも１つ、アンケートの結果にありますので、こういうのも含めて今後の学校運営に役立てていきたいと考えているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"中学校でも１学年……、とにかく１２学級以下の学校、あるいは中学校でも１学年３クラス以下の学校は淘汰していくという方向で出してきていると。通学時間が１時間以内でという具体的なところまで出てきているという点で、どういうふうに今の段階では考えているのか、その辺を伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"学校選択の希望調査を出して、学校選択を利用した方がそのうち３割いたということですので、それはもう一度申し上げておきたいところです。今考えているのは、今のところの学校選択に、今の品川区の教育プラン２１はこのまま推進していくという考えに変わりはございません。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"そういう状況がいつの時点のことを、例えばどういうアンケートなり、その辺の具体的な裏づけの資料というのを紹介しておいていただきたいと。で、終わりたいと思います。","respondent":"野呂瀬学務課長","answer":"先ほど質問したところで、小規模校の支援につきましては、今後も継続してやっていきたいと考えています。小学校では６８.３％、中学校では７０.９％であるという調査もありますので、このように考えております。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"私がさっき言ったのと趣旨が違うのかなと思ったので確認なのですけれども、反対、３分しているということなのですね。学校選択制についてよいかどうかという質問に別にくぎを刺すつもりも否定するつもりも全くありませんけれども、それは申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤副委員長","kind":"質問","question":"そうすると、今、大体が３割がマックスの状態だよと。今言ったマックスの３割をしっかりとキープするような学校運営というか、そういう教育方針になっていらっしゃるのか、そのあたりを説明するよう求めました。","respondent":"野呂瀬学務課長","answer":"ちなみに、いわゆる指定校変更制度というのがございまして、そういう制度で大体３割ぐらいは他の希望したところに行っているという現状があります。","id":"exchange-008"},{"speaker":"須藤副委員長","kind":"質問","question":"ですから、まず学区内のほうを先にして、あとは抽選ですというやり方になってきてしまうよね。そうすると、選択制というもの自体がどこまでそういう表現をしているのかということがちょっと気になってきているので、そのあたりを説明するよう求めました。","respondent":"田村教育次長","answer":"施設一体型と学校選択は品川区の今までの教育改革の柱ですから継続はしますが、同時に、並行して進めていくと。その課題を教育委員会と学校がともに解決するような努力をしながら学校選択を継続するという動きが必要なのかと、そういうふうに考えております。","id":"exchange-009"},{"speaker":"須藤副委員長","kind":"質問","question":"それから、鈴ヶ森小学校も２回上がってきていると。それで、予防をやるよというお話だけれども、学校ではどういうことをやられているのか、説明を求めました。","respondent":"野呂瀬学務課長","answer":"３番の上神明小学校６年１組ですけれども、６年１組といいますか、イコール学年閉鎖と同じことになります。部屋の換気とか、そういうところが基本になるかと思うのですけれども、事あるごとにそういう注意喚起は呼びかけているところです。","id":"exchange-010"},{"speaker":"須藤副委員長","kind":"質問","question":"僕らが見るものなので、１番から来てどうだよというのが普通の出し方だと思うのだけれども、まずそのあたりのお考えを教えてください。これ、わからなければわからないので構わないのだけれども、ちょっと「あれ」と思ったので、教えてくださいということだけです。","respondent":"野呂瀬学務課長","answer":"それと、申し訳ございません、伊藤学園、確かにこういう名称では言われていませんので、これは３年……。〔「何、違うの」と呼ぶ者あり〕 ミスプリントだと思います。〔「違うの」「伊藤学園はたしかこういうクラス名……」と呼ぶ者あり〕 調べします。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"例えば１８番目の大井第一小学校は１９日に登校して、そして、翌日から３日間休業をしたというふうに読むわけですよね。そのあたりのことを教えていただきたいのと、その辺について教えていただきたいのと、そういうあたりはどうなっているのか尋ねました。","respondent":"野呂瀬学務課長","answer":"これは目安ですけれども、大体２割がお休みになったら、学級閉鎖も検討する。１組、２組、そういう呼び方になっているというものです。","id":"exchange-012"}]},{"id":"topic-02","title":"の寡婦・寡夫控除のみなし適用","agenda":"の寡婦・寡夫控除のみなし適用","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう１点は、対象人数が５０人と記載されていて、税法上でいったときの人数というのがもしわかれば教えていただけないかと思うのですけれども。２点、お願いします。","respondent":"竹田保育課長","answer":"平成２１年に、平成２６年度から、政令指定都市２０都市のうち１０都市で寡婦・寡夫控除の見直し適用が実施されております。こうした背景を受けまして、品川区でも慎重に検討した結果、寡婦・寡夫控除の見直しの適用の検討を始めたところです。","id":"exchange-013"}]},{"id":"topic-03","title":"の「品川区子ども・子育て計画（素案）」に対するパブリックコメントの実施結果","agenda":"の「品川区子ども・子育て計画（素案）」に対するパブリックコメントの実施結果","exchanges":[{"speaker":"南委員","kind":"質問","question":"全体で意見としては２４件だという話なのですけれども、予想より多かったあるいは少なかった、どういうふうに捉えているのかを伺いたいと思います。そこから伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"パブリックコメントにつきましては、これまでも区民説明会等でもご説明してきましたので、十分周知がされた上でのことだと考えております。他の自治体も同程度またはそれより少ない数のご意見だったということも聞いておりますので、十分ご意見をいただいていると考えております。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"パブリックコメントは１１月１日から始まるにしても、周知はもっと前にやるべきだと思うのですけれども、その辺の見解を伺いたいと思います。この際ですからいろいろ言いたいのですけれども、４番のところも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"民間ではなく、しっかりと公的責任を果たすべきだと思っていますので、その辺についての考え方もこの際伺いたいと思います。３行目の冒頭に「送迎バス等」と出ているのだけれども、これはどういうことでこういうふうになったのか、この際伺っておきたいと思いました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"３点のご質問にお答えします。３点目の保育の質の確保のところですが、適切な施設整備の中のことにつきまして、具体的に区の考え方を示したものです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"特別支援のところについては障害者福祉課のほうにという話なので、ぜひそれはそれとして大事なことですから、進めてほしいと求めました。それと、出された意見は貴重な意見ということで、実践に移していただければということもあわせてお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-04","title":"の認証保育所の新規開設","agenda":"の認証保育所の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"この認証保育園なのですけれども、例えば、給食だとかはどんな形で提供される、そのあたりを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"給食設備につきましては、これは小規模とは違いますので、０歳児からですので、離乳食から、認可保育園と同様に提供しています。","id":"exchange-018"},{"speaker":"高橋委員","kind":"意見","question":"設置者について、他にも保育所等の運営といいますか、をしているのかどうかとの意見を述べました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２６年度から台東区で小規模保育施設を行っておりまして、また、私どもでも小規模保育の事業のほうを開設する予定です。ですので、これまで認可保育園や認証保育所の経験、実績はございません。","id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"事業所内と小規模ということですね。区内でも小規模の予定ということは、これは予定ということなので、平成２７年度の予定ということでよろしいか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"株式会社アイ・エス・シーにつきましては、今委員ご質問のとおり、事業所内保育所と小規模保育施設の運営の実績があります。１２月１６日の新規開設におきまして、南大井に小規模保育施設、１５人として開設するウィズブック保育園大森海岸が同事業者による設置です。","id":"exchange-020"},{"speaker":"須藤副委員長","kind":"意見","question":"０、２歳の３０人が年が上がってくると、その先はどうなってしまうのかなという思いがある。上が１０人しかいないというと、そのあたりはどういうふうにしていただけるのかなとの意見を述べました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ご案内のとおり、認証保育所は東京都の独自施策ということで、やはり待機児童が多い０から２歳の開設のところを中心に設置されているものです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"年齢ごとの人数がもしわかれば教えていただきたいのが１つと、あと、この株式会社が施設を借りるか何かしてオープンするということなのでしょうか。前回質問すればよかったのですけれども、今出てきたので、ここに関連して伺っておきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"オーナー様のほうから、小規模保育事業への貸し出しというか、賃貸のお話があったというふうに聞いております。大体見込みですが、１歳が１２人、２歳が１２人ということを予定しております。","id":"exchange-022"}]},{"id":"topic-05","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"南委員","kind":"確認","question":"そういうことで、どういう対策がいいのかはしっかりと教育委員会としても検証して、とっていただけるようにお願いしておきたいと思います。５月２４日の５時間目ということなのですが、どういうルートでなのかというのが、確認をしたいと思います。","respondent":"渋谷指導課長","answer":"これは校長のほうから教育委員会のほうに電話の一報があって、事案が発覚したです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"先生が何回かＴシャツをつかんだりドアに押しつけたりいろいろやっている最中に、別の子どもさんたちが校長室に飛んでいったという形なのですかね。どんなふうに認識をされているかということを、かいつまんで話してもいいのですけれども、表明できるところがあったら教えてほしいと求めました。","respondent":"渋谷指導課長","answer":"今回の該当の教員については、基本的に体育会系の人間で、一つ課題として大きなところがあるのだろうなと思います。再三再四、力を行使することはいけないということを徹底していくことを繰り返し繰り返しやらざるを得ないのかなというところを感じるところです。","id":"exchange-024"},{"speaker":"須藤副委員長","kind":"質問","question":"そうやって入ってはいけないよというところへ入ってしまうような子どもたちに対して、教員はどうすればいいのでしょうか。保育園大丈夫なら大丈夫だよと言ってくれればそれでいいし。","respondent":"渋谷指導課長、竹田保育課長","answer":"６年生の発達段階であれば当然わかるわけで、懲戒として投げ飛ばしたり蹴飛ばしたりしているというところが大きな問題なのだろうなと思います。一般的に、今委員がご指摘になったように… くれぐれもそういうことがないように、日頃から研修、あるいは機会を捉えて保育士にお伝えするところです。そういったことから、そういった事故等はないものと認識しております。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"ということがあったと思うのです。どんな形で児童に対するケアというのでしょうか、お伝えできる範疇で結構なので、どういうふうにやったよというのがあれば説明を求めました。","respondent":"渋谷指導課長","answer":"市民科等の時間を通して考えるいい契機にして、今、卒業に向けて一生懸命取り組んでいるといったような状況です。","id":"exchange-026"},{"speaker":"高橋委員","kind":"意見","question":"それが１カ月に当たっているのか、つまり３学期に１カ月あるとすると、ケアについてどういうふうに。仮にこれからだとすると、どうされるのかということをお尋ねしたいとの意見を述べました。","respondent":"渋谷指導課長","answer":"この事案が発生した後、臨時の保護者会を開きまして、該当の保護者の方たちにはきちっとご説明をしたというような経緯があります。授業に来られない期間は１２日間ということで、その間は講師の対応、副校長が学級担任として入るということでご理解いただいているところです。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"１０月のときの委員会で質問した待機児の問題、１０月のときの委員会で伺ったときには、そういう申請状況があるというふうな報告をいただきました。今日は２０日ですから２週間ぐらいたっているので、１２月２６日の締め切りで何人ぐらい申請をしたのか、ぜひその辺を教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"昨年の１０月時点での数値というのは新規申し込みではございませんで、継続して毎月毎月申し込んでいる数です。１２月から初めて新規に申し込んだ数ですので、現在書類等の審査をしておりますので、具体的な数は現在のところは申し上げかねるところです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"これから行われる審査会にかけるわけですから、大ざっぱな数でいいですから、そういう状況を教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"例えば、そういうふうに思っておっしゃるのだったらそれはそれとして伺ってもいいかなと思うのですけれども、この委員会としての責任の問題ですよね。ですから聞きたいし、掌握する必要があると思うのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ないですか。〔「だから、そう言えばいいじゃない」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須藤副委員長","kind":"意見","question":"今、正副の副が出たので、今初めて言われたので、担当課長が答弁したように、出せる時期が来たらまた出してもらうということで整理していかないと、いつまでぴったりとかというのはなかなか難しいと思うので、ご意見としては正副でまた話をして、調整をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"副委員長もそういうふうにおっしゃったのだけれども、出せる時期というのは、いつだったら出せるのか、そこは質問したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら、入園の１次の選考の発表というのは２月１９日を予定しておりますので、２月１９日に選考が終わって、結果発表もありますけれども、その時期になれば私どももきちんと、もちろん確定しておりますので、その日以降、またご報告の機会を設けたいと思います。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"では、そのときには今の数字を示していただける、報告していただけるということで考えて期待していいのですか。それともう一つ、そういうことを今求めているのではなくて、２月１９日の発表後だったら出せるというところには全然すごく違和感を感じるのですよね。","respondent":"こんの委員長","answer":"要求できない委員会ではございません。きちんと受けていますので、どうぞこの辺はご理解いただいて、きちんとご報告できる時をつくりますので、よろしくお願いしたいと思います。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"さっきは、数字の問題と一人ひとりの要望の中身、申請の中身は全然リンクしないじゃないですか。〔「該当しているかしていないかがあるじゃないか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"数字が、つかんでいないなんていうことはあり得ないのですから、締め切ってから何週間もたっているので。納得できないから、そこを納得できるようにちゃんと説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"やはり途中で、辞退も含めたそういうふうな数値がきちっとしたものを逆にお出ししていなかったことを私も十分反省しております。ですので、私としましては、きちんと数字が確定した段階でお出しするのが一番的確な情報の開示だと考えています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"書類不備ということも１つの理由に挙げられましたけれども、では、書類不備は受領したことにはならないのですか。申請を受けたことにはならないのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"その数がありますので、最終申込数というのは、５月以降、お出ししているところです。ですので、１次選考の中でも、１次選考の確定の後に数値のほうはご報告させていただきたいと考えています。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"このケースについては一人ひとり確認した、書類がそろっていますねと、大抵そういうふうにして受領するわけでしょう。それはそれとして課長の答弁については伺ったわけですけれども、その書類不備な人は受領したことにはならないのか、そこを聞いたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"南委員","kind":"確認","question":"でも、それはそれなのですよ。１次と２次の申請数、それはそれでしっかりこの委員会でもみんなで確認をしていけるからいいと思っているのだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"１次の数を求めているのに何で答弁してくれないのですか。では、窓口の人たちの仕事が不十分なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"委員会としては、そのとおりのこともお願いしてありますので、その結果はまたしかるべきときに数字を出してもらうということで終わっています。委員の皆さん、みんなそういうことで、あとは個でやってくれないかということで、議事進行で閉会を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"須藤副委員長","kind":"提案","question":"私、提案した。私、議事進行の提案をしたのだからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"しかも副委員長からそんなふうな提案するなんて、冗談じゃないです。区民に責任持てないではないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"知っていることなのだからいいではないですか。知らない数字を求めているのではないのだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4846#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":36488,"voices":124}},{"id":"h27-20150120-5","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"総務委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"国民健康保険のほうでお伺いしたいのですけれども、支払いをしないと社会保険には加入できませんとかという仕組みにはなっていないのかどうなのかというのが１点と、何かはじかれるものがあるのかどうなのか。","respondent":"久保田会計管理者","answer":"細かくはちょっと説明できないのですけれども、聞いているところによると、交換というのが現在はほとんど行われていないという状況らしいです。転出先についてもいわゆる住所変更、それさえも、その先が不明だというのがあるのです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"かかる費用とどうなのかと言ったときには、１か月分ぐらい何となく緩衝地帯ではないですけれども、おそらくあると思うのです。金額的にどうなのかという話ですけれども、多分本来納めるべきお金だと思いますので、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと伺いたいのですけれども、どこかの項目だったり、それに基づいて区議会に報告するという性格のものなのか。その辺のまず報告の位置づけを教えていただきたいのが一つと、もう一つは、弁済することができる見込みがないというのはどういう状況なのか。","respondent":"久保田会計管理者","answer":"確かにいろいろなケースはあるのですが、それから何回も請求あるいはそういう行動を我々のほうがとったとしても、なかなか同じ状態で回収できない。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"それから、延滞金がありますけれども、この延滞金というのは、どのぐらいのもので、どういうふうに発生されているのか。平成２６年の中で放棄するという形で決められているのですけれども、これは何か決め事があるのでしょうか、説明を求めました。","respondent":"久保田会計管理者","answer":"ご本人以外に連帯保証人を２人つけることが原則ですので、同じく、あるいはもう亡くなられているというようなケースも多いわけです。そういうような個々のケースについて、それぞれ事情を把握して所管については必要な情報を収集しながら対応しているというような状況です。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"そうではなくて、やはり品川区として若者の就労支援という意味で言うと、その連携の仕方をどうされているのかもう一度お聞きしたいと思います。それに対応していくという形に変更していく一つの大きな理由づけになると思うのですが、その辺の見直し等々についてはいかがか尋ねました。","respondent":"久保田会計管理者","answer":"あるいは若者就職支援ですと生活福祉課もそういうことを手がけている事業がありますし、ものづくり・経営支援課でやっている事業もあります。それから、今委員がおっしゃられた今後の考え方については、所管のほうに十分それについては伝えたいというふうに思います。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう形の中で一つお伺いしたいのは、あれも５００万円ぐらいまではお金を貸すわけで、例えば高校生は授業料が無償化になったと。例えば、奨学金というのは行政が担うべき問題ではなくなる可能性が大だと思っていて、そういう奨学金についての思いがあれば教えてほしいと思います。","respondent":"久保田会計管理者","answer":"いわゆる根本の考え方についてということになりますので答えにくいというか、非常にそういう点では期待しているということは伺っているところです。どういう方法が一番いいのかというのは、所管のほうでも随分これから考えて検討することだと思いますので。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も今石田委員がおっしゃったとおり、やはり何とかして今の垣根ですか、国民健康保険と社会保険の、それは区役所として訴えていくべきではないか。品川区としても、上のほうに、国のほうに上申してほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後の動きも伺いたいと思います。何がどう変わるのか、実際の動きの中でどういうふうな役割として位置づけられるのか、そこをご説明いただきたい。","respondent":"柏原行財政改革担当課長","answer":"最終的にはまだ検討の途中ですが、今詰めの段階で確定させていただきたい。総務部長であり、実際の行動に移した段階のときに、担当部長が陣頭指揮に立つといったようなイメージで考えているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"商業・ものづくり課ということですけれども、いわゆる横断的な事業になるので、その意味で内閣府に置いてあるのだと私は伺いました。阪神・淡路大震災から２０年ということも含めて、どういう形で陣頭指揮をとる体制になるのか、もう少しご説明ほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"それから課長のポストが４７、担当課長が８というポストになりますので、課長で言うと四つ減っている。あくまでもポストの数です。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"商業・観光課、商業・ものづくり課、産業政策調整担当課長はもともと現行では経営支援課の部分の業務をという形でよろしいのでしょうか。ちょっと詳細を教えていただけたらと思います。","respondent":"柏原行財政改革担当課長","answer":"担当課長におきましては、ものづくり・経営支援課で行っていただいている事業を担当する部分が多くなってくるだろうというふうに思ってあります。その中から例えば産業活性化であるとか、就業支援・企業支援、こういったところを主に担うことになるという想定で今考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"そうすると、総務部とそれから防災まちづくり部を兼務ということなのですけれども、仕事が多くないでしょうか。そこをどういうふうに割り振って、誰がやる、どこがやるのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"それから危機管理の部分、私の説明がちょっと足りなかったところがありまして申しわけございませんでした。区の考え方とすると、行財政改革を進めていくという考え方に変わりはございませんので、それを企画調整課の中でさらに進めていく考えです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"総務部に部長が１人と、防災まちづくり部に部長が１人というような認識ですか。担当課長でもいいですけれども、品川区の姿勢という中でも示すべきなのではなかろうかと思うのですが、その辺のお考えはいかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"その考え方というのはこれからも踏襲しますし、十何年間の一定程度の成果であろうというふうに思ってあります。ちょっときちんとしたお答えになっているかどうかあれですが、ご理解いただきたいと思います。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"これからも改革ですから何年後、品川区をどう考えていくかというのは、やはり別次元で考えていくべきものも多々あるかと思うのです。短期という形での改革という意味では、これからも進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、それでいいのかどうかという感覚を教えていただきたい。そこまで入るの、いろいろ話が入り組んできてしまうのではないか、そこら辺の整理はどうやってお考えなのかというのを教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"そういったところで、いわゆる横串というところで、やはり企画部門が積極的に入りながらというのは大きな役割だろうというのは認識しています。そういう状況を見ながら企画部門を改める形で管理するかというのは、判断したいという内容のものであろうというふうに考えております。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"部の中はもちろん部の中でやるのだけれども、そう考えると事業部でと思うではないですか。部になったわけですから、せっかく部にするのですから、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいのですけれども、事前説明のときにこういった内容は全部入っているということでいいのか。これはちょっとお答えいただきたいのですが、とにかく早急にお配りいただきたいという思いがあるのですが、配布期間が２０日から２４日（金）までと。","respondent":"工藤選挙管理委員会事務局長","answer":"計画では２０日から２４日までという形になってありますけれども、今私どもが予定しておりますのは、１９日（日）午後５時３０分が締め切りです。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"では利便性がよくなりつつも、一方ではそういったネタというのですか、その人のためにもしっかりとした形で配布をしてほしいと求めました。若者のためにどうすればいいかというのは、いろいろな広い観点で考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"今のバイク便ではないけれども、バイク便は手配をされたということだろうから今みたいにバイク便でそこへ届けられますとおっしゃっているのだと思う。私はこの部分だけは毎回そうやって言うのは、もうそろそろやめにしたほうがいいと思うので、これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"公園の中にあって、後から場所を変えたと伺ったのですけれども、公営ポスター掲示板の設置についての今回の工夫の点を伺いたいと思います。選挙管理委員会の車だったと思うぐらい、いろいろ工夫をしていただきたいと思ったので述べたのですけれども、それぞれいかがか尋ねました。","respondent":"工藤選挙管理委員会事務局長","answer":"やはり１日でも早く届けるというのが基本だろうと考えていますので、いろいろと検討していきたいというふうに思っておりますけれども。１５０名の方がそれぞれのエリアで、そういった部分を含めまして、いろいろと多方面の形で検討させていただこうというふうに思っております。","id":"exchange-019"},{"speaker":"西本委員","kind":"確認","question":"１０番と１１番、くじを引くということですが、これは選挙管理委員会のほうで決めたのですか、ちょっと忘れてしまったので教えてください。それは行政側がそこのマンションと交渉して、選挙公報は入れさせてもらうとか、そういうような動きというのはされていないのか尋ねました。","respondent":"工藤選挙管理委員会事務局長","answer":"２点目の選挙公報についてのマンション等への配布ですけれども、一番今私どもも対応に苦慮していることは、トラブルになっているケースがあります。どうしてもシルバー人材センターのほうでも対応できないというケースについては、いわゆる配布するような形にしておるものです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"なかなか結構これは増えているのではないかと思うのですが、これに対して何か、選挙というのは当たり前だと思うのです。効果があるのかないのか、よくご苦労されているのはよくわかるのですけれども、成果なんかはいかがか尋ねました。","respondent":"工藤選挙管理委員会事務局長","answer":"趣旨をご理解いただいて、まず配布するというのが一番ですので、その中で交渉してベストを尽くすです。結果的にそれで１００％という形、やはり必ず選挙がありますと二、三のマンションで交渉してもなかなか難しかったということがあることは事実です。","id":"exchange-021"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいのですけれども、９名の方のお話をこれに、いろいろな団体から意見交換とか要望を毎年１回お受けしているのですけれども。あくまでも区職員の発案というか、何歳代かはわからないですけれども、今後それを中心に考えてしまうのかどうかということか尋ねました。","respondent":"荒井広報広聴課長","answer":"今後、キャッチコピーの案といったものも提案してもらいながら進めていく予定になってあります。それから、接合点という、この言葉も含めてコンセプトをどういう言葉として使っていくかというところは検討を進めていくところですので。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"八つ、例えば先ほど言った運河の関係、まさにこっち側の８個の魅力的なところからある意味抜け落ちているわけではないですか。今後品川区はこういう魅力をつくっていこうと、そういうのも含めてシティプロモーションをつくっていただきたいと思うのですが、どうか尋ねました。","respondent":"荒井広報広聴課長","answer":"新たな品川区の魅力をどう引き出して、その目標値を立てていくかということを今後の施策の中で進めていきたいというふうに考えているところです。水辺の事業ですが、今後具体的な事業を進めていくときにはもちろん出てくる事業の一つだというふうに考えているところですが。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問","question":"最終的に費用を払うのは品川区側ですから、しっかり伝えないと多分広告代理店は品川区に言われたとおりつくりましたで終わってしまうと思うのです。いくら広告代理店がついたとしても、いいものが本当にできるかどうかというのは品川区にかかっているような気がしますので、ぜひ頑張っていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"お聞きしたいのは、誰がこれをまずまとめたのか。それから住んでみたいと思ってもらえる、あとは居住している方、誰が誰のためにこれをつくったのですかというのをまず聞きたい。","respondent":"荒井広報広聴課長","answer":"そういったもののためにやっていきたいというふうに考えているところです。訪れてよし、住んでよし、働いてよし、学んでよしの品川区をつくっていきたい、そういったような考え方でやっているところです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"交通の利便性を出してみれば、５００ｍ以内に駅がありますとか、事実として出せることというのはいっぱいあるではないですか。何か反対があれば、意見を求めます。","respondent":"桑村副区長","answer":"ただ、このことの打ち出し方というのは非常に難しいということと、これは２３区、ほかの区でも相当そういうことを打ち出せる。打ち出し方が下町というイメージで出せるのですが、これがやれるかどうかというのは、品川区の中でもなかなか難しいのだろうというふうに思います。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"それが失敗したという例もあるけれども、イメージづくりとかで成功している例だってあるわけではないですか。行政がやれない部分は民間にやってもらうということだってできるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"シャッター通りがどうのこうの、区の職員の方々も問題意識のあり方がどうなのだろうか、ほかの地域のところに視察に行っているのでしょうか。そこら辺、広告代理店の考え方というのはどうだったのか尋ねました。","respondent":"荒井広報広聴課長","answer":"先ほどご説明させていただきましたように、そういったところで見られるだろうということで、この言葉を導き出したものです。お答えになっていなかったら、またご質問いただければと思います。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"広告代理店が出してきたものは、もうちょっと調べてほしい、品川区の魅力をもっと引き出してもらえるような調査をかけていただきたい。ここはこういう特徴があって、今後の検討の参考にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"これからどうやってつくるのかあれですけれども、どうなるのかあれですけれども、進めた以上やってほしいと求めました。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問・要望","question":"おそらくここの１位から５位の間というのは、確実性というのですか、そこをしっかりやる。１０万ｔ以上の船は今度青海に新しいふ頭をつくって接岸するわけですから、本当に膨らんでくると思うので、海をばっさり切らないでもらいたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"これにかかわって伺いますけれども、品川区の魅力をどこにつなげるのかがなぜ不明確なのか。訪れてほしいでも、品川区の魅力をどこにつなげるのかがなぜ不明確なのか、そこを伺いたいと思います。","respondent":"荒井広報広聴課長","answer":"確かに皆様のご意見の中にあったように、非常に総花的になってしまっているというのが一つあるかというふうに感じているところです。品川区の魅力をどこにというのは、少し絞り込んだ形を今後考えていきたいと考えています。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"定住化を図るというのは一体どういう意味なのか、ここにつなげたいと思っているのは一体何なのか、そこを伺いたいと思います。都市間競争に勝つ、定住化を図るというのは一体どういう意味なのか、ここにつなげて何が生まれるのか、そこを伺いたいと思います。","respondent":"桑村副区長","answer":"それはまたいろいろ考えなければいけないというところで、非常にご批判を受けるということなのだと思います。先ほどの答えとすれば、都市間競争というのは自治体としてあるべき姿を追求するという意味で言っているので、それが目的ですということです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"人のいない自治体はないですから、ではどれぐらいの人口がいいのか、これはなかなか私自身もわからないことです。まずシティプロモーションの取り組む未来やコンセプトからしっかり見直して、必要なことをまず整理するところからではないかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"お聞かせいただきたいのですけれども、ほかにはどのような案が出たのか、ちょっとほかの案も聞かせていただけたらと思います。そちらからお願いいたします。","respondent":"荒井広報広聴課長","answer":"「人と人の接合点」というのが最終的に出された。区と業者の間でこれにしようと決めた案ですので、ほかの案については、検討の過程で削除していったというか、ここにまとめ上げてきたということです。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"幾つかお聞かせいただけたらという意図がありまして、ちょっと質問させていただいたのですけれども、何かキーワードだけでもないでしょうか。幾つか、二、三点でももしありましたら教えていただけないか尋ねました。","respondent":"荒井広報広聴課長","answer":"ではその前に何をやっていかなくてはいけないかというところで戦略プランをつくって、その中で定めていきたいというふうに考えているところです。できるだけ年度内を目指して戦略プランの策定を行うというのが現在のところの考え方です。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"意見","question":"年度内と言わず、もうちょっと後でもいいですけれども、私は根本的に考えたほうがいいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"塚本副委員長","kind":"質問","question":"なぜ商店街がということで、どういうことで商店街が品川区の地域資源として各職員が出てきたのか理由を知りたいと思いましたので、これをお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"まじわりがあるとか、そういう形です。マスコミ等に取り上げられて有名であるとか、そういったこともありました。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"そういった方々の意見なども集約しながら検討していただければなというふうに思っているので、ちょっと意見として述べさせてほしいと求めました。それにかわるぐらいのものをつくっていくべきなのだろうというふうに思うので、そうすると、その辺の考え方をお伺いしたいと思います。","respondent":"荒井広報広聴課長、渡部委員長","answer":"努力はするところですが、今皆様方からいろいろな意見をいただいたところですので、決め方も含めて少し慎重にやっていきたいというふうに考えているところです。 これから私たち委員の意見を活かして進めていただければというところでお願いをして終わります。ただいま出ました意見については、今後策定予定のプランに活かしていただきますようお願いをしまして、所管事務調査を終了いたします。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":61232,"voices":90}},{"id":"h27-20150121-14","meetingId":"h27-cm01","date":"2015年1月21日","dateIso":"2015-01-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ご発言がないようなので、先に１点だけ伺っておきます。いろいろとこの１年間議論してきた中で、こちらのまとめのほうは区長に提出するものですから、皆さまのお考えはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"そこでまた契約のこととかがあると、また１つのそれはテーマになるわけではないですか。それはいろいろなことを検討してやったのはわかるのですが、今、これに関することということですから、これはこれでいいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員長","kind":"提案","question":"２つの議論が一緒になってしまって申しわけないです。今のあべ委員の提案としての私の受けとめとしては、３つのテーマ事項の１つでありますので、ご意見を伺えたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"あべ委員","kind":"意見","question":"３項目でやるということで、残りの２つの中で、そこに至っていないところについては現況にとどめるというような整理でいいのかと思います。であるので、複数であることについては何の問題もないというのは私の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須藤委員","kind":"提案","question":"どういうふうにして出すのかという、こっちは提案しますと１つあって、行政に対しての提案という形もその中に含まれて出してきているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"意見","question":"３つの調査事項に関しては、我々の中にはどうしようかという部分があって、いわゆる議長への報告という形にとどめさせていただいた。これまでせっかく１年間議論してきたことを、通常であればもっとコンパクトに簡潔に記すべきところを、議長のほうには報告をするとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今後、検討の項目に値しますと。ですから、そういうものを１つにして議長に報告して、私は違うと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"意見","question":"済みません、途中で。順番的には、まず議長のほうにお出しをさせていただいてと、こんな順番で考えているところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"これは時間的に別々に出すのか、議長に一緒に出すでしょう。これをここへくっつけているのなら、私は意味がわかると思うけれども、別々に出すというのはちょっと違うと思うとの意見を述べました。","respondent":"中塚委員長","answer":"こういうものを出す予定ですと、活動現況報告をした上で提言として出す予定ですと、こういうふうに進めていきたいと考えています。","id":"exchange-009"},{"speaker":"須藤委員","kind":"意見","question":"どうだろうというようなことをしないと、先ほどの話ではそうでもない、今後の課題だというふうに思っている。活動報告というものがきちんとまとまったもの、課題のもの、それを出していくという仕組みでいいと思うのだけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ここはこういうふうにしてほしいとかと、いろいろな意見を出し合って、そして次回のときにまとめていただいたものを最終的に確認するという。ですから、皆さまの合意がとれればいい話ですから、もう少しまとめていただいたほうがいいのではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須藤委員","kind":"意見","question":"今、南委員が言ったように、これもついてくるのですというような話で説明していってくれればいい。進行の仕方が若干、入ってくるからいろいろな意見が出てしまうということの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"提案","question":"ならば、須藤委員が言うように、具体的検討事項のまとめも活動現況に入れるということがまず前提になります。再度提案してくれたほうが、本日ここでずっと議論するよりは、非常にまとまってくるのではないでしょうかという提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"それで、本年度も３月６日までにそれを出してというようなお話であったと思うのです。この中で委員長会へ出ていらっしゃる委員の方、どのように解釈されているかというところも含めてお伺いできればと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"ある程度ベースができているわけですから、お二人がまずそのことを確認するように展開していかないと、いろいろな思いをお持ちですから。そこが申しわけないけれども、もっと頑張っていただかないことには、これはまとまらないと思いますので、再度ご検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"提案","question":"１番目です、今すぐ行政側に提案していって、大体意見的には言っていたと思う。ですから、今後参考にされたいとか、提言としてまとまりますというようなことでやっていってもらいたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"私、議論の間にも何度も繰り返させていただいたのですけれども、基金を増やすことについては慎重であってほしいというふうに思っております。両論併記でも少数意見でも構いませんので、基金の数を増やすことには慎重な意見もあったようなことが伝わるような文章にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"現況報告ですから、まとめにしましても、いろいろな意見を出していただけるようにしていただきたいというふうに思います。その辺の表現についても、慎重に、正確にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"どういうふうな取り出し方をするのか、標題をつけるか、これはまさに正副のツールなのかと思っています。皆さまの総意がとれれば、ぜひ提言というような前向きに検討してくださいというようなことでやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"意見","question":"私は一番そこが、どこまで具体的に書くかはお任せするとしても、その部分かと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"次の委員会しかないので、議事録をよく研究をしていただいて、本日もいろいろな意見があった、１つの意見、物事に対して賛成も反対もあった。１回しかない委員会がまたこういう形になると非常にもったいないし、むだだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"まとめのほうで、文言的に、ほかの委員からも指摘があるかもしれませんけれども、この際ですから、４段落目の最後の部分です。ちょっと細かいですけれども、もうあと１回しかないから。","respondent":"中塚委員長","answer":"そして、できるだけ早くとのご意見もありましたので、丁寧に進めていけたらと思います。３月６日までに議長に提出する活動現況についてですけれども、内容を改めさせていただいて、そのような進め方でよろしいでしょうか。","id":"exchange-022"},{"speaker":"須藤委員","kind":"意見","question":"１年間のまとめとして出せばいいの、全部を。その中に委員会としてはこういう言葉で提言をしていきますということが最後に出てくればそれでいいことなのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"それは２枚になってもいいですけれども、１通のあれでして出すのが普通ですという話をしていた、そういう形でまとめてほしいと求めました。次回にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"若林委員","kind":"意見","question":"いわゆる活動はこれだけですと、委員会の回数とか、視察に行ったとかというものを議長に出す。それを今回は、正副のお考えはどうかわかりませんけれども、それを１つにまとめてしまうというお話なのですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"須藤委員","kind":"意見","question":"理事者のほうにも経過だって、議会で今何をどういう状況で、どういう話になっているのだということを知らしめなければいけない。先ほど来、全体のあれを議長にもやって、きちんとまとまって提言として上がってくるものは提言として上げていいよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"区長部局を意識したまとめは、それだけで１つの文章にするという今までの慣例というのか、そういうやり方でいいのだと思うのです。書かないで話を聞かないとだめだ」と呼ぶ者あり〕 〔「聞いている」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"もう時間が１回しか残されていないので、またこんなふうに繰り返さないように、そのこともあわせて意見として言っておきたいと思いました。かき回すつもりはございませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842551?Template=document&Id=5982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14265,"voices":49}},{"id":"h27-20150122-18","meetingId":"h27-cm01","date":"2015年1月22日","dateIso":"2015-01-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば品川区の出張所なのか、品川区の庁舎なのかといろいろ考えはあると思うのですけれども、その辺を教えてほしいと求めました。それをわざわざ横断幕化するかというのは別としても、できる限り掲げていただきたいと思っているのですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そして２点目の団体のチームですけれども、例えば表の４番、それで出身校で掲示をするという形になっています。そのチームが、例えば連合チームだとかそういうことであるならば、学校のほうで連携をとっていただいてそこに張るというような形をとっています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"以前にも、スポーツ都市にしていくという思いがあるのであれば、ぜひいろいろな幅広い観点からそれを盛り上げていくために何かをやっていただきたい。そういうところに力を入れて育成していくというのですか、そういった方向にもつなげてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、課としての連携というのはどういう形で、そのあたりのことを説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"平成２３年、平成２４年という年を重ねるごとに、それは浸透してきたということです。そんな形で、公立、私立を問わず、連携をさせていただいているです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"地域の中の学校ですから、こういった横断幕は結構学校のアピールとしても使える部分があると思うのです。全額区でやられているかと思うのですが、そのあたりの連絡というか、コミュニケーションはどうなっていますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"例えば、７番、８番のところなのですけれども、品川女子学院のところです。１本についてはこちらのほうで予算がありますのでぜひということでお話を申し上げまして、掲示をさせていただいているです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう制度になっているのかということを１点お聞きしたいのと、ほかのことについてもということでしたのでちょっとお伺いしたいのですが、いかかか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"ちょっと今、平成２１年３月の区民意識調査ということで、品川区民の２０歳以上の２,０００人を対象に行いました。そこのところで、ほとんど毎日と、週１回から２回の人がやっているパーセンテージですが、この当時、４３.８％です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎日と週１回を合わせてということですか。そして、どういう要求があるかというふうなところもそのアンケートで捉えられていたら教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"月に１回とか、月に２回、それぞれについては調査してございません。何をやりたいですかというような質問は、そのときの調査は実施率だけで、そのときは種目まではやってございません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"働き方なども見直していくこともすごく求められていると思いますし、そういうところでは区としてはどう考えられているのかという思いがあるのですけれども、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"親しむ場所、環境をつくるということは私どもも最重要課題として取り組んでいるところです。あわせて、施設の場合は、改修だとか修繕に合わせて少しずつ多目的にできるような状況にもつくっていっているです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう区民の皆さんがどういうスポーツ振興についての要望があるのかという辺りも、具体化をしていただきたいというふうに思うのですけれども、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"これからますます２０２０年に向かって皆さんのスポーツの意識も上がってきます。そんな中で我々も生活の中にスポーツということで、区民に対して気軽にできる環境をあらゆる方面から整備をしていきたいというふうに考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"では、ぜひ区民の実態もつかんでいただき、要望もつかんでいただきますようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"後半の部分で、「区民同士のつながりを深め、地域のにぎわいと活性化を図る」これも目的です。これまで４年間、事例があれば教えていただきたいのと、それも含めて説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"意識が高まったり、子どもたちのつながりがあったり、地域が１つになるという実感はつかんです。これからもそういうような形で、この事業をますます普及発展させていきたいというように考えてあります。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"全国的に見ても、日本代表がどうこうすれば日本全体が盛り上がるということがあると思います。既にやったことがあるかもしれませんけれども、その辺があれば教えていただきたいのと、そういう考えについてはどうか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"４番のワールドカップの野球のこちらの選手の方が卒業されましたので、そういうような形で地元還元ということでやっていただく場合もあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"意見","question":"ぜひいろいろな角度で検討していただいて、その方がまた語っていただくことで、まさに区民のそういった文化芸術・スポーツ活動の振興につなげていく。しっかりと品川区でも顕彰もしつつ、また品川区にもご貢献いただくといったことで、ぜひ積極的に検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"裏面のまちづくりに関することの（３）で、各交通機関の整備が一層のバリアフリー化につながるよう配慮を求めていくことということなのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、あれだけ要望が強い問題ですので、しっかりと入れておいたほうがいいのではないかなと思うのが１点です。それと、区の行政が規制緩和したほうがいいという項目については積極的に取り組んでいくことということとして書かれているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、区民から要望があったから、それはどんどん積極的に何でもやるべきだということに捉えられるような表現ではない表現にしていただきたい。もしもそこのところがまだ不確実でしたら、ぜひ今後に向けても入れておいたほうがいいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"渡辺委員長","answer":"先ほどの特区のところ、ここの表現は文章全体、その部分だけではなくて、正副でまた再検討させてください。では、その２点を預からせていただきます。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"要望、まだ始まったばかりでして、（１）「区民のスポーツ活動が支障なく継続できる」というような表現で私はよろしいのではないかと思います。（３）の「特区の適用による規制緩和については、さまざまな取組みの説明がなされた中で、その辺だけちょっと説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/515238?Template=document&Id=6468#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":13013,"voices":42}},{"id":"h27-20150220-3","meetingId":"h27-c-budget","date":"2015年2月20日","dateIso":"2015-02-20","committee":"予算特別委員会","time":"午後 ２時０５分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"何卒、皆さん、効率的で実りの多い委員会運営にご協力をお願いいたします。僕もこの場で皆様の議論を得々と聞かせていただきますので、実りの多い議論、楽しみにしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592877?Template=document&Id=1016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":2142,"voices":16}},{"id":"h27-20150223-6","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"区民委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"第２０号議案、品川区公共の場所における客引き行為等の防止に関する条例","agenda":"第２０号議案、品川区公共の場所における客引き行為等の防止に関する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"しかも過料については１０月１日ということで、周知期間３カ月という説明があったのですが、その周知期間は必要なのでしょうか。できれば４月１日から施行にしていただければよかったなと思うのですけれども、その点についていかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"できるだけ早くというご趣旨はよくわかりますが、この条例の施行のためにいろいろな周知をしていく必要があると思っています。こういった準備をするためには、やはり３カ月程度の期間を設けてしっかり知っていただく、こういうことが必要であるというふうに考えております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"かなり悪質な状況ですから、できればもっと早いほうがよかった、これは意見とします。そういったところの特定地区の今後の考え方というのは、今の現時点でのイメージでは、どういうふうにお持ちなのか説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"指定区域の範囲につきましては、初めから広い範囲にしていくことは、やはり実効性の点から問題があるというふうに考えています。さらにその後のその他の地区の客引きの状況、これを見ながら広めていく必要があるかどうか判断しながら進めていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"これから例えば地元のお店の方や地域の方がそういう執拗で強引な客引きに向けて注意をしたときに、逆手をとられないような対策というか、その辺はどういうイメージなのかとの意見を述べました。","respondent":"上垣外生活安全担当課長","answer":"この条例の裏づけに基づいてきちんと指導する、注意するということが可能になってきますので、そういった問題は減ってくるのではないかというふうに推測をしております。","id":"exchange-003"},{"speaker":"本多委員","kind":"意見","question":"そういうトラブルがなくなるように、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"この中で何点かお伺いしたいのですけれども、ここはもう公表ということなのですけれども、公表についてなのですが、どのような手段で公表されるのか。一般の方とか、そういう方が知り得るような公表の仕方になるのか、その辺を１つお伺いしたいと思います。","respondent":"上垣外生活安全担当課長","answer":"公表の方法につきましては、最低限、区役所の掲示板に掲示するということは必要だと思われますが、その他、例えば区ホームページに掲載するということも、効果的なものであればそういったものも検討していきたいというふうに考えております。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"それが区民の方によく知れ渡って、さらに強化をしていただきたいと考えていますので、この手段についてはさらに検討してほしいと求めました。もう１つ、今回は入っていないと思うのですけれども、この点についていかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"第１５条の両罰規定によって処罰をすることは可能ですし、直接指示をしてこういった客引き行為をさせたということであれば、第６条第２項の規定によって処罰するというふうに考えています。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"そのような形で店側にも注意を促すというのでしょうか、このような考え方を持っていかないといけないと思っているのですけれども、この点いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"罰則がないといたしましても、こういった環境を排除していくために店の協力というのは当然必要ですので、そういったことに関与しないように協力を求めていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"浅野委員","kind":"意見","question":"規定をどうするかという考え方もあると思うのですけれども、やはりお店の側が客引きに対して断固たる決意で営業するというような、そのようなことも推進をしていかなければならないかと私も感じておりますので、この条例が実効性のある形で進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この条例のことについて伺いたいのですが、１つは、そこら辺のところをお聞かせいただきたい。地域の住民団体のほうからそういう条例をつくってほしいという要望が出されて、具体的なところでわかるものがあったら教えてほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"第１番目の２３区内における客引き防止条例等の制定状況につきましては、私のほうで９区でこの条例が定められているというふうに認識をしております。かつ、区民委員会で十分議論していただけるものというふうに考えております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"結構ほかの区は、目的です、なぜ「区民等の責務」というものを目的の中に入れたのかということもお聞かせほしいと求めました。第２条で、なぜ品川区が全ての事業者を対象にするのかというところを教えていただきたいのと、全ての業種にしたというその理由とあわせてとの意見を述べました。","respondent":"上垣外生活安全担当課長","answer":"２つ目の目的として、区全体でこういった環境を改善していこう、こういった考え方から目的のほうに組み入れております。同じ場所で執拗な客引きをする、どんな業種であっても執拗な客引き行為については迷惑な話ですので、業種を問わず規制をした理由であります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特定地区というのは決めていくということなのですけれども、ここの特定地区というのは、とりあえず五反田駅周辺ということになるのでしょうか。だから、区内全域の対象地域と、それから特定地区との違いというのはどういうところにあるのかということもお聞かせいただきたい。","respondent":"上垣外生活安全担当課長","answer":"２つ目の地区の指定については、五反田地区を今は考えております。第７条にいうところの指導につきましては、指定地区内外を問わず可能という構造になっております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"勧告、公表、そこまでは全ての地域で適用になっていくということなのかということが１つ。この「あらかじめ指定する者」というのはどういう人なのかということと、そこら辺のところがもうちょっと、もうちょっと詳しく説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"２つ目の「あらかじめ指定する者」につきましては、それをやめなさいという指導をしていくことになります。この条例が基準です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めてこれを施行するわけですから、客引き防止条例の指導をする人ということであらかじめ指定をするという人が指定されるということなのでしょうか。それが何人くらい、どういう形で指定されて、どういう活動をしていくのかということもイメージできるようにお願いします。","respondent":"上垣外生活安全担当課長","answer":"現在、１４名で早番だとか遅番、いわゆる近隣セキュリティシステムの「まもるっち」緊急発信の対応等を含めてローテーションでやっています。に、計１６名のローテーションでこの取組みを含め、ローテーションで対応する体制を整えていきたいというふうに考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この生活安全サポート隊が２名増員になって１６名になって、ローテーションでパトロールをするのですか、公表というふうな形になっていく。特定地区以外のところは、とりあえず今回条例の対象にはなるけれども、指導されるというふうな体制はとられないということか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"おっしゃるとおり、条例の適用範囲は区内全域ですので、区内全域で指導することは可能です。ただ、これについてはやはり優先順位をつけて考えていくべきというふうに考えておりまして、その範囲でやっていくべきものと考えております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"全域を対象にされるということはないのですか。そこのところをお聞かせいただきたいのと、あとは、今回この条例を実施するにあたっての予算についてもあわせてお聞かせほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"２つ目、おっしゃるとおり、あるいは警察署の協力も得て一緒に回るという形を基本的な形として取り組んでいきたいというふうに考えております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"指導の基準なのですけれども、先ほど、指導の基準はこの条例に基づいてということなのですけれども、この条例はすごく大まかな条例ではないですか。品川区の五反田などはどういう状況になっているのかということもお聞かせいただきたいのですけれども、事業者、そこら辺についてはいかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"１点目の指導の基準につきましては、実際に運用するための要綱、マニュアルのたぐいは、今後策定していく予定をしております。日本のこういう不利益を科す処分につきましては、やはり生身の人間の行為がまず処罰の対象の第一であろうというふうに考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"若い人が仕事、雇用の厳しい環境の中で、そういうアルバイトをやっているという人もいるのではないですか。そうすると、どれぐらいの時間帯と回数と体制でやっていくのかということもお聞かせほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"時間帯につきましては、夜の８時を中心とした時間帯です、この時間帯を中心に考えております。回数につきましては、月曜日から土曜日まで、基本的には毎日実施したいというふうに考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、もともとに国の風俗営業等の規制及び業務の適正化等に関する法律と、それから東京都の迷惑防止条例がありますね。そこのところで、それだけではどうしてもだめだというあたりの、そこの根本的なところをもう１回お聞かせほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"そのために、一定の時間、労力がかかりますので、毎日毎日やるということは無理な話なので、現実的には無理な状況があります。区、日々継続して指導を行うための法令上の根拠、これを与えるために今回の条例を提案させていただいた次第であります。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その風適法とか迷惑防止条例では、日々そういうふうな形ではできないのですか。罰則ということを目的にしないと、日々そういうふうな形での見回りだとか、指導ということはできないという仕組みになっているということなのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"全くできないという趣旨ではありません。それなりに準備等が必要なので、今この条例が想定しているような毎日毎日見回って指導するというところはできないというのが現状であります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、そこの条例や法律でもできるけれども、そこまでの体制になっていないために、それを区の条例でカバーするという、そういう形と考えていいのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"体制だけの問題ではありませんで、実際の取り締まりのやり方ですね、これについても一定の限界があるというふうに考えておりますので、やはり区、区民等が継続して行うための根拠が必要であるということで、この条例を提案させていただいているものであります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"提案","question":"じゃあ都庁だか警視庁だかの帰りに五反田でおりて現場を見てきますというようなお話をいただいたことを今思い出しつつ質問をしますし、自民党のほうから条例提案が出ているという形で上がったというのは、最重要目的は何か尋ねました。","respondent":"上垣外生活安全担当課長","answer":"これは条例第１条の最後のほうに記載をさせていただいていますとおり、区民の安全で安心な地域社会の実現に寄与すること、これが最重要な目的というふうに考えております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"提案","question":"みんな生きていくためですから、頭いいです。せっかくこういう条例をつくったのですから、特に本当に気弱と言ったら失礼かもしれないけれども、その辺についてはいかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"これを背景に、強力な指導を継続していくというために罰則を設けさせていただいているところであります。警察等が連携して、日々継続的にまちに出て指導していく、こういった取組みを継続していきたいというふうに考えております。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜ出るかというと、２０２０年にオリンピックでいろいろな方が来る、海外の方もいらっしゃいますよね。間違いなく２０２０年のオリンピックのときには客引きゼロ、どちらの担当が答えてくださっても私はいい、その辺の答弁をいただきたい。","respondent":"上垣外生活安全担当課長","answer":"実際に他区の例を、この客引きの対応のためにパトロールすることによって、客引きが減ったという結果が出ています。さらに、そういったことも視野に入れてしっかり取り組んでいきたいというふうに考えております。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"本当に品川区、これからすばらしいのだと夢を持ちつつ、今日の質問を終わらせることができました。本当にどうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"何点かお伺いをしたいのですけれども、第５条の区民等の「等」は、何を想定しているのか。第８条の特定地区の指定なのですけれども、どういう形で指定をして公表するのかということと、そこまでまずはお聞きしたいのです。","respondent":"上垣外生活安全担当課長","answer":"は区内を通過する者および営業その他の業務の用に供するための場所を提供している土地または建築物の所有者または管理者ならびに区内において事業を…具体的に五反田地区という表現ではなくて、例えば西五反田何丁目という形で丁目を示して特定したいというふうに考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"区民等が自主的かつ相互に取り組むということは、その辺の人たちに自主的かつ相互に取り組むことを求めているというふうに理解をするのでしょうか。積極的関与が必要というふうに考えるのであれば、対策として周知方法とかをとっていくのか、２点について説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"やはり区としてそういうふうに取り組んでいただけるように積極的に働きかけていくということが必要だというふうに考えております。ですので、こういったところにも直接働きかけをして、この条例の規制内容等について周知をしていきたいというふうに考えております。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"周知をするのはわかったのですが、具体的にどういったことを今は考えていらっしゃるのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"具体的には、この施行日に向けてキャンペーンを開催するだとか、あるいは、広報啓発用のチラシを配布する、こういった方法を考えております。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問・要望","question":"客引きのイメージはもっと遅いのではないでしょうかと思うのと、ここのところで本当に対策を打とうとするのであればどうなのかなということについてのお考えをお聞かせいただきたいのと、そこの関係をもう一度詳しく整理をして説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"指導体制につきましては、サポート隊について、昼過ぎに出勤いたしまして、夜の１０時までの勤務時間を今は考えております。つまり、区長は、違反行為を中止するよう指導することができるというところの「区長」の実際の担い手がサポート隊という理解をしています。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"第２項に、あらかじめ指定する者に前項の規定による指導を行わせることができる」ということなので、普通の区民ではないということですか。ある程度何か経験者であると、そういうことか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"不特定多数の区民の方にお願いするものではなくて、やはり必要なご意思と、あと必要な知識を事前に持った方を指定することを想定しております。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"では、ここの「あらかじめ指定する者」というのは、何か基準があってこういう人材であるということを取り決めた上で、自薦、他薦とか、そういうレベルのものではなく、こういう要件を満たした人ということをこれから規則でつくるということで考えてよろしいのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"どのような方を指定するかについては、おっしゃるとおり、規則等で要件を定めて指定をするという手続を踏みたいというふうに考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１回確認なのですけれども、先ほど、この条例のかかわりによって何か変わることがあるのかということを確認をさせていただきたいのが１つです。そういう区民の実態と品川全域の実態とこの区民の責務というのが齟齬があるような感じがするのですけれども、そこのところと、２点説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"１点目の条例の適用範囲につきましては、おっしゃるとおり、区内全域ですので、全域の中で指導は可能であるということになっています。２点目の客引き防止に関しては、人に迷惑をかけるのだよ、こういった意識の啓発を図っていくというのが重要であるというふうに考えております。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"実際の活動そのものは、五反田だけのパトロールになって、全域のパトロールというのはしないわけですよね。どういう形でその指導は可能、可能だけれども、実際はどういうふうにされていくのかというのがちょっと見えないのですけれどもとの意見を述べました。","respondent":"上垣外生活安全担当課長","answer":"ただし、必要な体制を有効に使うためには、やはり特定地区を優先的に実施をしていく。優先順位をつけて実施していくのが重要だというふうに考えておりますので、まずは特定地区を中心にやっていくべきものというふうに考えております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確認なのですけれども、それで先ほどから確認をさせていただいているのですけれども、全域にかかるというその具体的なところがイメージできるようにお聞かせいただきたいのです。","respondent":"上垣外生活安全担当課長","answer":"実際には、特にそういう実態が出てきた、しつこい客引きがあるということが特定地区以外であれば、例えば生活安全サポート隊がそこへ行って指導するということは可能ですし、そういったことも必要であろうというふうに考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"先ほどからそういうことで確認させていただいたのが、そういうふうな形で適用されるということでいいのですかということで先ほどから確認させていただいているので、それでよければそれでいいのですけれども。","respondent":"上垣外生活安全担当課長","answer":"そのとおりであります。","id":"exchange-034"},{"speaker":"沢田副委員長","kind":"提案","question":"先ほど来、安全で安心な地域社会の実現ということで、この品川区という自治体の中で必要な条例であるということで条例提案がされているわけですから。悪質な業者に対してはどういうふうに罰則をしていくのか説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"その貸し主の要望にこたえるのが１つと、あと、その契約関係を通じて適正な営業をしていただけるよう促すことを期待しているものであります。２つ目の過料につきましては、その手続を踏まえて、違反を繰り返した場合に悪質と認めて過料を科すという構造になっています。","id":"exchange-035"},{"speaker":"沢田副委員長","kind":"質問","question":"そういうところに貸していていいのですかという契約上問題があるのではないかということを説明したりするということでよろしいということですか。そうすると、当然、その辺はどう考えていらっしゃるのか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"２つ目の過料につきましては、やはり違反行為をして指導した、それは指導を１回カウントします。勧告に違反したら、またそれは勧告違反で１回カウントしていく、こういう形で手続としては進んでいくということを想定しています。","id":"exchange-036"},{"speaker":"あべ委員長","kind":"質問・要望","question":"どうもそうではなくて、とすると、それを補ってくださるような準プロフェッショナルな方々みたいな感じでイメージをされているのでしょうか。この方々の役割がよくわからないので、もう少しご説明いただけると、どういうイメージを持っていらっしゃるのか教えてほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"全くの区民、その対応に必要な知識をこちらのほうからあらかじめ指導、サポート隊と一緒にまちをパトロールしていただくということを想定しています。ですので、サポート隊以外にこういったあらかじめ指定する者と一緒にこの取組みを進めていくという趣旨です。","id":"exchange-037"},{"speaker":"井上委員","kind":"提案","question":"先ほど来、各委員から「区民の責務」というところで、ちょっと違和感があるということで、ここのところを委員会修正という形で文言整理をして、できればそれがいいという提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"井上委員","kind":"提案","question":"第５条「区民等の責務」とありますけれども、第５条の「区民等の責務」については、「区民等の責務」というのには違和感があります。ですので、文言は別として、「責務」という表現を修正をすることを提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"本多委員","kind":"意見","question":"やはりそれが最大の目的ですし、我々も本当に区内の商店と商売繁盛、健全な経営をしている商売繁盛を願っております。この辺が本当に課題になっていると思いますので、ぜひ課題克服に向けて条例が制定されることを望み、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"賛成です。今後とも引き続きこのような対策というのでしょうか、まちづくりのための方策などを徹底していってもらいたい、そのように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"多くの区が骨子案を提案をし、そしてまた条例を提案するという形で何度も議会で議論もし、その進め方が１点です。それともう１つは、客引き防止は必要だと思いますけれども、この条例に関しては反対という態度ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"井上委員","kind":"提案","question":"しかし、やっぱり骨子案という形で委員会に提案をしていただくということが必要だというふうに、区民にかかわる大きな条例ですので。それから、区民の積極的な関与ということを求めるのであれば、区民にとってもメリットになりますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"確認","question":"補正予算の審議にもかかわるところにもなるかもしれませんが、答弁の中で、大型店舗も含めて検討していくというような答弁があったかと思います。そこはちょっと定かではありませんので、そのことについて、方針として詳しく改めて確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":32050,"voices":107}},{"id":"h27-20150223-7","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件整理しています。","topics":[{"id":"topic-01","title":"第２７号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２７号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か、確認で質問させてください。ここの資料では６人増、２０人増となっていますけれども、品川区のお考えを合わせて説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"少ないところで１１人、多い月で１７人といったような状況で、この中で埋められるのではないかと考えています。実施した結果、またもう少し必要なことが判明すれば、またそこで変えていくようなことは柔軟にやっていきたいと思っているところです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"現行はそういう人数なのでしょうけれども、でも全高齢者となったということは、当然対象が増えるわけではないですか。今のサービスで１１人から１７人だというお話をお伺いしましたけれども、品川区内の高齢者は約４万５,０００人くらいでしたか、全高齢者対象だから。","respondent":"永尾高齢者福祉課長","answer":"基本チェックリストをやりながら、その中でということなので、全員が来るということを想定はしておりません。少し遠くて利用しづらい方もいらっしゃいますので、そのあたりの実績を見ながら、柔軟に考えていきたいと考えています。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"ただ、申し込む方が増えることは、当然想定されるわけですから、そのことについての対応の確認でした、よろしくお願いいたします。負担をできるだけ少なくしてこういうふうにしたという、それだけの説明が必要だと思うのですが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"１２月にご説明いたしました第六期介護保険事業計画の骨子案のお話になるかと思います。高齢者人口が今後３年間伸びていくという想定と、内容としては、やはりご負担いただく金額も多くなってきてしまうという現状になっております。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"団塊の世代の方々が７５歳以上になる時期、広く多くの区民の方々にご説明していくわけでしょう、これから。この制度の趣旨を間違って理解される部分があると思うので、そのことについての考え方をもう一度お聞かせください、お願いします。","respondent":"永尾高齢者福祉課長","answer":"なかなか保険の制度は難しいところがあるのですけれども、区といたしましても、保険料の冊子も今つくっているところですので、それをもう少しわかりやすく説明するような内容にするとともに、いろいろな機会を捉えて説明していきたいと思っているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"確認","question":"１点確認ですけれども、介護保険料率の改定のほうですが、私の認識が違っていたら申し訳ないのですけれども、第五期の保険料がありますね。その辺で比べてみて、決して高くはないというような認識があるのでしたら、その辺を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"保険料については、今、２３区で情報を集めてはいるのですけれども、まだ２３区決定はしていないところです。集めた情報の中では、品川区は下から２番目というふうに受けとめているところです。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今回また６００円値上げということなので、私は引き下げこそ、また値上げは中止をしていくことが必要だと思うのです。もう１回確認させていただきたいのですが、この間の本会議では、そのことでの残額を教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"そこで不公平感が出てきてしまいますので、今回は、第１２・１３段階のところの変更とさせていただきました。平成２６年度末の見込みが、その残高が約１７億８,０３７万円という数字が、現在のところでは出てきているところです。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"質問でもさせていただいたのですけれども、消費税８％の増税分の２５億円を使ったらどうかという提案をしたのですが、ここでもやはり。引き下げは十分に可能だと、値上げを中止することは可能だと思うのですけれども、そこはどうか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"２３区のほかの状況なども聞いてみますと、どうしても保険料を高くせざるを得なくて、大変に苦労をしているというような話を聞いております。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１１億５,０００万円を取り崩して、これもやはり最終的には１０億円を超えてまた余っていくのではないかと、今までの状況を見ていけば思います。結局幾ら引き下げるのかということをお聞きしたときに、おおよそ見込み額があったということなのでしょうか、それは幾らなのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"秋に説明したときから、事業者の運営のことも考えながら、少し変更をさせていただいているところです。本当に数円単位の話になってくるかと思いますので、今回については、その部分は考慮に入れないで出しています。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、今回の２割、３割単価を引き下げた分は、考慮しないでも大丈夫なくらいの給付費なので、それを入れないで算定したということか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"実際に２割、３割というのが、そこまでにはならないという想定で考えています。どのくらいの時間でサービスをしていくか、それによってかなり上下の幅がありますので、一律にそういうふうに下げているということではありません。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"これだけ引き下げるのに、なぜ算定できたのかと少し疑問だったので伺いました。パブリックコメントも取られていると思うのですけれども、今回のパブリックコメントの集まり具合はどうだったのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"３件の方は、相互扶助システムや情報提供の方法について検討してほしい、という内容です。区に救急対応する総合病院が欲しいので総合病院を誘致してほしい、ということで、７件になっているところです。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですけれども、その７件の中でも、いろいろ充実を求める声なのだと、今、確認させていただいたのです。私たちもずっと求めてきているのですけれども、少しご努力いただいて、そこはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それから、民生委員や区政モニター集会等でも説明をしているところで、ホームページにも載っています。これからの説明会のお話になるかと思いますけれども、区では、介護保険の制度の普及というところで説明をしていきたいと考えています。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ丁寧な説明を、どの分野でもしてほしいと求めました。２,５００万円ほどが、使わずに済むことになるのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"平成２７年度予算の現在の想定の金額としては、このリハビリサービス特別給付費は１,６０５万３,０００円の分が減になります。地域支援事業のほうが１,１２５万２,０００円プラスになるという計算になっております。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私たちはやめてほしい、使うべきではないということを要望してきていたので、どういう基準でされていたのかをお聞きしたいのです。","respondent":"白鳥高齢者いきがい課長","answer":"６５歳以上の要介護認定を受けられていない自立支援高齢者、それから在宅介護支援センターのスクリーニングで二次予防事業の対象者と判定された方を。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そして、認定を受けている方で要支援１、２、要介護１、２程度の人が、この市町村特別給付だったほうを使っていたと。そうすると、今回、地域支援事業のほうに移行されるわけですから、要支援１、２、要介護１、２の方もこの事業は使えるということですよね。","respondent":"永尾高齢者福祉課長","answer":"今のご説明のとおり、要支援１、２の方も、要介護１、２の方も使えるということになります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"当然事業が拡大していくわけですから、やはり区民に十分に説明していただくことは、ぜひお願いしたいと思います。それも合わせて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"向委員","kind":"意見","question":"１点、払うべきところはしっかりということで皆さんよく理解はされていると思うのです、そういうご意見も区民からいただくのですけれども。今後も丁寧に説明を引き続きしていただいて、先ほど伊藤委員からも出ましたけれども、今後もきちんと担保できるようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"値上げ幅も、先ほど見ましたけれども、基準額では６００円の値上げですけれども、第１段階、第２段階の方でも５０５円の値上げです。国費などもさらに上げてほしいという、求めたいと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"確認なのですけれども、つまり全国の自治体が改正しなければならない義務があると思うのですが、そうなのでしょうか。つまり、厚生労働省はこの改正で何を目的としているのか、もしわかれば、答えるよう求めました。","respondent":"永尾高齢者福祉課長","answer":"運営等がしやすくなるということでは、やはり住み慣れた地域の中で暮らしていくということを、国のほうも重視している結果だと捉えております。区として、そういう部分について、ますます事業者が参入しやすい形になるかと感じているところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"意見","question":"そのお考えについて、構想がありましたら、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"認知症対応型通所介護につきましても、共用型認知症対応型通所介護は現在やっておりませんけれども、そういうところも広げていきたいと考えています。その地域の中でどのくらいの需要があるのか、そういうところも考えたうえで、こういう利用の仕方もあるのかとは思っております。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"提案","question":"そうなると、そこで働く人が、今まで以上にかなり負担を強いられてしまうような心配も出てくるのかと思うのですけれども、その辺のところ。今回の定例会の我が党の代表質問の中で、小規模特別養護老人ホームを今後増やしたらどうかという提案に対して、その３点を説明するよう求めました。","respondent":"永尾高齢者福祉課長、大串福祉計画課長","answer":"国のほうも、社会保障審議会の分科会で有識者の方と検討した中で出た意見を反映して、今回の改正になっていると思っているところです。きちんと調査をした結果、兼務が可能という判断の中でやっておりますので… 説明がありましたように、親になって、さらにサテライト型が整備できるといったことが今回の趣旨になっております。その辺、この法改正の趣旨を踏まえながら、この新しい手法についても検討していければと考えているところです。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"働く人の負担とか、介護の質の低下につながらないように心がけていただきたいとしか言いようがないので、お願いしたいと思います。サテライトにすると、今の運営法人しかその運営に携われないということになってしまうのかと思いますけれども、そういう考え方なのか尋ねました。","respondent":"大串福祉計画課長","answer":"逆に、三徳会や福栄会がサテライト型をつくれば、その法人がそのサテライト型の特別養護老人ホームを運営するといった形になります。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"2)は該当してくるのですよね。会議が一つ減るというところでは確かに、これは必要だったからあったものなのではないのか、どうなのかを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"区役所の支援の係の担当者、在宅介護支援センター、これらの方々が連携推進会議に出席しているところです。介護・医療連携推進会議の中でやっているものと重複しているというところで、評価の仕方が単純化されるとか、その辺は心配要らないかと考えています。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私たち、職員が集まってこないというところでの苦肉の策と、だったらその大もとを転換させていくべきなのではないかと私は思います。人員が集まらないというところですが、看護師のところでは、区はどういうふうに見ているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"実際に、こちらは全国的に統一した改正になっておりますので、全国的な流れの中で看護師が集まらない現状というのが出ているのかと考えています。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"人員不足は本当に深刻だと思うので、ここで登録定員も利用定員も引き上げるのであれば、やはり職員の数も引き上げていくべきではないかと思います。(5)のサテライト型のところですけれども、追加される前にサテライトというものがどこかであったのかどうか、説明を求めました。","respondent":"大串福祉計画課長","answer":"ただし、現行の改正前の中でも、サテライト型の開設はできていたといったところです。今回初めて、小規模な特別養護老人ホームでも、いわゆるサテライト型を運営することができるというのが今回の改正になります。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけなのですけれども、下から４行目くらい、設備及び運営に関する基準（平成１１年厚生省令第３７号）」と書いてありますよね。確認したいのは、都道府県の判断でこの基準そのものを変えることができることになったのでしょうか、もしおわかりになれば説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ここの部分についても、地方分権法の関係で、東京都のほうにおりてきておりますので、それを受けて、東京都の条例というふうに変更しています。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはりこれに従ってやっていかなければ運営ができないわけですから、大丈夫ですと言うのは当然ではないかと思うのです。利用される方とサービスを提供する側の現状を見れば、もっとしっかりと対応していかなければいけないのではないかと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"第３０号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例","agenda":"第３０号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"そのことを区市町村に移したのではないかと推測されるのですけれども、やはり確認したいのは、条例制定の目的をもう一度確認させていただきたい。よく予防が大切だということをおっしゃっているわけですから、考えていくべきだと思うのですけれども、その二つをまず説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"介護予防支援ということは、また計画を変更したり、そういうことをする仕事になります。運営とか、その辺が区の裁量でできるようになるということは、とてもやりやすくなるかなと考えています。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"とても介護が必要な方もいらっしゃるでしょうから、その一面、手厚くサポートするべきところもできる可能性があるわけである。そういう計画ができるわけですから、もう一声、品川区の将来に対するお考えを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"相談を受けるところという意味で、介護予防支援というのは、これからの給付の部分で左右されることかと考えています。そういうところもきちんとこの介護予防支援の中で把握しながら、適切なサービスにつなげるような体制を整えていきたいと考えています。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問・要望","question":"裏面の２番の４行目で、そこが気になったので教えていただきたい。その在宅介護支援センターは入らない、いわゆる区の直轄の地域包括支援センターということでいいのかどうか、その確認です。","respondent":"永尾高齢者福祉課長","answer":"「等」の下線については、特に大きな意味はなく載ってしまったので申し訳ないと考えています。介護予防支援につきましても、地区の在宅介護支援センターで計画等を立てておりますので、各地区においても介護予防支援を実施しています。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、いわゆる在宅介護支援センターでもやっているということですか。そうすると、それは品川区として条例化した文章の中には、どういう表現で載っているのか、どの辺に載っているのかも含めて、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"この条例の中に、地区の在宅介護支援センターのことまでは掲載されていないです。この条例の中は、地域包括支援センターということで大くくりに制定しています。","id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"苦情というところの項目で、少し気になったので、簡単にでいいので教えていただきたいのです。こういったものの時間的なスパンは、普通はどういう概念で取り扱われているのかだけ、教えていただけますか。","respondent":"永尾高齢者福祉課長","answer":"苦情等があった場合には、区のほうにも届出をしなければならないという制度があります。モニタリング等調査部会というものを設置しておりまして、区に寄せられた苦情への対応状況とか、助言等を説明したうえ。","id":"exchange-031"},{"speaker":"向委員","kind":"確認","question":"事業者だけではなく、二重、三重に一つ一つ対応していくということでよろしいのでしょうか。念のため、それだけ確認したいと求めました。","respondent":"永尾高齢者福祉課長","answer":"やはり苦情を申し立てた方の状況もお聞きし、さらに、サービス事業者のほうの状況もお聞きしながら、どういうことで納得いかないのかということを分析しながら、一つ一つきちんとした対応をしています。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"一つ教えていただきたいのですが、３．条例制定による効果というお話の中で、区の基準で定めるというお話が出ました。高齢化が進んでおりますので、その辺のお考えはどうか、ちょっと教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"現在も、八潮のほうは高齢化率が高くなっておりますけれども、この先も高くなるという見込みが立てられております。相談体制がまず第一に大事になってくるかと考えていますので、そのあたりは件数、それから内容なども見ながら検討していきたいと考えています。","id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問","question":"参酌と従うべき基準というのは、一番最後の２２分の２０の上から２番目が、これは何か理由があるのですか。それから、一番最後の付則が、漢字が変わっているのですけれども、何か理由はありますか。","respondent":"永尾高齢者福祉課長","answer":"「参照」は申し訳ありません、間違えまして「参酌」になりますので、訂正をお願いします。付則の部分ですけれども、区の条例では「附則」ではなく、現在常用漢字で使われている「付則」で統一しているものです。","id":"exchange-034"}]},{"id":"topic-03","title":"第３１号議案 品川区地域包括支援センターの包括的支援事業等の人員の基準等に関する条例","agenda":"第３１号議案 品川区地域包括支援センターの包括的支援事業等の人員の基準等に関する条例","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"人員配置なども進めたとおっしゃっていたのですけれども、品川区が庁舎に１カ所、包括支援センターというふうにしていることはなぜなのか。どちらが正しいということはないと思うのですけれども、なぜ品川区はそうなのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"１カ所で集中していることが非常にメリットが高くて、品川区では各地区の在宅介護支援センターで、全ての相談の窓口ということで対応しております。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１カ所であることで、情報も電算システムで共有し合えているということですけれども、そうすると、保健師、社会福祉士、主任介護支援専門員というのは、各在宅介護支援センターには配置はされていないということか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それから、主任介護支援専門員につきましては、こちらも非常勤もいますので、２３.８７人となっているところです。全員、主任介護支援専門員となっているところです。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういったことが心配される一つでもあるのではないかと思うのですが、こういうところへの対応などはどのようにされていこうとされているのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"各在宅介護支援センターで個別に動いてしまうと、逆効果になったりすることもありますので、今は、区のほうで直接対応しております。それから、成年後見が必要になる場合もありますので、やはり区が一括してそこをきちんとまとめていくことが大事だと考えております。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういったところで、区に１カ所あるということが、今後どうなっていくのか、区としての考え、包括支援センターを増やしていこうとするのか。だけれども、この配置するべき人たちの仕事を少し請け負ってしまっている部分もあるのではないかと思うのですけれども、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"行政のほうが、虐待とか権利擁護の部分で支障が出たりすることもあるかと感じておりますので、品川区のこのやり方は効率的かと思っています。その辺は、その状況に応じて、これから必要な検討はしていかなければいけないと考えています。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"介護等支援を受ける方々の、利用者の安心・安全が一番大事だと思うので、そのための人員確保、配置すべき職員は、ぜひ進めていってほしいと求めました、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"第３２号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","agenda":"第３２号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認だけなのですけれども、第３２号議案の品川区立心身障害者福祉会館条例の一部を改正する条例の資料で、１．改正理由のところで。ボランティア室の必要がなくなったという判断だと思うのですが、それはどういうことでしょうか、ご説明をお願いいたします。","respondent":"中山障害者福祉課長","answer":"品川区障害者生活支援センターを、平成２１年度には、障害者自立支援法に合わせて機能を変更してきています。地域生活支援センター、地域活動支援センター、上げさせていただいたところです。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、利用される方々の不便等はあるのでしょうか。その確認をお願いいたします。","respondent":"中山障害者福祉課長","answer":"ヘレンケラー協会ですとか、実際にはマッサージ室の利用が少なくなってきたことから、このように事業を変更しています。平成２１年と平成２４年から、利用いただいている団体の方々とも十分にお話をさせていただいて、ご理解いただいたうえで変更してきたところです。","id":"exchange-041"},{"speaker":"松永委員","kind":"質問・要望","question":"１点お伺いしたいのですが、資料の３分の２のところで、部屋が３分の２に縮小されて、料金が安くなったということをお伺いしたのですけれども、では減った分は何に利用されているのか、ご説明ほしいと求めました。","respondent":"中山障害者福祉課長","answer":"変更前が約１２５m2あったところ、変更後は８１m2となっております。この残りの部分につきましては、地域活動支援センター「逢（あえる）」として、今活用されているところです。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それぞれ条例の左のほうの書面の上の段の、ボランティア室とパソコン室とマッサージ室がある表で、それぞれ何m2あった部屋なのか、ちょっとお聞きしたいのですけれども、わかりますか。","respondent":"中山障害者福祉課長","answer":"多分畳みにして１０畳くらいの部屋かと思います。ボランティア室も同じくらいで、そう広くはない部屋になっております。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"共同事務室は、７団体と一緒にボランティアの方々が使っている。録音室とパソコン室が……それぞれの今の用途を、もう一度教えていただいていいですか、すみません。","respondent":"中山障害者福祉課長","answer":"ボランティア室については、現在、地域活動支援センター「逢（あえる）」として使っています。マッサージ室につきましては、生活支援センターとして、主にピアカウンセリングですとか、個別の相談の場として使われているところです。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そちらに移っていってしまうというのは、使いづらかったということなのでしょうか。なぜ減っていってしまったのかを伺いたいです。","respondent":"中山障害者福祉課長","answer":"例えば東京都の視覚障害者生活支援センターであれば、マッサージのほかにもパソコンであったりとか、さまざまな訓練ができます。あるいは、やはりそういうところで訓練を受けられたほうが、より具体的にその方に合った訓練ができるのではないかと考えているところです。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"では、マッサージは、今の方々は東京都のほうを利用されているということで、少ないからもう需要もないのでなくしていくと。訓練室の３分の１、常にいる団体になっているのでしょうか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ここには当然、職員とボランティアが配置になって、通っていらした障害者の方たちの日中活動、趣味活動を支えているといった場になります。特段どこかの団体に貸し出しをして、事業として行っているわけではございません。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"利用されている方の話を聞くと、活動する場がどんどん狭くなってきているという声も伺いました。少し手狭になっているという質問も、いろいろときれいにされているという話なども伺うのですが、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"文化センターとかを併せてご利用いただくことで、地域に障害者の方が出ることで、より多くの活動の場面が広がっていくと考えています。耐震化につきましては、こちらは現在、耐震チェックをして大丈夫ということになっているところです。","id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうしたら、チェックということは、耐震診断をされたということで、どういうふうに耐震化がされたのか。旧耐震の時代の建物だと思うのですけれども、耐震診断をして、そこでオーケーが出たということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"そのとおりです。耐震診断をして、その結果、新耐震基準に合致しているです。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今は２階の部屋でグループになって、そういった声は区のほうには届いていないのでしょうか、私のほうでは聞いているのですけれども。障害者が、こういった施設をさらに狭くしていくというところでは、区としては今後の障害者支援のところをどう考えられているのかと思うのですが。","respondent":"中山障害者福祉課長","answer":"区内にある貸出施設に、障害者の方が自由に使えるようなバリアフリー化を進めていくというのが、おそらく今の世の中の流れではないかと考えています。貸し館としての場所については、障害者に特化した貸し館を増やしていく予定はございません。","id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういう形で、全部一緒にしなくても、広く使っていくことはできるのではないかと思うのです。ですので、これ以上狭めるのではなく、さらに広げていく方向で考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"反対です。やはり障害者の方たちが安心して使える施設をさらに大きくしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-05","title":"第３３号議案 品川区障害者福祉手当条例の一部を改正する条例","agenda":"第３３号議案 品川区障害者福祉手当条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"合わせて聞きますけれども、当然、財源が必要なわけであって、これは品川区の一般財源なのでしょうか。例えば東京都全体だったら財調はあるのでしょうけれども、要するにどこからお金が出ているのかということを、併せて、答えるよう求めました。","respondent":"中山障害者福祉課長","answer":"そこの増で、先ほど申しました３億４,７００万何がしの金額になります。それから、財源につきましては、この手当につきましては区の単費となっているところです。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"難病のほうが少し気になったのですけれども、増えるのは、もちろんいろいろな基準があるのでしょうけれども、これも区の財源なのですか。それぞれの区で、各区の判断で決めることなのでしょうか、答えるよう求めました。","respondent":"中山障害者福祉課長","answer":"難病の指定自体は、国のほうで指定するのですけれども、この福祉手当につきましては、特に国や都から財源が来るものではありません。それから、近隣の各区につきましても、それぞれ各区の事情に合わせて、全体の障害者施策を考える中でこの手当の額についても決定しています。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから続いていくでしょうから、毎年３億４,７００万円余の新規の増加になったわけですから、さまざま財政部門とも調整をとっていただいて。それからもう１点、ぜひ国に要望してください、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、これは対象者に対して個別に周知をされるのか、周知の方法をどうするのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらの手当につきましては、広報やホームページでもお知らせはいたしますが、現在、もう既に受給されている方につきましては、そのお手紙の中で合わせて、このように金額が変わったことをご通知していきたいと考えています。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この引き上げは、私たちもずっと求めてきていましたので、本当に良かったと思っています。改正理由のところで、障害者一人ひとりに即した日常生活の質を高める支援が求められているというところで。","respondent":"中山障害者福祉課長","answer":"それは本当にお一人おひとり違うと思うのです。趣味活動であったり、社会参加であったり、そういったことも、日常生活の中でその人らしい生活ができるように支援したいです。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"一歩がなかなか難しかったりというところもあると思うのですけれども、そういったところでの手当の支援は本当に大きな支えになると、私も思います。対象も、先ほど言われましたけれども、精神も入るということなのか、少し聞き取れなかったので、もう１回お願いしますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"この第二種手当の中には、精神障害者１級の方が含まれています。これは、品川区と、ほかには杉並区だけのことです。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり生活の質を高めるための支援というところでは、品川区だけではなくて、まだまだ全体的に低いと私は思います。障害を持たれた方の生活、そして社会参加を応援していく支援ができるように、区としても働きかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"たけうち委員","kind":"質問","question":"それ自体は、トータルの金額は変わらないのか、そこだけ教えていただけますか。","respondent":"中山障害者福祉課長","answer":"この障害者福祉手当につきましては、生活保護の収入に認定されませんので、プラスとして考えていただければと考えています。","id":"exchange-059"}]},{"id":"topic-06","title":"第４２号議案 指定管理者の指定","agenda":"第４２号議案 指定管理者の指定","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、この場所については、5)の規定によって公募するのが適当でないと認められたということですよね。公募をするのが適当であると判断する場合と、適当でないと認められる場合の差は、どういうふうにお考えなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"その他全て厳正な審査をした結果、指定管理者候補者として選定をし、今日に至っているという状況になっております。少し違った順番でやっておりますけれども、結果的にはきちんと公募をして、その中で選んでいるという状況になっております。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"私の質問が少し悪かったかもしれませんけれども、福祉のこういう関係のものについて、公募をすることもありますね。ですから、公募をする基準と、公募をしない基準の差は何なのでしょうかということをお伺いした。","respondent":"永尾高齢者福祉課長","answer":"運営事業者の公募としては、もう既に建設の段階で公募をして決めておりますけれども、指定管理者としての公募は、二重にやる必要がないため省略をしているということになります。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"確認","question":"すみません、確認ですけれども、この施設を建設するときから、恵愛と何かしらそういうやりとりがあったということなのですか、それを確認したいので、改めて答弁をお願いいたします。","respondent":"大串福祉計画課長","answer":"そのときには、３者手が挙がりました。運営事業者、平成２５年５月に事業者の決定の報告ということで、厚生委員会のほうにはご報告をさせていただいているといった経過になっております。","id":"exchange-062"},{"speaker":"たけうち委員","kind":"質問","question":"４月以降の予算のほうにもかかってしまうといけないのですが、区のほうで２万４,０００円を上限に何かやるというのが、出ていますよね。それとも、あくまでそれは決まってから、その事業者に任せるのか、どんな考えなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今、運営しているグループホームについては、全部事業者あてに情報提供をしています。竣工いたしましたら、手を挙げていただきたいと区としても考えておりますので、そういうふうに指導していきたいと考えています。","id":"exchange-063"},{"speaker":"向委員","kind":"質問","question":"１ユニットということで、普通は２ユニットという話で、過去にも議論がありました。５年経った後に、その辺りをどのようにお考えか、お伺いできればと思います。","respondent":"大串福祉計画課長","answer":"あるいは設計事業者と綿密に連絡を取りながら、また、地域の皆様のご協力を得ながら整備を進めてきているところです。区のほうといたしましても、この法人が健全に運営をしていけるような形でのサポートについては、引き続きやっていきたいと考えているところです。","id":"exchange-064"},{"speaker":"向委員","kind":"確認","question":"一つ確認ですけれども、私の記憶が確かだとすると、基本公募によらないでというところで、もともと品川区内の事業者にお願いするという話でしたよね、それだけ最後に確認したいと求めました。","respondent":"大串福祉計画課長","answer":"平成２５年１月に公募の要領を発表したのですが、そのときに、区内で同種の事業をやっているという形での公募になっていました。逆に言いますと、本社が他の区にあったとしても、品川区内での運営実績があるという形での公募になっていたと記憶しております。","id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"株式会社の事業実態、運営実態をしっかりと見ていくための仕組みというのは、品川区ではちゃんとつくられているのか。それがあるなら、それを私たちがどのように知ることができるのか、説明を求めました。","respondent":"大串福祉計画課長","answer":"運営事業者の公募の中で、ご提案いただいたアイデアの中で一番いいものということで、こちらにお願いをしています。モニタリングを実施させていただいて、あるいは経営実績等々についてのチェックは、今後ともやっていく考えです。","id":"exchange-066"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"その事業所の実態がどうなっているのか見させていただいたりもするのですが、区としても把握し切るというのはなかなか難しいところだと思います。そういう面で、福祉の施設をまた同時に進めていくということなのか、株式会社もどんどん入ってきてもらいたいという姿勢なのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"どういったケアをしていただいて、どういった福祉の向上を図っていただけるか、これを最大のポイントにしています。","id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"賃金実態だったり、全ての株式会社の状況を品川区は把握されて、特段低いようなところがあれば、指導なり、通告なりが何かできる状況にあるのか。そういう把握ができる仕組みがあるのかどうか、伺いたいです。","respondent":"大串福祉計画課長","answer":"指定管理という形をとりますので、先ほども申し上げましたが、毎年、モニタリングという形で、その経営状況、運営状況を見しています。離職率の関係が出てまいりますし、経営についてはこちらのほうから改善を促していく、これは当然のことだと考えています。","id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"あの形を株式会社にもやられているということですよね。それをこの場にも出していくということが必要だと思うのですけれどもとの意見を述べました。","respondent":"大串福祉計画課長","answer":"モニタリングの結果については、ご報告をしています。","id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"区の施設なのであれば、そして福祉を増進させるのが自治体の本旨なのですから、そこはやはり区が責任を持って進めていくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-07","title":"第４３号議案 指定管理者の指定","agenda":"第４３号議案 指定管理者の指定","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、突然出てきたと。中身は変わらないのか、そしてスタッフは変わらないのか、伺いたいと思います。","respondent":"川島健康課長","answer":"実は、約１年前に契約更新をさせていただいたときには、予測できない事業の移管だったということです。議会のほうにお諮りして、再度、指定の手続をとっているところです。","id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"名前が変わっただけというところでも、構成員が変更されているわけですから、代表取締役社長なども変わってきているわけですよね。では、何も変わりないということで、もう１回確認させてほしいと求めました。","respondent":"川島健康課長","answer":"事業の構成員に変わりがないです。","id":"exchange-072"}]},{"id":"topic-08","title":"平成２７年請願第５号 介護保険料の値上げ中止と特養ホーム増設等を求める請願","agenda":"平成２７年請願第５号 介護保険料の値上げ中止と特養ホーム増設等を求める請願","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認させていただきたいのですけれども、まず請願の大きな項目であります介護保険料の値上げ中止と特養ホームの増設等を求める、この財源には。そういう認識でよろしいのでしょうかという確認を、まずお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"保険料の算定にはさまざまな要素が入ってきますけれども、特別養護老人ホームを建設することによって、当然、それにかかるサービスの経費については、介護保険財政のほうの財源を使いますので、影響は出てくると考えております。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、特別養護老人ホームの増設を求める請願と同時に、できないわけではないですか。これは特別養護老人ホームの増設を求める請願で、何か道があるのかという確認を、まずお願いします。","respondent":"永尾高齢者福祉課長","answer":"先ほど申し上げましたとおり、一般財源からは入れてはいけないとなっておりますので、そうすると、あと残されたところは介護給付費等準備基金という、そこの基金しかないと認識しています。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり、財布が限られているわけではないですか、このことについては。こういう施設をつくっていきたいと要望させていただいてはいるのだけれども、おいそれと、まず指摘させていただきたいということ。","respondent":"永尾高齢者福祉課長","answer":"やはりサービスを受けるためには、当然財源が必要になってきています。そのときに、やはり一定程度の備えは必要であると考えておりまして、今どういうふうに進むべきかということを考えるのが大事だと考えております。","id":"exchange-075"},{"speaker":"伊藤委員","kind":"意見","question":"品川区はもっとそういうＰＲをしてほしいのですよ、これだけのことをやって、これだけの費用が必要なのだと。必要最小限の引き上げをするのだということをやはり説明していかないと、こういう請願が出てくると思うのですが、改めて答弁をお願いいたしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"やはり負担が増えるというのは、どんな方でも大変なことだと考えています。区といたしましても、今までもやっておりますけれども、もう少しさらにわかりやすい説明を行うように心がけてまいります。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問","question":"いきなり月５,３００円と言われると、それは検討された結果であって、その前提にはこれだけの介護サービスが必要ですと。品川区民の方々の今から１０年後、２０年後を見据えたうえで、最後に答弁をお願いします。","respondent":"永尾高齢者福祉課長","answer":"やはり結果だけを最初に説明しまうと、なかなか納得いかないことだと思います。これからのこと、将来のことや、今現状置かれている状況、そういうところもきちんと丁寧に説明をしていきたいと考えています。","id":"exchange-077"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私は、介護保険の骨子案のところでの段階別の人数を教えていただけないでしょうか。ですので、そこの立場で見解を伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第１３段階が約９００人、第１４段階が約８００人ということで、合計８万１,５００人ということで推計をしています。非常に問題になっている国保会計のようなことにもなりかねないので、やはりそういうところは慎重に考えていかないといけないと思っているところです。","id":"exchange-078"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そのうえで要支援１、２の方がサービスを取り上げられる、私は本当に深刻になると思っているのです。そして、あなたはチェックリストですよ、あなたは認定ですよというふうに割り振っていく基準は何なのか、お聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"その結果、残額が６億２,６００万円程度になるというところで、やはり今後のことを考えると、これ以上投入するのは危険だと考えているところです。ですので、少しやり方が違うので、今どのくらい件数があるかというところは把握はできません。","id":"exchange-079"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"要支援者の支援のサービスというのをどう考えているのかと、本当に疑問に思うのです。こういった方々からサービスを奪うという、この区が考えるサービスというのはどういった考えなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"基本的に、専門家の方が行うサービスとしては、身体介護は専門家のサービスというふうに想定しております。その中で、全て取り上げるとか、そういう考えは全くありません。","id":"exchange-080"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういった形で、品川区も要支援のサービスをしていくということなのでしょうか。ここがケアマネジャーの腕の見せ所なのだというような、そういった実態も出されているのですけれども、こういった状況をどうお考えか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"もしそういうケアマネジャーがいたとすれば、やはりそれは少し認識が違いますので、区のほうでしっかり指導していかなければいけないと考えています。そこを活用してやろうと考えておりますので、全く素人の方が生活支援をやるという想定はしておりません。","id":"exchange-081"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"少しそこら辺を、どういったところを受け皿として考えているのか伺わせていただきたい。それから、やはりそこの人材の確保が、今現在どういうふうになっているのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"国が言っている訪問型サービスＡというのは、これについては、現在やっている生活機能向上支援事業を充てる予定になっております。","id":"exchange-082"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この間、品川区は整備率が１％未満ですので、これが１.５倍の補助になって、７億５,０００万円入ってくると思うのです。２０億円程度の特別養護老人ホームだったら、１２億５,０００万円で、わかるか尋ねました。","respondent":"大串福祉計画課長","answer":"先般の本会議でもお答えしましたように、あくまでも保育園については暫定地活用といったところで整備を検討されていると伺っております。資料を持ち合わせてございませんので、今、幾ら財調算定されているのかというのはお答えできかねます。","id":"exchange-083"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"広町の区有地を、開発ではなく特別養護老人ホームに、福祉施設にと求めますけれども、ここはいかがでしょうか。介護報酬の減額は中止して、やはり増やす方向で国に求めてほしいというのが、この請願でもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"改めて、広町の暫定地域を、開発ではなくて特別養護老人ホームにと求めます。それから、介護報酬減額ではなくて中止こそ国に、増やすよう求めてほしいと求めましたけれども、改めていかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"介護公明ビジョンというのを平成２２年につくられていまして、それから２０２５年までに特別養護老人ホームを倍増させるというふうに出ていたのです。こういった状況を見て、我慢してくださいと言うのかと思うのですけれども、委員の皆さんの意見を聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"たけうち委員","kind":"質問","question":"我々もこの間の代表質問でもそうですけれども、例えば小規模特別養護老人ホームを増やしていくべきだとか、ここにいる委員みんな同じなのですよ。そういうことは、何で共産党は言わないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"２０２５年までに倍増させると書いてあったので、この１０年間でどうやって倍増させるのか、そして増やしていくのかと思ったのです。ですので、幾らでも財源はあるということを、私は言いたいと思いますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"ですので、より丁寧な対応というふうに認識していただきたいと思っています。ほかの区では定期巡回・随時対応型サービスというのがまだできていない区もたくさんありますけれども、品川区は、だいぶ軌道に乗ってきつつあり。","id":"exchange-088"},{"speaker":"向委員","kind":"質問・要望","question":"この４年間も、しっかり基金についての考えとか、高齢者福祉に対してとか、本当にご努力とかも伺ってきました。傍聴の方もいらっしゃっていますので、お伺いできればと思います、お願いします。","respondent":"永尾高齢者福祉課長","answer":"その分をさらに投入いたしまして、結果的に約６億３千万円ほどの残になりますけれども、対応をしています。ですので、今現在の方の保険料が安くなるということだけではなくて、やはり長期的な視野で考えていく必要があるかと考えています。","id":"exchange-089"},{"speaker":"向委員","kind":"意見","question":"運用についても本当に区のほうでもさまざまに心を砕きながら、気を使って、基金運用も簡単なものではないと思っています。もちろん私たちも将来に向けて不安も多いので、このあたりは引き続きのご努力を重ねてお願いしつつ、以上で終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは誰が何と言ってもお金が必要なわけですから、２０年後、３０年後の品川区も支えなければいけない。この請願については、本日結論を出してほしいと求めましたし、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"たけうち委員","kind":"意見","question":"理由は、先ほども午前中にもあったとおりです。ただ計画だけを先につくればいいということではないと、その２点をまず指摘したうえで、全体として不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"向委員","kind":"意見","question":"午前中の第２７号議案のとおりですが、変更を行うために力を注ごうとしているか、よく理解できております。これについても再三ご説明いただきましたので、以上の観点から、この請願には沿いかねるということで申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"基金の問題も、８億円残ると言っていたものが１７億円になるわけです。その力を発揮するための４カ所目の適地、当然４カ所目が欲しいと選定しているというところの具体化を求めて、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は４年間、厚生委員会にずっと出ていまして、一連の議論は聞いてきました。結論を出す、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":73001,"voices":284}},{"id":"h27-20150223-8","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"建設委員会","time":"午前１０時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"していないね。シャッター音については、格別の留意をしていただきたいと、これはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"の１「議案審査」を行います。 初めに、(1)の第３４号議案、品川区手数料条例の一部を改正する条例","agenda":"の１「議案審査」を行います。 初めに、(1)の第３４号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"建築主事が確認審査を行うということでは、チェックする中身の基準とかがどうなるのか、教えていただきたいのが二つ目です。ここまでお伺いします。","respondent":"鈴木建築課長","answer":"ルート２に変更になるとどうなるのかですが、この資料２の下段、これも審査の適正化あるいは効率化につながっているというような内容です。医療施設の周辺に居住者あるいはほかの生活支援施設が集まるようなところを、それなりの容積率を与えるといった制度です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこのところがよくわからないのでもう一回教えていただきたいのと、品川区の場合、これを定めることが必要なのでしょうか。そこを教えてほしいのと、この特定というのはどういうことを意味するのか教えていただきたいのと、その点を説明するよう求めました。","respondent":"鈴木建築課長","answer":"構造計算のルート２の審査内容につきましては、従前と内容については全く変わらない内容になっております。特定用途誘導地区につきましては、基本的には都市計画に定めるものですので、都市計画審議会等にお諮りして決定していくものだです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"意見","question":"特定というのはどういう意味なのかというのを改めて聞きたいとの意見を述べました。","respondent":"鈴木建築課長","answer":"すみません、説明が漏れておりました。特定用途としましては、生活に必要な施設というところで、医療ですとか福祉あるいは商業といったところが定められているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"続けてお伺いをします。違いがどこにあるのか、審査の内容に違いがあるのかどうかと、あとやはり区がどう関与していくのかという中身を説明するよう求めました。","respondent":"鈴木建築課長","answer":"今回促進法の一部技術的上限が改正されまして、そちらのほうの性能評価書の添付でもこの認定を受けられることとなったというような内容で、内容的には同じような内容です。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区の関与がどう変わっているのかを一つ教えていただきたい。５分の４ということで、残りの５分の１の意思が反対であっても、この点はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"５番目の高度管理医療機器販売業・貸与業の許可等にかかわる、そこのところなのですけれども、許可の内容に変化があるのかどうか。その１点と、あと手数料に変化があるのか、区民にとってどこか変わるところがあるのかどうかを説明するよう求めました。","respondent":"高山生活衛生課長","answer":"先般区への移譲に当たりまして検討した結果、改めて積算をし直したのですが、同じ金額において当初はスタートするというふうに考えているところです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"その事情を教えていただきたいのが一つ。この手数料条例が、手数料条例が区に移譲されることによって、大体区は手数料の増収をどれぐらい見込まれているのか説明を求めました。","respondent":"鈴木建築課長","answer":"それから、改正に伴う収入の増の見込みですが、細かい数字は出しておりませんけれども、特定用途誘導につきましては、今のところ見込んでいないです。来年度２件あるいは１件程度見込んでいると、制度スタートですので、その程度今のところ見込んです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"確認","question":"改正前だと形上は１回確認申請と合わせて構造計算適合性判定を出せば、改正後だと、これが判定結果の通知がなければ確認申請を出せないような。現場はちょっと私もわからないものですから、これによってどう合理化が図られるのか、スピード化が図られるのか説明を求めました。","respondent":"鈴木建築課長","answer":"区のほうで今１８機関ございまして、民間機関と年間契約を結んで、バランスよく区のほうで送っていたです。それから次に、基本的には民間に事前に出して、それを確認申請に添付して、確認申請の受け付けというふうな流れになってあります。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"では、区が指定するのですかね、１８民間機関の中から建築主が選べるということですね。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど一つ、長期優良住宅の認定事務のところで、適合証と評価書に違いがないということだったのですが、区の関与がどうなのか再度お聞きしたいのですが、その点を答えるよう求めました。","respondent":"鈴木建築課長","answer":"関与につきましては、認定申請の内容を審査するですので、従前と変わらないです。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"そこをうまく円滑に運んでいただきたいので、これに関しての考えだけ、新規のことに対応するところに関してのポイントだけを言ってほしいと求めました。","respondent":"鈴木建築課長、矢木住宅担当課長、高山生活衛生課長","answer":"変更等につきまして、特にルート２、窓口等で対応していきたいです。管理組合のご希望も丁寧に聞きつつ、相談も含め、改修等々の相談も今以上に対応を丁寧にさせていただきたいと思います。区の歳入見込みとしては、１７０万円程度新たに入ってくるものと見込んでおりますので、こういった新たなる歳入の確保といった意味合いもあります。","id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"これは質問ではなくて、お願いごとなので。逆に言うとわからない方もかなり多く出てしまうと思うので、その辺のところを皆さんもおっしゃっているように丁寧に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"意見","question":"５番目の高度管理医療機器販売業、特に問題はないと考えていますので、この問題については賛成です。総じて反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-03","title":"の第３５号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"の第３５号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"延長しない理由、あと家主からの意見とか要望が出ているのかどうか、その点を説明するよう求めました。","respondent":"矢木住宅担当課長","answer":"次に、延長しない理由ですが、こちらは２０年の借り上げ期間をもって満了する契約になっているということに基づくものです。現時点で少しずつ返還後の対応についてですとか、私ども各オーナーおよびオーナー会を通じまして、丁寧な対応を心がけているところです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結構空室があるのですけれども、せっかくの区民住宅なので、やはりより本当に活用していただきたいなと思っているのですが、募集についての相談とかがあるということなのですけれども、この辺というのは何が足りなくてというか、何が問題となって空き室が多いと考えているのか説明を求めました。","respondent":"矢木住宅担当課長","answer":"空き室が多い理由ですが、一つには家賃が、以前はスライド制ということで、安くもあったのですが、２０年近く経過しまして、施設の老朽化に比しまして、家賃がちょっと相対的に言って高いというご評価なのかなというふうに考えております。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"低廉な住宅を求めているというところにおいては、代替の対策とかが今後必要ではないかなという思いがありますので、意見として述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、たしか以前のやりとりで空き室率が５０％を超えた場合に家賃を下げるというようなことも考慮に入れていくという話もあった。そのほかの特に借上型区民住宅において、現在そのような対象になるようなところがあるのかどうか、これについて教えてほしいと求めました。","respondent":"矢木住宅担当課長","answer":"現時点におきまして、次年度返還するものを除いては空き室率が５０％を超えたものはございません。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"賃料のことはさまざまなご意見を区民の方からもいただいておりますので、５０％というところにこだわることなく、賃料の検討はしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-04","title":"の第３６号議案、品川区建築審査会条例の一部を改正する条例","agenda":"の第３６号議案、品川区建築審査会条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"同意の基準は一体どういうものなのか教えていただきたいのと、特定行政庁というのは区と理解していいと思うのですが、そこの許可の基準というのはどういうものなのか説明を求めました。","respondent":"中村都市計画課長","answer":"周囲に１ｍから２ｍの空地があり、またこの敷地に通ずる通路以外に避難経路が複数用意されていることというのが一つあります。そして、そこで特定行政庁も意見を述べて同時に審議をされるものですので、同意をもっておおむね許可をするというような流れになってあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同意をもって許可をするということは、ほとんど建築審査会の中で決まってしまうという理解でいいのでしょうか。議事録はどうなのか、非公開なのか教えていただきたいのですが、この流れから見ると議決は行われるのか尋ねました。","respondent":"中村都市計画課長","answer":"１.５ｍしか接道がないといったものについては例えば避難経路をさらに二つ、例えば三つとか、審査会で同意をされるというケースもあります。それから、審議会の決定につきましては、審査会の委員の過半の採決をもって可決するというようなことになってあります。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対します。より企業が仕事をしやすい品川区になっていくという中身の流れになりますので、悪法のもとの一定の流れの中での規制緩和なので反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"第４４号議案のほうからお伺いします。第４４号議案のほうで、かなりいろいろな問題をはらんでいると思うのですが、つかめるのかなというところをちょっと説明を求めました。","respondent":"矢木住宅担当課長","answer":"世帯の収入ですが、こちらは月２３万円ほどになっております。その収入申告で、例えばこれがパーセンテージ的に２０％を超えるので使用料が高いから出ませんかとか、生活状況をお聞きする中で判明したものです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"第４４号議案と第４５号議案、滞納の基準がちょっとよくわからないのですが、滞納状況というのはどのくらいあるのでしょうか。こういった大きな額になってしまうので、こういう事態にならない防止策というか、その辺のお考えを説明するよう求めました。","respondent":"矢木住宅担当課長","answer":"なかなか難しいところがあるのですが、少なくとも滞納３か月以上という方につきましては、全てをなべて２０人程度というふうに把握しています。わずかながらではありますが、早期着手ということで、効果が出ているものと認識しております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと基本的なことを教えていただきたいのですが、決まりがどういうところにあるのか、基本的なところを教えていただけたらと思います。","respondent":"矢木住宅担当課長","answer":"大体１か月から２か月程度の準備期間を設けておりまして、その前に専決をするということの中で、その期間がたまたま議会の開催中でないです。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"(3)のところで、たまたまなのかどうかわかりません、どちらもこの物件であると。今２件出てきましたが、そういったことが今あるのかどうか、お答えができる範囲で教えてほしいと求めました。","respondent":"矢木住宅担当課長","answer":"お忘れではないですかということで納付書をお渡しするということで対応はしております。当面の予定としては、訴訟の提起の予定はございません。","id":"exchange-026"},{"speaker":"大沢委員","kind":"確認","question":"第４５号議案で、ちょっとすみません、確認を、契約された方が外国籍の人だとちょっと伺ったのですが、そこの確認したいと求めました。","respondent":"矢木住宅担当課長","answer":"失礼いたしました。外国籍ではなくて、現在は帰化しておられる方で、平成１７年に帰化された方です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"隣の青物横丁の駅を利用するなど、ぜひ最寄りの駅になるようにしてほしいということで、地域の人が当たり前に使える駅にしてほしい。お寺のこともそうですけれども、どのくらい、どういった中身で京急に働きかけをしているのかという点をまず説明を求めました。","respondent":"中村都市計画課長","answer":"まず区民の皆様からご意見をいただいたときはもとより、また京浜急行につきましては、それ以外にもさまざまな打ち合わせの席がいろいろあります。そういった機会を利用して声かけを行って、お願いしますということを継続して行っております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"区民の声があったとき、打ち合わせの席、結構あるのでしょうか。継続してと言っていますが、この請願にあるようなエレベーターの設置の指導というか、話し合いは実際何回ぐらい行われているのか尋ねました。","respondent":"中村都市計画課長","answer":"昨年の４月以降ですけれども、区民の方からお問い合わせいただきましたのが３件、八回程度は区役所において行われております。そういった機会を利用して、会うたびごとにお願いをしているです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"京急新馬場駅南口にエレベーターの設置を求める会の方々は、申し入れに行ったときに、東京都は法律に沿った補助金を都は出しますよと言っている。５点ですかね、品川区がどう決断をして、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"この理由につきましては、限られた財政状況の中で株式会社としての京浜急行電鉄が判断するにおいては、いたし方ないところもあるかもしれません。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"これは二つ出ていまして、一つのほうは指導してくださいと相当強い意味で書いてあるのですが、この指導というのは行政指導なのでしょうか。私たちは、この指導という意味、働きかけと相当違うように感じるのですけれども、理事者は指導というのをどういうふうに捉えているのか尋ねました。","respondent":"中村都市計画課長","answer":"ただ、それ以外、法に基づかないものについては、指導を強要するというのは非常に細心の注意が必要なところです。法律では適合しているというところから考えますと、この指導というのは、ちょっと慎重を期すべきものというふうに考えております。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは今お話を伺いましたけれども、働きかけていただきたいというのは、私たち自民党としてはなじまないなというのが大勢なのです。このことだけを申し述べておいて、皆さん方の意見もまた聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そして私も含めて計７回ほど一般質問、予算特別委員会、また決算特別委員会においてもこれは求めてきたものであります。自治会長からのご要望ということで、これは確認いたしましたけれども、自治会長から出ているという内容であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかができていないので、ここの強い要求を待ってほしいということにはならないと思うのですよね。行政指導を強力にしてほしいということではなく、そこを実現してほしいという願いであると受けとめていただきたいのですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"鉄道事業者のほうにもさまざまな事情があるかもしれませんけれども、その順番を少しでも早めていただくというところがやはり大切だです。やはり行政指導そのものは確かに難しいかもしれませんけれども、お願いのほうは、強いお願いとして引き続きお願いをしてまいります。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"ですから、指導と我々が民間で使うときの言葉と行政用語の指導、その辺が本当にはっきり言って役所の言葉というのはわかりにくいです。ですから、賛成、趣旨という感覚を私は持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"利便性の向上のためにもぜひ設置に向けて働きかけていただきたいと考えています。この指導ですが、その辺を考えながら、採択に向けていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"松澤委員","kind":"質問・要望","question":"今紹介議員のあくつ委員から伺いましたけれども、あつく委員が署名しているほうは、周りの町会長だという話を伺いました。やはり地域が望んでいるということ、私たちはこちらの請願第１号のほうは、採択というふうにとってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"その中で、紹介議員が紹介するに当たって、しっかりと議会に出す前にチェックをすべきものであるということもやはりあるのではないかと思います。ですから、これは指導ですから、趣旨採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"先ほどから皆さんからお話があるように、指導という部分でやはり私たちの会派でもこの表現で果たしていいのかどうかというところで議論になりました。こちらの「強い指導」というほうでは、この思いも非常に理解できるところでありますので、趣旨でお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"共産党としては、請願第１号も請願第８号も区民の皆さんから一刻も早くバリアフリー化を進めてほしい。今日結論を出していただきたいのですが、請願第１号に対して採択、請願第８号に対しても同じく採択をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願第１号のほうは皆さん一致をしているのですが、請願第８号に対して趣旨と、うちは採決を主張していたのですが、趣旨採択で一致をするならば、趣旨採択で一致させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"平成２７年請願第２号、補助２８・２９号、放射２号線の事業計画の白紙撤回及び家屋の倒壊、火災予防中心の防災推進を求める請願","agenda":"平成２７年請願第２号、補助２８・２９号、放射２号線の事業計画の白紙撤回及び家屋の倒壊、火災予防中心の防災推進を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"不服審査請求も出されている方々からの意見陳述なので、冒頭にご意見を聞いていただいて審査をしたほうがより中身が深まると思うので、その辺の取扱いについてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"これは変えることはできないのですか。委員長のご判断か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"そうですか。意見陳述の後審査をしたほうが、より中身が深まると思うのですが、皆さんにちょっとご意見を聞いていただけますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先立って、品川区議会が東京都知事に提出をしました都市計画道路補助第２９号線の計画廃止を求める意見書をぜひ皆さんに聞いていただきたいので。廃止を求める意見書が全会一致で決議、２９号線の計画廃止を強く要望したわけですけれども、その辺についてお聞かせをいただければと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"２０１１年を機に、とりわけ東京において、そこの大きく顕著に変わった部分があるのであれば教えてほしいと求めました。私は２００２年のときには、その場にはおりませんので、そこのところを教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"すぐ年度が変わりましたので、しっかりと取り組んで、区民の安全安心のまちづくりを進めるということで大きく方針をお示ししたところです。","id":"exchange-046"},{"speaker":"大沢委員","kind":"意見","question":"今言った２００２年当時、２０１１年当時、行政が防災に対する取り組み、あるいは取り組みに付随する事業について、さまざまな議会、行政を含めた部分で意識が変わってきたと私は今課長からの説明を聞いて思ったのですが、そのような捉え方でいいわけですよねとの意見を述べました。","respondent":"鈴木防災課長","answer":"特に平成２４年４月に東京都から首都直下地震の具体的な被害想定が出されました。そのことで、より具体的な対策の方向性が出ましたので、かなり防災対策に関しても充実をさせてきたです。","id":"exchange-047"},{"speaker":"大沢委員","kind":"意見","question":"２００２年当時の全会一致という部分と、これをもって２００２年を根拠にしながらこの話を進めるというのはいささか乱暴な気がします。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"1)と3)住宅の耐震化と初期消火の成功率向上、2)の通電火災を防止するための感震ブレーカーというお話があるのですけれども、また周知に努めていることはあるのか説明を求めました。","respondent":"鈴木防災課長","answer":"通電火災につきましては、この請願の中にもありますように、国の中央防災会議で検討されているところです。個人の財産、直接区のほうでやるものではなくて、現時点で感震ブレーカーの普及のための助成制度というものの予定はございません。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり２００２年の阪神・淡路の震災に教訓を学んで意見書を当時つけられたわけですから、ここに学ぶべきであると思っています。防災のためと書かれている中身、防災に役立たない道路をやめてほしいというこの点に対して、皆さんは防災のために必要だとお考えなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大学の教育にふさわしい環境が求められていると、その教育理念等を踏まえて決定すべきと考えていますと、国会ではこう答弁をされているわけです。文章で説明をしてほしいと、皆さんにもぜひ議論のところに加わってほしいと求めましたが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"放射２号線ですけれども、この放射２号線に関しましては、また延焼遮断帯としても効果が期待できるというふうに認識しております。星薬科大学との交渉につきましては、やはり丁寧な説明とあるいは今後の再建策につきまして、話し合いが進めばいいというふうに考えてあります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点をお伺いしたい。どのくらい説明に行ったり、大学の意向を聞けているのか、そこをぜひ具体的に教えていただきたい。","respondent":"中村都市計画課長","answer":"星薬科大学につきましては、東京都のほうからは特に情報は入ってきておりません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はぜひこの大学の考えを取り入れたら、本当に放射２号線の建設と相いれないと思うのですけれども、この辺、このままでいいのでしょうか。私は都と区でごり押しをするのは絶対やめていただきたいと思うのですが、いかがか尋ねました。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"かなり交渉事の中に入っていくということにつきましては慎重を期していかなければいけないのかなというふうに考えております。星薬科大学としての考え方がありますので… それから、行政は防災に強いまちづくりを進めるための行政としてやらなければいけないこともある。これらを総合的に勘案しながら品川区としては防災に強いまちづくりを東京都と連携していきたいというふうに考えてあります。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"東京都自身が当時の計画の原図や原簿の存在を確認できていないということ、法的な瑕疵があるのではないかと言われている状況です。都がやっていることですからという立場ではいられませんよね。","respondent":"中村都市計画課長","answer":"今現在、当時その書類をもとにこの計画が進められてきたということの状況的な証拠をかんがみると、これは今後国の判断によるものなのかなと思います。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願者はこの道路計画白紙撤回を求めていますが、立場の上で推進をされる立場に立っていらっしゃる方のご意見もぜひお聞きしたいと思っています。ぜひ、ご発言をお願いしたいと思いますが、再度いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"原委員","kind":"質問","question":"私は会派に所属しているわけでも何でもないですから、両方がある意味学校法人を利用しているというところがあり得るのかなという気がしております。それが私の今の意見ですから、国土交通省、どうも全面的に撤回だよということではないというふうに私個人としては解釈しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこういう機会に、議員の皆さんにも、行政の皆さんにもぜひ聞いていただきたい。不服審査請求も出していらっしゃる方々なのでしっかりと受けとめたいと思いますので、ぜひ意見陳述を聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出してほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"白紙撤回と火災予防中心の防災推進、二つを求める請願。感震ブレーカーですけれども、結構テレビとかでやったものですから、かなり区民から私のほうに問い合わせがありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"意見","question":"まちコミュニティを壊す、商店街も壊す、許されないと訴えを重ねています。道路ではなく、こちらに転換をすることを主張されているこの請願を応援し、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"大井町駅上空１,０００フィート、３０５ｍのところで８０デシベル、どのくらい違うのですかね。不安を持つのは当然で、この不安を取り除くために何をしていくのかというあたりを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"現在のところ、今のところ、１,０００フィートのところでは８０デシベルということが想定されております。飛行機の機械に対する性能、機密、そのあたりも徹底していくです。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうしたら地域の方々の不安を取り除けるのかという、やはりそこのところは十分な、ここにも八潮の住民に計画などを説明してくださいと。この辺をどう考えているのか、その不安を取り除いていくために何が必要なのかというあたりをご説明ほしいと求めました。","respondent":"三ツ橋環境課長","answer":"区民の不安を取り除くためにまず何をしなければならないのかですが、まずは国からの説明をしっかりしてもらいたいと、こちらはまず区からの要望も出しておりますけれども、国が区民に対してしっかり丁寧な説明をしていくということが大事だと考えています。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"具体的には国に説明してもらいますというのは何回もお伺いしているのですが、こういう場がどういうところで、あと言ってみれば説明の内容ですよね。内容によって不安が取り除かれるか、除かれないかというところなので、してもらうというところだけか尋ねました。","respondent":"三ツ橋環境課長","answer":"説明に関して、もう少し詳しくお伝えいたします。説明のプロセスやタイミングについては、地域への説明についてはより多くの方々のご理解を得て、取りまとめていくことが肝要と考えているです。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とにかく説明のところはきちんと十分に本当にしていただきたいのと、しっかり言っていかなくてはいけない。落下物と墜落の危険性、この回避をする部分に対しては、区はどのような見解をお持ちなのか尋ねました。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"こちらの落下物等につきましては、まず落下を起こさない、また安全安心ということをまず大前提としておりまして、そちらが大事だと考えています。そのため… そのように考えておりますけれども、少しでも被害が少ないような形でのこと、これを考えていることだというふうに思っております。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"命を守っていくという立場で、やはり何らかの歯どめというのですかね、守っていく手だてが必要だと思うのですよ。国が、東京都がといって済む問題ではないので、ぜひそういった手だてもやっていかなければいけないと思うのですが、この点はいかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"国に対して言っていくという部分、市街地上空を飛んではいけないという法律はございませんけれども、そちらの件に関しては、今後研究させていただきたいと考えています。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"今まで質問されましたけれども、議会のほうでも１２月２５日付で意見書を出しております。要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区から８月に国に対する要望を東京都を経由し提出とあるのですけれども、目標年次、２０２０年を見直しする予定はあるのかという問いかけに関しての何か返答というのはあったのか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちらの２０２０年の目標年次見直しということについては、３ページですけれども、今のところオリンピック・パラリンピックが目標というふうになっているです。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"質問・要望","question":"基本的には不安があることは間違いないので、国のほうにしっかりとした安全を求めていくというスタンスで私も理解しておりますし。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"区民の方々にできるだけご理解していただけるような説明を求めて、取り組んでほしいと求めました。品川区全体の問題ですので、多くの方にちゃんと説明していただいて、不安が取り除けるように国に求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"提案","question":"結論を出すということで、採択をしてほしいと思いますが、一言。地元の納得するような案を要望していくと、この間、やはり今回の要望事項というのはとても重要であると思っていますので採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"}]},{"id":"topic-06","title":"の３「報告事項」を聴取いたします。 初めに(1)専決処分の報告について（報告第１号）","agenda":"の３「報告事項」を聴取いたします。 初めに(1)専決処分の報告について（報告第１号）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"損害賠償額が３万７,０００円で、電卓というのはこんなに高いのかなという疑問が出た人がいたので、何と何を購入されたのか、内訳を教えてください。ただ、それだけです。","respondent":"小林品川区清掃事務所長","answer":"この３万７,０００円の内容ですけれども、２点、入っていましたかばんと中の電卓です。これは相手方も知らなかったとはいえ、買ったばかりのかばんだけは何とかしてくれということで、かばんと電卓を弁償したです。","id":"exchange-072"}]},{"id":"topic-07","title":"の戸越公園駅周辺まちづくりビジョンの策定","agenda":"の戸越公園駅周辺まちづくりビジョンの策定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"３商店街、どういった意見が反映をされたのか、ちょっと初めのところを説明するよう求めました。","respondent":"中村都市計画課長","answer":"素案の説明会ですけれども、大体２５名から３０名ぐらい町会の皆様が出席をして、また後日いろいろ意見が届いたりということがございました。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どのくらいお金がかかっていて、どこから支出をされているのか、大もとのところを教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"品川区とあと地元の皆様で意見交換を行いながら進めてきたものですけれども、区としましては、委託業者に委託をして進めてまいりました。これは説明会ですとか、あるいは資料の説明会に要する作成費ですとか事務経費などが含まれてあります。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託、どういうところに委託をされているのか、また委託先が今後どうかかわっていくのか、その辺を教えていただきたいのが一つです。どうこれからも保っていくのか、またどういうふうにしていきたいというか、していくのかというところをまず商店街のところを説明するよう求めました。","respondent":"中村都市計画課長","answer":"個別建て替えなどの建て替えの支援などを行って、お店の配置ですとか、地元の方々と連携して話し合いをしていくことが必要だと考えております。それからあとは、こういったところもこれからまちづくりで重要なところというふうに考えてあります。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"既にこの間町会とか商店街との話し合いをしているわけなので、ご意見がいっぱい出ているのかどうか、その点を一つ教えていただきたい。そこをどう考えているのかというところ、あと６か所の踏切をどうするのですかというのが率直な地元の疑問なので、答えるよう求めました。","respondent":"中村都市計画課長","answer":"区としても避難経路の確保あるいは交通の円滑化という点からすれば、やはり解消することが望ましいという認識でおります。このまちづくりビジョンを定め、引き続き東京都に要望してまいりたいというふうに考えてあります。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に地元の要望であると思いますけれども、都に要望を引き続き課題としていきます程度しか今日は答えられない、まだそんなところなのですか。私たちは道路は反対していますけれども、高架化のところのめどがどの程度なのか、どういう説明をされているのか教えていただきたいのが一つです。","respondent":"藤田都市環境事業部長、中村都市計画課長","answer":"なかなか踏切対策基本方針に位置づけられているものがありますので、その辺について具体的にいろいろ調整をしているところです。区のほうとしては、少しでも早くそれが実現できればということで考えているところです。そして、今後のかかわりですけれども、昨年度、まちづくりビジョンを策定するに当たりまして、主な業務として進めて委託をしてまいりました。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問","question":"地域の利便性を高めてほしいと思いますが、補助２９号線とセットで進めるというのは、私は何かちょっとひきょうなやり方だなと思います。いつごろ明らかに、何か既にいろいろ出回っているイメージがあるので、いつぐらいに明らかになっていくのかというあたりも説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]},{"id":"topic-08","title":"の大井町駅周辺地区バリアフリー計画の策定","agenda":"の大井町駅周辺地区バリアフリー計画の策定","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと個別案件なので、ちょっとはてなと思うところがあるので伺いたいのですが、これは私もご要望をいただいたことがあるのですが。これも随分私たちも要望してきたことなのですけれども、すごく遠回りをしないと入れないということがあるものですから、わかる範囲で説明を求めました。","respondent":"中村都市計画課長","answer":"この実施予定時期につきましては、これもシルバーセンターの所管のほうで継続して取り組んでいきたいというところもあって、時期については。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"両方とも進めていただけるというご答弁でありました。ちょっと、またこれは予算特別委員会で詳細についてはお聞きしますが、全体としてはすばらしい内容だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-09","title":"の特定整備路線沿道における都市計画変更素案に関する説明会について（補助２９号線 大崎地区）","agenda":"の特定整備路線沿道における都市計画変更素案に関する説明会について（補助２９号線 大崎地区）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"新たなにぎわいの創出というのはどういうことなのか教えてください。３０ｍ、沿道の住民の方々にとって、この計画変更のメリットとデメリット、両方あわせて説明を求めました。","respondent":"中村都市計画課長","answer":"居住継続支援や新たなにぎわいということで、居住継続支援ですけれども、居住の継続の支援を考えてあります。特に変更がございませんので、この辺も商店街においてはにぎわいの創出のためにプラスになるのではないかというふうに考えてあります。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の方は補助２９号線建設反対、中止を求めているわけですけれども、この沿道の部分はどうなるのかという疑問が一つ出ています。補助２９号線、この部分の進捗状況がわかったら説明を求めました。","respondent":"中村都市計画課長","answer":"商業系は変更がないということで、３００％と申しますと、高層ビルが建つというような容積率の設定ではないです。道路整備が推進され、完了されるということを前提に容積率を定めるものですので、中止についての概念は今回の変更につきましてはございません。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"最後にしますけれども、これはこれから説明を受けるわけですけれども、いつから実施をされるのか、時期を説明するよう求めました。","respondent":"中村都市計画課長","answer":"説明会を行います。区と東京都の都市計画審議会というものを開く予定でおりますので、予定としては今年度の変更は、手続の進捗状況によりますので難しいかなですが。","id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":82374,"voices":281}},{"id":"h27-20150223-9","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"文教委員会","time":"午前１０時００分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"の第２１号議案、品川区青少年問題協議会条例の一部を改正する条例","agenda":"の第２１号議案、品川区青少年問題協議会条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"教育委員会との関係ではどういうふうになるのかなと思うし、どういうふうに違いが出てくるのか、全く同じなのか。違いが出てくる、教育委員たちの意見がちょっと入っていかないような気がするのですけれども、その辺はどうなのか尋ねました。","respondent":"福島青少年育成課長","answer":"今までと変わらずに、当然ながら教育委員会は、これを主宰するのは教育長ですので、教育委員の意見も教育委員会の意見も、当然ながら反映されたものとなりますので、今までどおりと変わらないものと考えています。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"委員たちの構成による５人の教育委員会、やはり教育委員としての意見が届いていかない状況になるのではないかと、非常にその辺を危惧するのですね。","respondent":"福島青少年育成課長","answer":"こちらの青少年問題協議会条例につきましては、今までと同様と考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"検討もしたし質問もして、その辺をしっかり確認したいと思っているわけですけれども、今までの仕組みとは全然変わるわけですよ。その辺について、どういう検討でそうなったのかということを改めて伺いたいと思います。","respondent":"福島青少年育成課長","answer":"ただし教育長の位置付けがどうなるか、その辺につきましては、私どもの問題ではないと考えているところです。教育長という形に、教育委員会を主宰する方に出ていただくという位置付けですので、私どもとしては変わらないと考えています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"では、教育委員会のほうに質問というか伺いたいと思うのですけれども、地方教育行政の組織及び運営に関する法律が変わったことで、教育長の位置付けというか、そこのあたりは全く同じなのか、それともどういう変化が、あったとしたならばどういうことなのかをちょっと伺いたいと思います。","respondent":"品川庶務課長","answer":"教育長の位置付けというのは、今まで教育委員長と教育長というのが教育委員会の中に置かれていました。これが、新たに教育委員長と今の旧教育長を一緒にした形で、新教育長という形で変えていますので、ここが大きな変更点かと思います。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"やはり私は教育委員会、教育委員を代表するという立場で、青少年問題協議会構成も図るべきだと思うわけです。そういう点で、やはり教育委員会のこの教育委員という位置付けでなぜしようとしないのかというところを、ちょっともう一度伺いたいと思います。","respondent":"田村教育次長","answer":"法律の考え方に沿って説明しているので、南委員の思いはわかるのですけれども、法律を理解してもらいたいのですね。その説明を先ほど来やっているので、そういう形で改正をしますという趣旨なので、ぜひご理解いただきたいと思います。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"法律改正されたからとして、今まで教育委員会委員という形が教育長になるというのは非常に危惧すると思うので、私はそういうことで質問をしました。〔「代表なんだからさ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それが委員会なんですから、委員長、そういうふうにちょっと仕切ってほしいと求めました。」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"何を言ってるんですか。早く終わって」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、自分の意に沿わないような発言があったときも、別にそのことに対して発言をしにくくするような行動は、私はずっとしていません。ぜひ受けとめていただきたいと、発言された方は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"私は先ほど質問したような趣旨で、賛成はできません。心配な点があるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"子どもですから、そういう中で品川区に連絡をするだとか、そういう関係というのは具体的にどんな動きになると考えればいいのでしょうか。先ほどは年間大体１件程度だというお話だったので、何かいろいろな齟齬というかいろいろな状況が出てきて、そのあたりのことも伺えればと思います。","respondent":"福島青少年育成課長","answer":"広く周知してというよりは、実際に起こったときには、こちらのほうから改めてこういう手続が必要ですよという形で案内していきたいと考えています。全２３区と市町村に対して、今、こういう改正を行っているです。","id":"exchange-011"},{"speaker":"南委員","kind":"確認","question":"最終的に確認したいと思っているのですけれども、では、事故に遭って通院を始めたと。そのときに、区のほうで対応することになりますよというふうに、被害者の保護者にはそういう旨をお知らせをするということでいいわけですね。","respondent":"福島青少年育成課長","answer":"まさにそのとおりです。","id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"今回の措置というのは、期限というのは設けているのでしょうか。当面はこのままでいくと聞いたような覚えがあるのですけれども、その関係で、この措置は期限があるのかどうかというのを確認しておきたいと思います。","respondent":"竹田保育課長","answer":"子ども・子育て支援法に基づきまして、平成２８年度以降については、また別途検討するということを考えております。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"第３子以降の子どもについての減免だとか、また８時間保育が８割だとか、これはこのままでいくと。保育料の額が変わっていくということで理解していいのか尋ねました。","respondent":"竹田保育課長","answer":"平成２７年度につきましては、今までどおり所得税による算定をしておりますので、基本的に収入等が変わらなければ同等の保育料だと考えております。今回、子ども・子育て支援法の実施に伴いまして、その部分について今回ご提案させていただいているものです。","id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"８時間保育、保育短時間認定の子どもの保育料の関係で、では延長保育料金というのは、具体的に保育時間がどういうふうに延長したら、どこからどこまで延長したら延長保育料金を徴収する対象になるのかどうか、そのあたりを保育時間との関係で確認しておきたいと思いますので、お願いします。","respondent":"竹田保育課長","answer":"今回新たに設定されました保育短時間につきましては、この時間内の８時間について、ご利用、お預かりするという制度です。したがいまして、この開所時間内でありましても、８時間を越えた部分については時間外保育料として徴収するものです。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"そうすると、その保育短時間認定の８時間の方は、８割の保育料プラス延長料金というふうになるわけですよね。７時半から６時半の間であれば、８時間保育を若干オーバーしても、その辺の情報というのはどうなのしょうかとの意見を述べました。","respondent":"竹田保育課長","answer":"より柔軟にその８時間をご利用いただけるように、開設時間の範囲内であればご自由に８時間をご利用いただけるというふうに一歩進んだ制度としておりますので、延長料金として徴収する考えです。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"勤務ですから交通機関を利用する方もあるだろうし、徒歩の方も自転車の方もいろいろあると思います。その辺というのは延長料金徴収との関係で、どのくらい厳密にするのかしないのかというあたりをちょっと確認しておきたいと考えています。","respondent":"竹田保育課長","answer":"原則は８時間というご契約ですので、８時間をはみ出した部分は徴収しますが、もろもろの天災等ご事情がありますので、その場合はケース・バイ・ケースで対応していきたいと考えております。","id":"exchange-017"}]},{"id":"topic-02","title":"の第２６号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例","agenda":"の第２６号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"先ほど質問させていただいたときにも、当面平成２７年度中は所得税をベースにということなのですが、その辺の確認です。改めてこの条例の制定そのものについてはちょっと違う質問をしてしまって申し訳ないのですけれども、この際、確認をしておきたいと思います。","respondent":"竹田保育課長","answer":"周知期間もないことから、平成２７年度は現行どおりとして、その後については今後検討するということとしております。今後の基本的な考え方ですが、適正な保育料を定めていくという考え方です。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"一人一人の保育料がやはり大幅に変わらない配慮というのはするべきだと考えていますので、ちょっと最終的に確認をしておきたいと思います。考え方としてきちんと持ってほしいと求めましたので、その辺の考え方についてもう一回最終的に確認をして終わりたいと思います。","respondent":"竹田保育課長","answer":"今回ご提案させていただいたのは、平成２７年度の保育料についてです。それ以後の平成２８年度以降につきましては、今後社会情勢等いろいろ勘案しまして、適正な保育料をご提案させていただきたいと考えております。","id":"exchange-019"}]},{"id":"topic-03","title":"の第３７号議案、品川区教育に関する事務の職務権限の特例に関する条例の一部を改正する条例","agenda":"の第３７号議案、品川区教育に関する事務の職務権限の特例に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"これが教育委員会部局、教育委員会サイドでの条例になっているということがちょっとよくわからないのですけれども、その辺を説明するよう求めました。","respondent":"品川庶務課長","answer":"こちらは教育委員会の中の職務として位置付けるものとしまして、文化、それからスポーツに関することを位置付けているという意味です。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"それ以前はどういうふうになっていたのですか。この文化、スポーツに関することの扱いというのはどういうふうになっていたのか尋ねました。","respondent":"田村教育次長","answer":"１つわかりやすいのが、あと教育委員の保護者枠だとか、要するに教育委員の権限を拡充する改正が行われました。文化財の保護というのは法律上も例外規定はないですから、教育委員会に残さざるを得ないという形の趣旨なので、ご理解いただきたいと思います。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"平成１９年度の地方教育行政の組織及び運営に関する法律改正の中で、こういう位置付けになったということですね。それと、ここで地方教育行政の組織及び運営に関する法律との関係があるので、どういう動きになっているのかなというのを伺いたいと思います。","respondent":"品川庶務課長","answer":"教育大綱につきましては、来年度、総合教育会議というのを始めていく予定です。来年度、総合教育会議の中でどのようにやっていくかというところを議論していくという形になるかと思います。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"そうすると行政部局のほうの話になってしまうかもしれないのだけれども、法の施行は４月１日からですよね。そこの時点で、そういう質問をしたかったのですけれども、それはどうなのか尋ねました。","respondent":"品川庶務課長","answer":"法の施行は４月１日以降ですので、総合教育会議も当然４月１日以降という形になります。その中で教育大綱を決めていくという形になりますので、当然４月１日以降やっていくということになるかと思います。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"そういうことで、４月以降の準備というか検討が始まるというということなのだと思うのですけれども、かといってそんなに長期間つくりますよという状況を長期間続けていっていいとはならないのかなと思うので、大体どのようなめどなのかなというのを含めてとの意見を述べました。","respondent":"田村教育次長","answer":"この辺はまさに南委員がおっしゃっていたように、区長部局の権限なのです。ちょっとこの場でこうだと思います、ああだと思いますという話には、申し訳ないですがならないかなと思います。","id":"exchange-024"}]},{"id":"topic-04","title":"の品川区立幼稚園条例の一部を改正する条例","agenda":"の品川区立幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"確認だけですけれども、私立と区立とどういうふうに仕分けされているのかどうか、その辺を確認をしたいと思います。","respondent":"竹田保育課長","answer":"区立については、先ほどご説明したとおりの保育料を定めております。第３子と数えまして、第２子は半額、第３子については免除と今回するものです。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"戸籍上の第２子、第３子というのと違いがあるのか、最終的に確認したいと思います。","respondent":"竹田保育課長","answer":"第２子、第３子の数え方ですが、基本的には確認のできる書類をもって第２子、第３子と数えていきたいと考えております。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"そのときの第２子とか第３子とかいう捉え方をちょっと質問したのですけれども、さらに４年生以上の兄弟がいるケースだってあるわけですよね。あるいは戸籍上の第２子、第３子という捉え方なのか、そのあたりを確認したかったのですけれども。","respondent":"竹田保育課長","answer":"今回の制度の数え方につきましては小学校３年生までを対象にとしておりますので、仮に小学校１年生から３年生までに第１子がいた場合は第１子、幼稚園部門に２番目のお子さん、３番目のお子さんがいらっしゃった場合は第２子、第３子という数え方です。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"１番目の地域手当の割合の変更なのですけれども、一時金のほうのプラス２％ですから、そのあたりを伺いたい。当然、品川ベースというか、そのあたりのいわゆる労使との関係ではどういうふうになっているのかをちょっと伺っておきたいと思います。","respondent":"渋谷指導課長","answer":"基本的に全体の給料のこの変更については、幼稚園教員だけ特別に変更をということはできないと、準ずるしかないのかなと考えています。それから、実際の改定の部分で給与月額がどうなるのかというのですが、１.７％程度引き下げになるです。","id":"exchange-028"},{"speaker":"南委員","kind":"意見","question":"労使との関係でそういうふうになっていればこちらがどうこう言う筋合いの根拠もなくなってしまうので、やむなく了解するとしていきたいと思います。反対はしませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"本会議でも同種の質問をしたときに、不承諾通知をもらった人は１,２５６人という数字が示されたのですけれども、それは同じ数字ということで確認していいのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"本会議で答弁申し上げましたのは発送予定数ということで、一次選考で内定が出なかった数、１,２５６人という数字を紹介させていただきました。そこから数としては６８人を引きまして、１,２５６から６８ですので、１,１８８人の方に利用不可通知を発送したところです。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"１,１８８人ということにしましても、二次募集で受け入れる枠というのは何人ぐらいになると予定されているのでしょうか。１７人の枠しかないのかなとちょっと思って、大変な事態だなと私は思っているのですけれども、どういう状況なのかを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"小規模保育では０歳から２歳児の受け入れですので、そちらが１１人という形になりまして、合計１４８人の入園枠を予定しております。は地域型保育事業等の内定辞退のお届けを受けておりますので、この内定辞退または転園等が出てくると、受け入れ可能数が加算されていくです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"ここのところで見たときにも、では、ここの１,１８８人の年齢の内訳というのはどうなっているのかというのを伺っておきたいと思います。１,１８８人の中の８割だろうと想定される０歳から２歳の子どもがどれだけ入園できるのかというのをはっきり確認をしたいと思いますので。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、１,１８８人の年齢別の内訳は持っておりません。この１,１８８人の中に含まれておりますので、平成２７年の４月以降、ここからまた数のほうを精査していく形になっております。","id":"exchange-032"},{"speaker":"南委員","kind":"確認","question":"一番最初に確認しておきたかったのですけれども１,２５６人のうちに書類未提出の方もいるという、そこを確認したいと思います。私は１,２５６人で考えていきたいと思っているのですけれども、担当課長としては大枠でもご承知だと思いますので、そのあたりを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"いわゆる利用不可通知の中の０歳から２歳の枠につきましては、例年どおりこちらのほうがほとんど多い数を占めていくということで認識しております。３点目ですけれども、委員のご質問は内定者数のうちの中で、認可保育園と地域型のみの内訳ということでよろしいでしょうか。","id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"一次を取り下げた方も含めて６８人だという話なのですが、その中で、その扱いをちょっと最終的に確認をしたいと思います。そこが大事なところだとだと思うし、改めてその対策についてどういうふうに考えていこうとしているのか、そこを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後引き続き認可保育園、認証保育所、小規模保育等という総合的な待機児童対策はとっていこうと考えております。委員にご説明したとおり、内定の辞退等の可能性があるので、ご希望の申請の変更などもあわせてお伺いしています。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"４月１日に入園したい、その子どもたちへの対応はどうしようと考えているのか、そこが私は一番聞きたかったのです。そこについて、説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"さまざまな情報提供を通して４月の入園、また４月の保育サービスの利用が可能になるように、情報提供に努めているところです。","id":"exchange-035"},{"speaker":"南委員","kind":"確認","question":"１,１８８人、あるいは１,２５６人、あるいはその８割という数が解消できると考えているということですか。そこをまず確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私としましては、今回待機児童という形で、昨年最終の確定値が１２８人という形でございました。不承諾数のほうが増えている中ではありますので、開設は進めておりますけれども、待機児童数は残念ながら増加すると見込んでおります。","id":"exchange-036"},{"speaker":"南委員","kind":"提案","question":"この１,２５６人に対する責任を品川区はどういうふうに考えているのでしょうか。その点についてはどうか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現時点でも、やはり待機児童が増えるという見込みの中で、年度途中なるべく早期に開設できるよう、事業者、そして私どもも開設の計画を早めるということを、今、念頭に置いて努力しています。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"早期にというのはいつのことですか。そこについて、どういうふうに応えようとしているのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほどご説明しましたとおり、予算プレスでもございましたとおり、私どもの早期というのは、まず確定している内容は７月です。さらに小規模保育等を含めて開設が早められないか、今、努力をしておりますが、まだこちらのほうはご案内する時期には来ておりません。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"７月だったら、４月、５月、６月の３カ月はどうするのですか。だから、今、開設をしていってくださいよ、緊急対策をとってくださいよと言っているのですけれども、そういう姿勢はないと見ていいのか尋ねました。","respondent":"金子子ども未来事業部長","answer":"説明は制度改革・待機児童対策担当課長が申し上げたとおりなのですけれども、６０人台から、昨年４月には１２８人。私どももこの状況はしっかり認識しておりまして、これについて、さまざまな総合的な手段をもってこの枠を拡大していこうと考えているところです。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、ちょっとやはりしっかりと確認しておかなくてはいけないと思いますので、ぜひ許してほしいと求めました。だから、そういう人をつくってしまうということに対して保育の実施責任という点でどう見ているのか、その辺を最後に聞いておきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これまでどおり、総合的な待機児童対策の中で、品川区が住民の方から求められる保育の実施について、今後も引き続き努力してまいります。やってまいります。","id":"exchange-040"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これも質問の一つでありますが、これまで私どもも待機児解消に向けて自民党としても強く要望し、この請願については願意に沿い難いです。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"今、そうした中でこの保育を求める方々の心に全力で応えていくということは、これまでも公明党としても力強く要望させていただいて。一人も出さないということを求めつつも、２のほうでは解消に向けという、求められているところの趣旨がいま一つ明確ではないかなというところ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"意見","question":"対策をとって、何とかこの解消に向け、区も取り組んでいる最中だということ。対策を講じて待機児ゼロに向け取り組んでもらいたいという思いでおりますので、この請願に関しては不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"南委員","kind":"提案","question":"あらゆる努力をしていないじゃないですか。私たちが提案したことをどこまで検討されたのか、やはりあまりにも無責任というか、住民の切実な願いに真摯に応えていくことが求められると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"高橋委員","kind":"意見","question":"先ほどあったように７月開園と、そのほかの小規模等を含めた受け入れ、これを早期にという答弁もありました。先ほど話があったように平成２７年度の計画を早期に努力されるということですので、私はこちらの請願の趣旨には沿い難いと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"この第９号は意見として不採択。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"解消に向けたことを公明党としても求めてきたということも含めて、これまで全力でそうしたことに対してもあらゆる提案を区にも申し上げ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"石田（し）委員","kind":"意見","question":"保育園増設、そういった支援策によって待機児の解消に努めてほしいという思いの中で、この請願においても不採択ということでお願いしたいと思います。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの質疑のところで質問しなかったのですけれども、全ての品川区内で開設している認可外保育施設については一刻も早く調査をしていただきたいと。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高橋委員","kind":"質問・要望","question":"私もそういったさまざまな対策で待機児の解消を求めてきましたし、先ほどお話ししたように早期にということで、対策がなされていると思います。２のほうの項目では、増設以外にも補助や支援で対策を行っているという点においても、請願趣旨に添い難いということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":38798,"voices":268}},{"id":"h27-20150223-5","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","agenda":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"これをもって１点だけ、この間の議論の中でもう一度だけ伺いたいのですけれども、これからの取り組み方というのでしょうか。渡された資料を見るときにこんがらがらないというのでしょうか、これは要望だけにとどめますので、これは要望だけしておきます。","respondent":"柏原行財政改革担当課長","answer":"こういったところを迅速かつ的確に対応していきたいといったところがあります。この部制について、ここの課題等に当たりながら行政を執行するです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"この条例の内容で、いろいろな第２条の関係の附属機関なのですが、条例の中にはそういう指示をするところがあるのでしょうか。もう１点ですが、わかる範囲なのですけれども、なぜ子ども育成課に変わったのかというところのご説明をお願いします。","respondent":"柏原行財政改革担当課長","answer":"今後の子ども・子育てに関するいろいろな計画を立てて、計画を今年度つくりますので、それをどういうふうに進めていくか。それから、会議をどうやって進めていくかといったところもありますので、そういった観点でこちらのほうに移ったといったものです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"要は、これら一覧のいろいろありますけれども、どこの部署に入っているのかというのがわかりやすく条例の中で明記はあるのでしょうか。いかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"私の説明がちょっとあれだったので、どういうふうに払うかというようなところを決めたものが、一括してまとめたものがこの条例です。このような形でご説明をする際に、この附属機関はどの所管になるかというのは、資料の中でお示しするというやり方は多分工夫であるかと思います。","id":"exchange-003"},{"speaker":"西本委員","kind":"提案","question":"そうすると、条例を見たときにわかりやすいような工夫もできるのではないかという提案なので、今後の検討という形でお願いしたいと思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"まさにこれ、内部的なことというのだったら、我々は何も言うことはないわけではないですか。ただ、この審議会はどこの所管なのということを明確にわかってほしいというのなら、照らし合わせていかなくては我々だってわからないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","agenda":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたい点だけなのですけれども、この独立行政法人が３法人に分類され、ここだけ少し解説していただけますか尋ねました。","respondent":"荒井広報広聴課長","answer":"そのうちの２行目の国家公務員の中に「独立行政法人通則法第２条第４項に規定する行政執行法人の役員および職員を除く」とあります。そのための改正です。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"よくわからないので教えていただきたいのですけれども、この第８条そのものが公開の義務を規定しているものでありますので、公開の義務を例えば緩めたり狭めたり、そういうものになるのか、ならないのであれば、そこを中心にもう１回ご説明いただけますか尋ねました。","respondent":"荒井広報広聴課長","answer":"失礼いたしました。公開の義務を定めているもので、この(2)については、それについては以前と変わりはありません。","id":"exchange-007"}]},{"id":"topic-03","title":"の第１１号議案 品川区行政手続条例の一部を改正する条例","agenda":"の第１１号議案 品川区行政手続条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１つ、また区民と業者というのでしょうか、ご説明ほしいと求めました。問題によってはいろいろ流れがあるのか、この手続後の対応というのはどういうふうな動きになるのか、そこを伺いたい。","respondent":"江部総務課長","answer":"各所管それぞれ考えられますけれども、やっていない、行政指導ですとか行政処分を求めていくというようなことが想定されております。どの条項で、どういう理由でというのは細かくしてという行政側に対して少し意識を重く受けとめなさいということで出るものだと認識しております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"相手は区民ですから、思料する場合ということで、そう思ったときというように実態に即しているのだと思うのです。やはり申出者に対してしっかり経過や処理の中身を報告するということは当然進めていくべきではないのかと思うのですけれども、その点はいかがか尋ねました。","respondent":"江部総務課長","answer":"申し出につきまして、各所管の状況の中できちんと調査をして対応していくということになるのだと思いますけれども、特に問題がないと思った場合に、何もしないかという部分につきましては、運用の中でこれを考えていくことになろうかとは思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味でも、その結果がどうなのかということも説明責任をしっかり果たすというスタンスをしっかり持っていかなければいけないと私は思います。今後、運用をされていく中で、そこは具体的に念頭に置いて進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"というのは、そこで摩擦が起きてしまったら大変なので、ただそれを今回、条文としてきちんと明記するということなのですか。それだけ説明を求めました。","respondent":"江部総務課長","answer":"これもそのまま横引きで第１項であるのですけれども、国民保護ということを考えたときに具体化した、より強くしたということになろうかと思います。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういうそれぞれのポストの身分というのでしょうか、身分保証といいますか、これはどういう関係にあるのか。質問としては、そういうふうに扱っているものなのか、そこを伺いたいと思います。","respondent":"江部総務課長","answer":"基本となります地教行法が改正されたことで、教育長が特別職に変わったという法の変更による形式的な整理ということになろうかと思います。区といたしまして改正をするものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"提案","question":"私が伺ったのは、今回の地方教育行政の改正とはまた別によく伺うわけですけれども、教育委員会のほうで今年はこういう予算を区長部局に提案しますと。","respondent":"江部総務課長","answer":"実際の執行は教育委員会でやっているということは、これは区長部局が評価することではなく、独立してやっていくものと考えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"やはり教育委員会が職責を果たすべき報酬だったり、いろいろな規定、それはそれにふさわしい中身にしていく必要があるというふうに思います。この地方教育行政の改正に伴って区長部局から教育委員会への権限介入というのは慎むべきだというふうに申し述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今回もいろいろ法改正があったということなのですが、そもそも教育長、今の教育長の給料額というのは、どういう規定になっていたのでしょうか。それから、第３条のところに、「１５人以内」という、これ、「以内」というふうにしたのは何か理由があるのか尋ねました。","respondent":"江部総務課長","answer":"副区長の給与の率の変更等ありました場合には、横並びといいますか、このような扱いをしてきたです。「１５人」を「１５人以内」ですけれども、そこまでいなくても適切な審議会運営ができるということで、自治体も組んでいないということにします。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"１５人いなくてもというのだったら何人がいいのですかという話になります。今まで１５人いなかったのに、なぜ１５人という数字にこだわるのかと、いかがか尋ねました。","respondent":"中山総務部長","answer":"このたびは一定の実態に応じて、その辺の運用というよりは、その中で一定の範囲でやっていく。基本的には１５人を目指すということだけれども、条例上きちんとその範囲を保っているという形をとろうということでやっているものです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"最後に１つ、現行と教育長の給料上に違いというのは大きく出て来るのか、来ないのかということだけお聞きしたいと思います。","respondent":"江部総務課長","answer":"実態は今までも審議会の対象ではないのですけれども、それを区長等の給与を横引きしているということはきちんとやってきたということになりますので、特に変わってくるものではないかと思います。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、この前、教育の改正の資料をいただいて、ちょっとだけレクチャーをしていただく機会がありました。第１４条、第１６条は、そこら辺のところをちょっと教えてもらいたいと思います。","respondent":"江部総務課長","answer":"第１４号議案につきましては、職務専念義務という扱いにつきましても、こういう特例法で扱わないというようなところもあるやに聞いております。表彰というのもないでしょうから、その辺は各区の実態もあるかと思います。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけど、特別職の報酬等審議会があるかどうかという、一部ないかもしれないからそれはわからない。１４とか１６については、額は品川区が今までやってきたことを踏襲しながら、それに見合った改正をしてきているという理解でいいのかどうかとの意見を述べました。","respondent":"江部総務課長","answer":"１６につきまして、１３につきましては、所要の改正だろうと思います。恐らく２３区なども全体調査をかけられるということは、報酬等審議会はそれぞれお持ちだと思いますので、同じような扱いになっています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"進んでいく方向性を考えると、品川区の報酬等審議会でも、その辺はしっかり議論してほしいと思います。それだけ意見を言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"ちょっと確認というか、よくわからないので教えていただきたいのですけれども、その辺はどのように捉えていらっしゃるのかお伺いしたいと思います。","respondent":"江部総務課長","answer":"教育委員会のトップであるということでありますので、そこでの職務代理ということは、教育委員会の特別職としての職務代理です。役割はそれぞれ違うというふうに認識しております。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"確認","question":"そういうことがきっと起こるのだろうと思っていて確認させていただいて、教育委員の中で教育長が今まで持っていたような職務を果たすということが果たして大丈夫なのでしょうかというところがちょっと心配、その辺はどのようにお考えか尋ねました。","respondent":"江部総務課長","answer":"選任について、今、議論をしています。それに対応できる方がどういう方がということは、まさに今、意見が交わされているところであるというふうに聞いております。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案を我々議会にしてくるときに、教育委員長がテレビとかの取材を受けたときに、私はよくわからないなどという人がなっている。そこら辺のところもぜひこれから皆さまがそういう形でやっていくのであれば、お考えいただくことも一つかということだけ言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-04","title":"の第１７号議案 品川区職員定数条例の一部を改正する条例","agenda":"の第１７号議案 品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"５歳児クラスの追加というのでしょうか、区民にも求められていると思いますので、今後もぜひ進めてほしいと求めました。例えば、今、念頭に置いている定数減や定数増や、そういう今後の見通しや考え方をどう考えているのか、そこだけ１点伺いたいと思います。","respondent":"堀越人事課長","answer":"そうでない部分とありますので、それをどう効率的に執行体制をとっていくかというのが検討していきながら進めていくというものです。保育士等増員を図る一方、工夫を図りながら減員を進めていくということですので、区政運営をしっかりと対応していくというのが考え方です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"５０とか、７０とかありますけれども、何か法則があって７０とかにするというのがあるのでしょうか。実態も含めて、これがどう反映されていて、運用に使われているのかということも含めてお伺いします。","respondent":"堀越人事課長","answer":"それから特別支援が必要な児童、在園児の対応ということで、用務職については減というふうに考えてあります。それから、育児休業の代替という形の職員が２０数名ぐらいの予定をしておりますので、そういった形であわせて弾力的に対応していくために一定数。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"そのノウハウとか、それについてはどういうふうにしていって、こういう７という減を決められたのかということをもう一度お聞きしたいと思います。そこをきっちりと行財政改革という意味も含め、考えながら人員配置、それから人数の設定はされているのか尋ねました。","respondent":"堀越人事課長","answer":"いろいろなインターネット関係等もかなり進んでまいりまして、より対応が可能になって、保育環境の充実につながるだろうというふうな考え方です。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"こういう理由なので用務員ではなくて別のほうをとっていきますというような説明をぜひ利用者の方々にしていただきたいというふうに思っております。人数はどうなのかというのは、当然、増やすところについてはしっかりと増やしていただきたいということで意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"現在、区民の人口が増えてきている中で、この２３区、とりわけ品川区でもこれから高齢化がますます加速すると思うのです。さまざまな事業も品川区は結構一生懸命やっていると思うのですが、これは大丈夫なのですよねというのをちょっと確認だけお願いいたします。","respondent":"堀越人事課長","answer":"４ページの表を見ていただきますと、見直しできるところは見直しをしていく、それが考え方です。きちんとした運営をする人数として算定しているところであります。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"指定管理をしたり、いろいろな部分で定数をその部分は減ってくるわけですから、それも１つの行革だという言い方でずっと来ていると思うのです。そうすると、まず民間の力の活用の部分と、それから人件費比率という地方自治体としての考え方の部分のところをお聞きしたいと思う。","respondent":"堀越人事課長","answer":"そういった必要なところの配置について一定考えを入れながらやっておりますので、そのような形でご理解をいただければというふうに思います。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは区長判断もあるでしょうから、ここで皆さまがどうということではないでしょうけれども、それは検討してほしいと求めました。そこら辺は頭の１割２割の余裕は、あとは政策判断で行くしかないかと思っているので、そこら辺のところのお考えがあればお聞かせ願いたい。","respondent":"中山総務部長","answer":"１つは、プラスアルファも図る中で、例えば民間の活用ができるかという検討も入ってくる要素かというふうに思います。その結果として、また定数のありようというものも決まってくる、このように考えております。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"頭の１割２割は少し余裕を持ってもらったほうがいい案が出てくるのではないかと思っている私がいるので、今、どう思われますか。変な質問で悪いけれども。","respondent":"中山総務部長","answer":"１つＤＮＡとして同じやり方を踏襲するのではなく、よりよい方法がないか、さらに成果を上げるためにということが脈々とある。それを反映していく、そういうものも一人一人の職員に全ていくようなことは組織的にもしっかりと保っていきたいというふうに思っております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"図書館の指定管理者制度はやめるべきだと思います。住民福祉を削る行革には反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","agenda":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"職員の方々の退職金を含めた形で考えると、大分下がるのではないかと思うのですけれども、それはどうでしょうか。〔「それは１９号議案」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"済みません。もう１つあるのですが、(2)の単身赴任手当のところですけれども、そこら辺を説明するよう求めました。","respondent":"堀越人事課長","answer":"単身赴任手当ですけれども、今現在は、宮古市被災地支援派遣で行っている職員が７名おりますけれども、そのうちの２名が単身赴任手当の該当になっているというものです。","id":"exchange-034"}]},{"id":"topic-06","title":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","agenda":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"かなりポイント制になって上がるというふうな感覚にはなるのですけれども、実際どうなのでしょうか。この適用区分の中に、保育園の園長先生はどの辺に入るのかと思っているのですが、それを説明するよう求めました。","respondent":"堀越人事課長","answer":"約３０万円ぐらいの増というふうな形ですとか、以下、課長の場合ですと１０万円弱ですとかの全体の増という形になってあります。より職層に応じた形でポイントを増やしていますので、その分、反映されているというふうに考えてあります。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":39946,"voices":182}},{"id":"h27-20150224-6","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"区民委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)ウーマンズビジネスグランプリ2015in品川","agenda":"はじめに、(1)ウーマンズビジネスグランプリ2015in品川","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"何点かお伺いしたいのは、審査員のメンバー構成はどういう形なのかということと、プレゼン審査の通過が８件となのですけれども、今回、１回から４回、４回目なので、通過件数の経過を教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"それから、高千穂大学の教授の方、趣旨を十分ご理解している方々に最終審査を行っていただくような考えで予定をしているものです。特に私のほうは、先ほどのご説明をさせていただいた審査基準を重点に見るようなことを立場として担わせていただいて、チェックをさせていただいて。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"２回、３回、４回までの最終プレゼンの件数をお伺いしたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"当日の発表をする時間等々もあって、第１回目からファイナリストは８名ということで、一応、原則として枠を決めております。過去３回、４回掛ける８名ということで、今までファイナリストの進出者は３２名というようなことになっているものです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問・要望","question":"それについて具体的に教えていただきたいのと、あとグランプリになった方たちが経過してどうだったかというようなことも、これを育てていく何か方策みたいなものはお持ちか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"ファイナリストの方の１年たってのプレゼンテーションというようなものも、お１人、２人というようなことで予定はしているものです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう形でのウーマンズビジネスグランプリというような中身のものをやっているところはほかにあるのかということを１つ教えていただきたい。そして、どういうふうにこれをＰＲしているのかというところも教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"武蔵小山の地域特性を考えますと、特徴ある創業支援センターにしようということで、武蔵小山創業支援センターが設立されたという経過があります。１０５件につきましては、今、手持ちではとれておりません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"実際のグランプリのところで８件という形で選ばれて、その後どうなっているのかというのは、品川区としてもフォローをされているのか。今後に向けての支援というところでは、どんなところが支援として必要なことなのか、そこら辺のところの考えをお聞かせいただければとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうしたところは武蔵小山創業支援センターの支援員なり、あと、やりとりをさせていただいたりというようなことをやっているものです。そういった形でご支援をさせていただいているものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後に残った８件はすごく選りすぐられたというふうなところだと思うのですけれども、書類審査の中を通過したのが２３件とか、こういうところまでも含めての相談とか支援とかというところについてはいかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"ファイナリストの８名のみ手厚くその後の創業支援をしているということではなくて、データもありますから、わかっているところなわけです。代表的にファイナリストの状況を説明したのですけれども、しっかりつないでフォローをするというようなことでやらせていただいております。","id":"exchange-006"},{"speaker":"木村委員","kind":"質問","question":"第１回から第４回までウーマンズビジネスグランプリということでやっているのですが、どうして女性だけのこういうグランプリが始まったのか。先ほど武蔵小山商店街にちなんで、関係があるというようなことでしたけれども、これがどうして男性はないのか、説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"さまざまな産業を支援する切り口の中で、武蔵小山創業支援センターの特徴としては、女性の起業に特化した支援をする場と区としては考えておりまして。","id":"exchange-007"},{"speaker":"木村委員","kind":"質問","question":"ここから卒業、グランプリをとったりした製品というものは、実際に販売をされているのかどうか。どうか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"現実に、先ほどのファイナリストでは２０名の方が起業していますので、そういうことで実際に小売をされているようなケースもあります。介護サービスを提供するとかという意味のサービス業として、しっかり業いをして頑張っていらっしゃるというような方々も大勢いらっしゃいます。","id":"exchange-008"},{"speaker":"木村委員","kind":"質問","question":"そういうものをこれから子どもたちだけのアイデアで、子どもたちのための何かをつくっていこうというふうな考えというのはどうなのですか。ありますか、ないか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした年代の方々と産学の連携等もあって、例えば品川区内では、北品川エリアに品川女学院という、そうした活動を一生懸命やられている高校もありますので、そういう意味での連携というのは、アイデアとして、いろんな交流というのは考えられるかなというふうに思っております。","id":"exchange-009"},{"speaker":"木村委員","kind":"意見","question":"ぜひ、それはお試しでも構わないと思いますし、子どもたちというのは、すごくそういうアイデア的なものというのは何か持っていると思うのです。これはただのアイデアですけれども、行政としてのそういう考えがあるかどうか、お願いしますとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"小学生の部でありますとか中学生の部あるいは高校生の部ということで、一般枠以外に区民枠という枠を設けて、区内の小中学生あるいは高校の方々から提案を受けてというようなことも同時にやらせていただいているところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"男女比率というのでしょうか、そこら辺の参加者の属性というのでしょうか、教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"今、会場が今回の新しいＳＨＩＰのイベントホールと同様の４５０平米で、椅子を並べますと３００人ほど入るキャパだと考えています。４０代の、これから起業を考えるような年齢の方が多いというふうに、感覚的にはそう思っております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"交流会ということで、参加費は２,０００円とあるのですけれども、これはどのような会なのかということ。自分もこれから何か起業を目指そうという方がいろいろ質問をしたりとかというための交流会だとは思うのですけれども、その概要については。","respondent":"山崎ものづくり・経営支援課長","answer":"ビジネスプランを発表した側、それから参加者といいますか来場者で交流をされたりというような形の希望者につきましては、一定のご負担をいただきながら、当日は会場で、会議室のほうでやらせていただくようなことを考えています。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"最後の質問をしますけれども、ちょっとはっきりしませんけれども、そういうような考えはあるのかどうか。現状と今後の見通しは。","respondent":"山崎ものづくり・経営支援課長","answer":"ウーマンズビジネスグランプリに協賛をいただいております団体を通じて周知をして、その団体の関係者にご参加をいただくという関係も多うあります。その中には、そうしたフレキシブルな交流の創出というようなことも交流会のほうでできればという狙い、観点はあります。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めてお伺いするのですけれども、区がなぜ区内創業者を重点にしないで、こういう形でやっていくのかという質問をしていました。３回やって、こういう形で効果は出ていますという答弁をいただきたいのと、こういう効果が出ているのですと。","respondent":"山崎ものづくり・経営支援課長","answer":"そういう意味では、そういう波及という意味ではあったということが１つ言えると考えています。いろいろ改善点はありますけれども、そうした意味では、取組みとしては効果を発揮したというふうに判断をしています。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、いつも区内産業にどういう形で効果が出ているかというのだけはしっかり押さえて、僕は賛成なのです。この二人の女性の起業というのは、どういうコンセプトなのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"伝わらなかったり、こういったものは難しいということは承知しておりまして、さまざま工夫をして作成をしてまいりたいとは思っております。手前の方は今、武蔵小山の１階でアンテナショップをやられて、関係者をポスターに使わせていただいているというのが実情です。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"説明を受けていないと、何なのになってしまうではないですか。書けないと思うけれども、そういうあれだったのですねということで、この質問は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５番のその他の女性起業家のテストマーケティングイベント「羽ばたけ！アントレーヌ」を同時に開催してということの中身をちょっと教えていただけますか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"その他のところ、説明を漏らしまして恐縮です。武蔵小山創業支援センターでいろいろ起業スクールをやって、そうした方々の商品とか、関連の方々が出展をされるというようなことです。","id":"exchange-017"}]},{"id":"topic-02","title":"品川産業支援交流施設「ＳＨＩＰ」内の貸会議室・多目的ルームの利用予約開始","agenda":"品川産業支援交流施設「ＳＨＩＰ」内の貸会議室・多目的ルームの利用予約開始","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは以前から、本当に高い利用料金になっているというのはここの中でも指摘したところなのですが、区民割引が１０％というところですね。そこの考え方と、１０％というところについてもなぜか、もう一回お聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"区民の方、区内企業の方の割引として、１０％、１割引きの区民割引というのは、制度として当初設定をしたものです。オープン前に協定を締結する予定になっておりますので、一定、その割引のプランなども考えていきたいというふうに思っております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"条例の上限そのものも変えていただきたいという思いもありますけれども、それから料金そのものを引き下げるというところでは、引き続きお願いしたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"２０２０年に向かっていって、せっかく開催されるわけですから、いろんな意味で品川区のアピールというのにも結びつくと思うのです。ですから、その辺も含めて、どちらの担当の方でも答弁は結構な。","respondent":"山崎ものづくり・経営支援課長、小川オリンピック・パラリンピック推進担当課長","answer":"場を１ついただいているということですので、大田区に負けない産業支援の品川区としての独自のアプローチの仕方というのもあると考えていますので。それも１つ、ここも国際的に… あらゆるチャンスを見つけて、品川区に開催競技場ができることもありますので、そういったことのＰＲをしていきたいとは考えてあります。","id":"exchange-020"}]},{"id":"topic-03","title":"住民基本台帳事務における特定個人情報保護評価の実施結果","agenda":"住民基本台帳事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"井上委員","kind":"意見","question":"今後のスケジュールの平成２７年度の作業工程のところで、４月の住民記録システム改修というところで、その辺の状況をお知らせくださいとの意見を述べました。","respondent":"井浦戸籍住民課長","answer":"現在予定されている国庫補助のシステム関連につきましては、平成２６年度に準備的な改修も行いまして、補助率につきましては１０分の１０です。","id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"後半のほうの社会保障と防災のほうのシステム変更というのは、単費予算で行われていくというものなのか、その辺はどうなっていますかとの意見を述べました。","respondent":"井浦戸籍住民課長","answer":"こちらにつきましては、現在、国のほうから、税につきましては補助率が示されておりまして、総経費の３分の２について補助するです。社会保障につきましては、厚生労働省所管になりますので、厚生労働省から国庫補助のものについては示されているです。","id":"exchange-022"},{"speaker":"浅野委員","kind":"質問","question":"１ページの第三者点検の実施結果の中で、人数はたしか３名だったと思うのですが、合計で５名で点検を実施するということなのでしょうか。この点、お伺いします。","respondent":"井浦戸籍住民課長","answer":"第三者点検の点検実施機関の構成メンバーについてのお尋ねです。弁護士ですが、弁護士の会長と情報工学の専門委員と学識経験者としての行政分野で情報システムに携われてきた方の３人で点検をいただいたです。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"その点を１つお伺いしたいのと、これは年に１回か２回ぐらい必ず発生していますけれども、この２点を説明するよう求めました。","respondent":"井浦戸籍住民課長","answer":"それぞれの情報安全については特定個人情報保護評価専門部会というものを設置していますので、こちらの３名の体制の中で情報安全については行うです。","id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"特に力点を置いて、これからも進めていってほしいと求めましたので、よろしくお願いします。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう中身で出すのかというところを教えていただきたいのと、その点が１点と、ここの委員会で報告を受けたことがあったでしょうか。その中身についてもお聞かせいただけたらと思います。","respondent":"井浦戸籍住民課長","answer":"「品川区は、特定個人情報ファイルの取扱いが個人のプライバシー等の権利利益に影響を及ぼしかねないことを認識し。それで、全項目評価書の公表、あるいはパブコメの回答についての公表ですが、３月中に公表するということで考えてあります。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろんな情報が統一されていくということにもつながっていくわけですから、これは本当に国民にとっても大きな影響を与えるものだと思うのです。６０ページもあるものですから、質問もできるような機会にしていただきたいということで要望もしたのですけれども、いかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"個人情報を取り扱う大事な仕組みになっておりますので、委員会等々でのご報告につきましても工夫をしまして、わかりやすい報告という形で心がけていきたいというふうに考えてあります。","id":"exchange-027"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"１日目の代表質問の部分で、プレミアム付区内共通商品券についてという質問への答弁の中で、その辺についての状況をお知らせほしいと求めました。","respondent":"米田商業・観光課長","answer":"規模の拡大も予定されていることから、取り扱いの小売店舗、ぜひこの機会にというようなことであったりとか。いわゆる大規模小売店舗へ取り扱いを拡大していくという趣旨でお答えしたものではございませんので、その辺のところはご留意いただければと思います。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"いっていなかったということでもっと拡大をするという趣旨なのか、その辺の、小売店舗の拡大の具体策みたいなものはあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-05","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"木村委員","kind":"意見","question":"先ほどの僕の発言の中で不適切なところがありました。それで、不適切な言葉がありましたので、それの取り消しをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"あべ委員長","kind":"確認","question":"私のほうから確認をいたします。先ほどの個人名を出されての発言の一部ということでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":29776,"voices":99}},{"id":"h27-20150224-7","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"厚生委員会","time":"午前１０時００分～午前１１時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"の品川区障害者計画・障害福祉計画","agenda":"の品川区障害者計画・障害福祉計画","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認させていただきたいのですけれども、障害者差別解消法に基づいた事由が見当たらないのですけれども、「品川区障害者計画・品川区障害福祉計画」が策定される前に法律が成立していると私は思うのですが、その法の趣旨はどういうところに反映しているかの確認を簡単にお願いします。","respondent":"中山障害者福祉課長","answer":"障害者差別解消法につきましては、平成２８年度から施行ということになっておりまして、この計画の中の期間に、当然、入っております。項目としては、こちらの９.障害者理解と共感のやさしいまちづくりのところに障害者差別解消法の考え方を盛り込んだところです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"しかも、あの法律の趣旨は達成できない部分があることがわかってきましたので、そのことについての品川区の見解をお伺いしたい。そうであるならば、「品川区障害福祉計画」の中でより具体化していくべきではないかと思いますが、合わせてお答えを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ここの具体的な書き方のところで足りない部分につきましては、事業の中で対応していきたいと考えています。そういった親の会とも連携しながら、具体的なイメージを持ちながら、この災害時の対応については考えてまいりたいと考えているところです。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"災害時における対応は、品川区が障害者の方々に関する情報を一元的に持っているわけですよね。そういう具体的なところまで話を落とし込んでいかないと、この支援体制の整備の目的が達成されないと思いますが、お考えを説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"今、そういったことも親御さんには協力して書いていただくようにするとともに、そういったところのご理解・ご協力も話してまいりたいと考えています。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"せっかく「品川区障害福祉計画」をまとめられたわけですから、それを品川区においては進めていっていただきますようにお願いしておきます。それから、例えば突発的に急に何らかの理由で移動支援が必要になるときもあるわけですから、その辺のお考えはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"最初にその方にとって月々当たりどれぐらいの移動支援の量が必要かということを、支給決定をして、その時間の付与の中で対応しているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"パブリックコメントですけれども、視覚障害の方向けにはどのような方法でされたのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"こちらの冊子につきましては、点字ではご用意はできておりません。それから、視覚障害者協会の会長にも、こういったことでパブリックコメントをやるので会員にご周知をお願いしますということでお伝えしたところです。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"災害の話が出たので確認ですけれども、その方たちが思っていらっしゃったのは、基本的には違いますよということは申し上げたのです。それが違うかどうか確認です。","respondent":"中山障害者福祉課長","answer":"委員おっしゃるとおり、一時的には避難場所に行っていただき、その中で対応が難しい方について、二次避難所、あるいは福祉避難所ということで、状態に合わせた避難所に移動していただくことになっております。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"その上で、先ほど伊藤委員からもありましたけれども、明らかに皆さんと同じ場所では最初から難しい方も多分いらっしゃると思います。難病があるという方で、では福祉避難所をどうやって開設するのかとか、その辺は防災課と今後連携をとっていくということでよろしいのか尋ねました。","respondent":"中山障害者福祉課長","answer":"福祉避難所や二次避難所につきましては、区内の社会福祉法人の施設などが指定されております。そことも連携しながら、実際に開設のシミュレーションをやりながら、ご利用者の避難の経路についても確認していければと考えています。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望ですけれども、誤解されているといけないので、比較的軽度な方は最初から分かれてではないのですよというところですよね。要望です、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"その避難所での生活をどう障害者がしていくのかというところでのマニュアル等を早急につくってほしいというところでは、障害を持たれた方が「では。ですので、そこにはぜひ応えてほしいと求めましたけれども、改めてお考えを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"どういった避難生活が送れるかはその場その場で違ってくると思いますので、それは個別のケースとしての対応をしていきたいと考えております。本当に災害がいつ起こるか、時間帯によっても随分とその対応は変わってくるので、そういった個別の作業を進めていければと考えています。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"就労支援もすごく障害者の方から多く出される要望ですけれども、なのでこうしていきますよという確保の方策がどこにあるのか伺いたいと思います。その具体化があるのか、もしないなら、何でないのかを教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"最初の避難に関してのご質問ですけれども、それぞれの障害者団体でも、防災の勉強会は実施しているところです。この中で、1)一般就労に向けての就労支援の強化ももちろんやってまいりますし、民間企業等からの受注増加に向けて支援しますというような形で。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"「では、死ねということなのですか」とも訴えられました。ではその場所を増やすのか、増設するのかというところまで考えて、または要望もされているのです。","respondent":"中山障害者福祉課長","answer":"そのサービスを使うというところでは、４７ページの障害福祉計画のところで就労継続支援Ｂ型がどれぐらい伸びていくかという数値も設けています。いろいろなお声は届くかと思いますが、今回の計画の中で説明を団体にもさせていただきましたが、つけ加えします。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私もここの要望を受けまして、現場も見て要望もしてきたので、そこを説明するよう求めました。","respondent":"中山障害者福祉課長","answer":"ただ１点、手すりが出っ張っていたために、車椅子でそのままトイレに入っていくことが難しかったと聞いております。施設整備課でも、多分、平成２６年度中にこちらは改修が進むものと考えています。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはりこういった当事者の声で個別に対応していただいているということだと思いますけれども、一つひとつ丁寧にやっていただいていると本当に思いますけれども、その声を集めるためのパブリックコメントと、さらに説明会もやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"提出人数１９名ということで、内容を見ると、提出された方は障害をお持ちの方がほとんどなのかと思いますが、出された方たちは、ある程度、そういう方が多いのか尋ねました。","respondent":"中山障害者福祉課長","answer":"多くはご自身が障害者、あるいはその親の方というのが多かったです。ただ、まちづくりのところで、障害者理解のことをするためにはこうしたほうがいいのではないかといった具体的なご意見もいただいているところです。","id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひとも今回のこのことを参考にして、１人ということでなく複数を委員に選んでほしいと求めました、これは要望です。7)移動支援事業が、パブリックコメントの１１ページにNo.３５「ヘルパーの増員をお願いしたい」という要望があって、その辺はいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"お２人の移動支援のヘルパーを使わなくても１人で済むというようなところで、今回、グループ支援という考え方も取り入れています。グループ支援でも対応できる方なのかどうなのか、できるだけ多くの方に移動支援事業をお使いいただけるような工夫をしてまいりたいと考えています。","id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"区としては中途聴覚障害の方に対しての研修事業は何かお考えになっていることは、私の見た感じではなかったものですから、何かお考えがあるのかどうか教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"ですので、今ご質問にありました中途障害の方が途中から手話を身につけようとすると、ここでは難しいということになっております。そういったところにつなげながら必要な手話を身につけていっていただいたり、あるいは相談も含めて、そういった対応をしていければと考えています。","id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"最初にお伺いしたいのが、パブリックコメント公表は広報しながわで来月２１日ということですけれども、この回答、区の考え方、ずらっと書いてありますけれども、これはこのままの文章で掲載されるということか尋ねました。","respondent":"中山障害者福祉課長","answer":"ホームページはそういった文字数の関係がないので、こちらのまま載せられるかと考えています。今回、パブリックコメントとしてまとめたものについて、障害者福祉課と区政資料コーナーに若干ご用意してお配りできればと考えています。","id":"exchange-017"},{"speaker":"向委員","kind":"質問","question":"根拠はわかりやすく区民に書いてほしいと思って、難しい意味でも、区の対応を目の当たりにする一つの機会になると思うのです。でも、そのあたりはもう少し熟慮したほうがいいのではないかと私は感じたのですけれども、この辺りについてお考えはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"確かに少し冷たいという感じがしないところもないとは言えないとも思いますけれども、書きぶりは難しいところがあって、今回このようにしています。","id":"exchange-018"},{"speaker":"向委員","kind":"意見","question":"あまり難しい根拠を述べ過ぎても区民の方はわからないとか、万人受けする回答はないと私も思っているので、この辺りは今後の意見ということで心に留めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"１つだけ確認ですけれども、パブリックコメントのNo.９に、病状が進行しなかったのではないかと感じることが多い」という表現があります。まさしくそれが書いてあるわけでありますから、それは進めていくべきだと思いますけれども、改めて確認ということでお願いいたします。","respondent":"中山障害者福祉課長","answer":"あるいは保育園・幼稚園から気になるお子さんということで親御さんに説明をして、そちらからまた相談ということでつながってきております。できるだけ多くの方が認識を持って早くからの療育につながるように、乳幼児期から就学期、就学期から成人期へとつながるように。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"ここに書かれていることは、すごく大きな、大切なことです。少なくなっていくわけだから、それは非常に大切なことでありますので、進めていっていただきますようとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-02","title":"の「しながわ健康プラン２１（素案）」のパブリックコメントの結果報告","agenda":"の「しながわ健康プラン２１（素案）」のパブリックコメントの結果報告","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"ふっと思い出したのですけれども、北海道のたしか旭川市だったと思いますけれども、「健康男子プロジェクト」を厚生委員会で視察に行きました。目標は職員の健康なのか、そういうことが具体的に向上していったということを示していく責務まで出てくると思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"今のご意見、非常に重要な視点だと思います。この計画も、品川区自らもこのような取組みをしていますという部分を、何らかの形で宣言する形の取組みもやっていく必要があると考えています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これに基づいて健康課長が中心になっていくのでしょうか、ＰＤＣＡでしょうか、非常にわかりやすい目標を出されていたわけです。せっかく行動宣言したら、その後の展開をぜひ検討していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"人事課の健康管理の担当の部門と連携をとりまして、こういった宣言をしていますので、今のご指摘の部分を踏まえましてしっかり取組みを進めたいと考えています。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この行動宣言は、今、後ろに４団体が出ていますけれども、２３団体、今は名前が出ていて、これがもう宣言した団体なのですよね。これは、ホームページなどに載せられているということでしたかとの意見を述べました。","respondent":"川島健康課長","answer":"２３団体全てが何らかの宣言をしていただいているということで、「しながわ健康プラン２１」の冊子に宣言の内容と団体を全部掲載する予定です。","id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"チェックリストは、今、冊子につけるとおっしゃられたのでしたか。もう一回伺いたいと思います。","respondent":"川島健康課長","answer":"冊子につけるのではなく、別な形で枚数を多くつくって、いろいろなところに置いていただくような形で考えております。その辺の使い方も踏まえまして、チェックの内容、項目を少し組み直しています。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"パブリックコメントのことをここでも言わせていただきたいのですけれども、こういった説明会をしますという周知はとても有効ではないかと思います。そして、それで多くの意見がまた戻ってくれば計画等にもさらに反映できるので、ここでも説明会を求めたいと思いますけれどもいかがか尋ねました。","respondent":"川島健康課長","answer":"実践をする委員と一緒に仕事をしておりますので、まずその方たちにこの「しながわ健康プラン２１」を説明して、そして活用していただくということで広めていきたいと考えております。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"向こう側にいる区民の皆さんはどう考えているのかは、説明会をお願いしたいと思います、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":25075,"voices":69}},{"id":"h27-20150224-8","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"建設委員会","time":"午前１０時００分～午後 ０時１８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、大崎駅西口バスターミナルの整備","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、大崎駅西口バスターミナルの整備","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今、お考えになっているところを伺いたいというところ。今度、高速品川線が開通しますけれども、これを見込んでというお話だと思うのですが、この関係性についてお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"都内４か所の同じようなバスターミナルがありますので、そういったところとの連携も図りながらになりますので、それから高速に乗っていくのか。それはちょっと今後の詳細な協議になってくるという形になるかと思います。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都内４か所というのはほかにどこがあるのか教えていただきたいのと、どれぐらい、その使用料というのを見込んでおられるのか。その辺についてご説明願います。","respondent":"溝口都市開発課長","answer":"箱崎にある東京シティーエアターミナル、そちらが都内では４か所、同じような形での事業認可をしています。それを収入としてしっかり入れられるような形で、今、バス事業者等との協議を進めているところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご紹介していただいた都内４か所は、非常にすごい話だなと今、改めて思いました。最後にちょっとお聞かせほしいと求めました。","respondent":"溝口都市開発課長","answer":"今後商業施設との施策の連携というのを図っていくというふうに考えておりますが、大崎に来て、そういった観光資源にも来ていただける。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこを一つ教えてほしいのと。１６３号線の関係で、周辺の影響とか交通量の影響とか対策とか、何か考えていることがあったら説明を求めました。","respondent":"溝口都市開発課長","answer":"ターミナルの容量としては１００台ほどバスがとめられ、運行できるようなターミナル機能を持たすような形をつくってあります。交通広場の中にバスがたくさんとまったりとか、出発するバスが混乱なくさばけるように、今、バス事業者と協議しています。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"今後どういうふうにご説明をするのか。その辺を説明するよう求めました。","respondent":"溝口都市開発課長","answer":"１００台の件なのですけれども、１日の容量、２４時間の容量になりますので、時間的に見ればそんなに多い形ではないと思います。地元町会長等には個別に本計画についてはご説明していますので、せっかくつくった施設、今後検討していきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も知っているのは新宿ぐらいですか、ターミナル。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"私は３点ほど、収益性事業が入ってくるわけですから、その辺のところが固まっているのか。国道１号にも接点を求めなくてはならないですけど、周りとの関係ですかね、その辺の整備状況を。","respondent":"溝口都市開発課長","answer":"さらに、周辺、五反田ですとか大井町、そういったところとどう連携するのか。観光施策とも連携した形でどういう形がとれるのか、それについては今後詳細に検討していきたいというふうに考えているものです。","id":"exchange-007"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、その辺のところでもう１回、もう少し全体を大きく考えてお返事いただきたいということ。これは通行の、単純に言ってしまうと道が狭いんじゃないのという感覚があるものですから、その辺のところについてお話をいただきたい。","respondent":"溝口都市開発課長","answer":"そういったところも含めて今後検討していきたいと考えています。これにつきましては、引き続き都市開発課のほうでさまざまな部署と連携しながら、よりよいまちづくりを進めていきたいと考えているものです。","id":"exchange-008"}]},{"id":"topic-02","title":"北品川五丁目第１地区再開発事業","agenda":"北品川五丁目第１地区再開発事業","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２４年からということで、一つお伺いしたいのは、区の所有している床がどこの建物にどの程度あるのかというのをもう１回教えていただきたい。","respondent":"溝口都市開発課長","answer":"その中で、経緯として、もともと持っている権利変換を受けている床といたしましては、まずは(1)大崎ブライトタワーの３階のホールの部分の床。それと(2)の事務所施設、それが区の権利変換で受けた施設となっているものです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"この３６０席のホールというのがちょっと具体的にどういうふうに使われるのか教えてほしいのと、この床というのはどういう経緯でどうなったのか。改めてもう１回お伺いいたします。","respondent":"溝口都市開発課長","answer":"これは上の４階の産業支援交流施設とあわせて一体的に所管課のほうで指定管理者を定めまして、運営していくような形になっております。一応２分割して使えるようにはなっていますが、会社説明会、そういったものにも使えるような施設のしつらえになっているものです。","id":"exchange-010"}]},{"id":"topic-03","title":"品川区の環境に関する各計画の実績報告等","agenda":"品川区の環境に関する各計画の実績報告等","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これを民間でやるということを推進するということなのでしょうか。合わせて３点お伺いします。","respondent":"三ツ橋環境課長","answer":"６ページの重点プロジェクトのアサヒビールにつきましてですけれども、東京都経由でアサヒビールから寄附をいただいております。３番目のカーシェアリングにつきましては、大分、その動向を見ながら活用してまいりたいと考えています。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"では、保健センターは３０％削減というのはすごいのですけれども、この省エネ設備の導入というのは、最新の機器を使っていると思うのですが、例えば具体的にどんなものを使ったのか、ちょっとイメージがわかないので、そこだけ教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"省エネ設備というのと、民間のＢＥＭＳなどを導入しておりまして、そちらで大分省エネとして削減はしております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"１点お伺いしたいのが、１ページ目の最初の１の(1)のところの基準年の考え方というか、平成２１年、２００９年を基準年としてその後の経緯が書かれているのですが、なぜ平成２１年なのか、基本的なところを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"直近の実績があります平成２３年度、２０１１年を基準年とすべきですけれども、非常事態体制で節電に取り組んでおりました。平成２２年度につきましては、猛暑の影響がございまして、ＣＯ２排出量が大きく増加したことから、平成２１年度を基準年としております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"そのときの基準年というのはいつも同じような考えで、その５年間の中で基準を持っていくという考えなのでしょうか。その辺を説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"基準年としては平成２１年度を基準としておりまして、こちらは前年度比を１％削減していこうというふうに見ております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"普通だったら５年計画だったら頭の年とか、全体的にどうなのかというのが見えないので、ちょっと基本的なところでとの意見を述べました。","respondent":"三ツ橋環境課長","answer":"この第三次実行計画といたしましては、基準年を平成２１年度としております。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"実行計画と見直案が４倍になって、この３ページにおいては、なぜ４倍近くなったかというところを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"それの総体的なＣＯ２の係数となっております。総体的なものは変えずに、施設ごとの総排出量を見直しました。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"３ページの表だと平成２１年、これは２ページは平成２１年、アとイとはリンクしていると思うのですけれども、平成２１年度を基準にした場合、この数字が違うのは何でなのですかということです。","respondent":"三ツ橋環境課長","answer":"こちらにつきましては、対象となるものが違っておりまして、そのトータルを見直しますと、こちらのＬＰＧが、対象となる施設が増えて……。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"そこの今、所長がおっしゃったように、入れるべき、入れないべきというのは、入れる入れないという基準はどういう基準に基づいて算入をされているのかを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"１ページの下にあります対象となる分は、こちらの計画の見直しの中でお伝えしたように、品川区地球温暖化防止対策実行計画の策定の後、環境省から発表された手引きに基づいて対象としております。","id":"exchange-018"}]},{"id":"topic-04","title":"水銀混入ごみによる品川清掃工場１号炉の停止","agenda":"水銀混入ごみによる品川清掃工場１号炉の停止","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"こういうもので、家庭的にはどういうところに使われているのか、業務的に。家庭的なものと、主にどういったものに水銀というのは使われているのか、わかっている範囲で説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"ちなみに、それに対する対応なのですけれども、品川区では他区に先んじて、蛍光灯、体温計等を資源として回収しております。もちろんこれを機に、医療系への協力依頼、業者収集での協力等も区民への協力とあわせてお願いしてまいりたいと考えています。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひ、そういったたった１個や何かの出し方の誤りで全体がとまってしまうということが大変な損害ですので、ぜひ働きかけもしてほしいと思いますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-05","title":"五反田ふれあい水辺広場等における平成２７年社会実験","agenda":"五反田ふれあい水辺広場等における平成２７年社会実験","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"何で売り上げが上がったのかというところでの区のお考えというか、その辺について伺いたいと思います。特に品川区の水辺というところでの、品川区というところに何かこだわりがあっての仕掛けみたいなものがあるのかどうかという点を説明するよう求めました。","respondent":"奥田河川下水道課長","answer":"もう１点が、区と一緒に季節ごとにイベント等を実施していこうということで、例えば防災まつりとか。３点目は、当然にぎわいとふれあい、水に親しんでもらうところを生かしていければというふうに考えてあります。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。そういう意味では本当に一生懸命やられているんだなというふうに感じますので、大切に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問・要望","question":"その他のところで、等というのは好きな字なのですけれども、等をもう１回細かくというか具体的に説明をしていただきたいのが一つ。普通、休みのときに一番書き入れのような気がするのですけれども、なぜ土日がここのところが抜けているのかを説明をしてほしいと求めました。","respondent":"奥田河川下水道課長","answer":"１点目の、３のその他のところの「等」ですが、そういったものを「等」ということで考えてあります。２点目の平成２５年度と平成２６年度の土日がないところですが、やらないときというのは、地元と調整しながらやっているところです。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"そこらをどのように外国の方に広めていくのかというビジョンというか、方策というか、戦略があったら説明を求めました。","respondent":"奥田河川下水道課長","answer":"まず地元の方にあるいは地域に根づいて区民の方に、国内の人にまず来ていただいて、にぎわいを出していきたいと思ってあります。外国人ということは、そういった国内外の観光客にも当然親しんでいただきたいと思ってありますので、こちらは今後調整していきたいと思ってあります。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"そこらの利用者の情報端末ツールに対して取り組みをするというような戦略の一部分なのですけれども、そこらのところについてどのような考えを持っているのか、説明を求めました。","respondent":"奥田河川下水道課長","answer":"多言語表記などをして、より来ていただくような形ということでいろいろ工夫していくところというのは当然あると思ってあります。委員からお話があったように、積極的に進めていくということで思ってありますので、その辺は調整したいと思っていますのでよろしくお願いいたします。","id":"exchange-025"}]},{"id":"topic-06","title":"防災地図（関係機関用）の配布","agenda":"防災地図（関係機関用）の配布","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"防災の関係の質問になってしまうのですけれども、そういうふうに考えていくのかとか、そこら辺についてのお考えをお聞かせいただきたい。その２点お伺いいたします。","respondent":"鈴木防災課長","answer":"自衛隊のヘリ、常設の指定はできないにしても、実際には一定程度荏原の方面にもヘリの発着はできるだろうということで考えております。","id":"exchange-026"}]},{"id":"topic-07","title":"平成２６年度「品川区地域防災計画の修正」","agenda":"平成２６年度「品川区地域防災計画の修正」","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"現在は崖消滅により４０か所ということで、今まで４３か所と伺っていたのですけれども、これは今後は４０か所ということでよろしいのでしょうか。区独自の体制をとっていくと、先んじてやっていくという、そういう考え方でよろしいのか尋ねました。","respondent":"鈴木建築課長","answer":"その辺の都の動きと連携協議をしながら調査を進めていきたいですけれども、基本的には今回、継続して都が指定するまではやっていくです。数字を今のところ公表することは予定としてはないのですけれども、３か所が実際もう、４０か所が実体的な崖だというところで把握しています。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１９号のときに避難準備情報というところで、混乱を起こさないように知っていただけるような形で周知に取り組んでいってほしいと求めました。この二つをお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"ただ、区民の方への説明につきましては、全体計画の検討もありますので。２点目の特に配慮を要する者という定義ですが、自分の努力で対応ができない方という意味で、特に支援という表現をしているというものでございまして。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"特に、(4)の災害時要援護者対策のところで、今日のところでは要点のところで名簿の作成が区市町村の義務になった。今回のところはそこは全然含まれていない、検討はそこまでは至っていないということなのか、ちょっとそこの関係を説明するよう求めました。","respondent":"鈴木防災課長","answer":"要配慮者の方の対応全般ですが、避難行動要支援者という名前になっておりますが、それに沿いましてしっかりと漏れのないように対応していくことになっております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、そこの修正の部分も今後、配布をされるというか、差しかえになっていくということなのか尋ねました。","respondent":"鈴木防災課長","answer":"今でいう要援護者の方についての対応は、それを改めて新しい定義に合わせて整理をし直しまして、計画のほうの修正はほぼ完了しております。今後は先ほど申し上げましたように、地域防災計画の下位計画として避難行動要支援者の方に関する全体計画の作成。","id":"exchange-030"},{"speaker":"若林委員長","kind":"質問・要望","question":"呼びかけチラシの個別配布、これは丁寧に１軒１軒伺うということで現場を見させていただいて、大変に来ていただいた方は心強くご協力いただきました。そこについて、また、一般質問等でやったと思いますけれども、明確な答弁がなかったので、要望も含めてお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"昨年の場合には６か所で２００世帯でしたので、現在あるもの、伝達方法については少し強化する必要があるというふうに認識をしております。自主的な避難というのも含めて、両方のそういう認識を高めることで、より安全な対応ができるようにしたいというふうに考えております。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"昨年の今ごろですか、その方が１週間エアコンが使えなくなって、それはもうそのとおりだと思うのです。間の部分がやはりないと、私はそのとき考えたものですから、ぜひその辺についてのお考えをお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"ボランティアを否定するものではありませんが、そこにつなぐための一つの仕掛けとしてボランティアも有効な制度であるというふうに考えております。その辺も整理をしながら地域の自助・共助が進むように、今後もしっかりと普及啓発していきたいというふうに考えております。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"意見","question":"やはり３７万区民がいるこの品川区において、そうでない方でやはりどういうふうに、町会に所属をしていく。そこのところをどういうふうに守っていくのかというところ、この観点も非常に大事ではないかなと感じておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"事業所さんでとても積極的に防災にかかわってくださっているところも増えてはいると思うのですけど、事業所というのはとても幅が広いですよね。いっぱいあるので大変だとは思うのですが、この辺がどの辺まで進んでいるのか、課題だとかがどうなっているのか説明を求めました。","respondent":"鈴木防災課長","answer":"特に多くのお客様等が集まる施設についての対応状況ですが、各事業者の方もかなり今、意識が高まってきていると感じております。事業者の方、まだ全てに行き渡っているとは申し上げられませんが、かなり意識が高まって活動も具体化してきているというふうに感じているところです。","id":"exchange-034"},{"speaker":"大倉副委員長","kind":"意見","question":"環境づくりという部分ではしっかりやっていっていただいているところだと思います。こういったところを区としてどんどん増やしていっていただければなと思っていますが、その辺について何かお考えというのはありますかとの意見を述べました。","respondent":"鈴木防災課長","answer":"大崎第１地区と品川第２地区には、そこでの訓練等が実施されておりまして、かなり主体的に活動をしていただいております。今後もその協定の協力であったり、地域への訓練参加や協力というところでしっかりと働きかけをしていきたいというふうに考えております。","id":"exchange-035"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"この自助・共助の環境づくりに向けて、防災訓練であったり、応急活動ができる環境づくりを進めていっていただきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-08","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１２月の建設委員会でご報告をいただいて、その際にも区民の皆様にぜひしっかり周知をお願いしますということでお願いさせていただきました。３月末に住民説明会をやられるということですけれども、住民の方、ぜひ皆様の感情等に配慮をされながら丁寧なご説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"ごめんなさい、追加で一つだけ。先ほどの確認ですけど、平成２７年度末までに工事を終了するのは、これは全ての工事を終了する予定ということでよろしいですか、調査だけではなくて。","respondent":"多並公園課長","answer":"今のお話のとおり、来年度末、平成２８年３月までの完成を目指し、なるべく一日も早く工事が完成するよう今、設計作業を進めておりますので、それがまとまり次第、最終的なスケジュールが明らかになるところです。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4134#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":45660,"voices":142}}]);
